// Kiswahili — version 1, written in for en.help-app.ts (2026-11-03). Fetched only when the language is chosen
// (shared/i18n/index.ts); a country's own review is laid over it, and this stays as written. Generated: edit the review, not this.
export const words: Record<string, string> = {
  "help.people-at-work.title": "Ongeza watu wa kaunta au wa sakafuni",
  "help.people-at-work.summary": "Watu wanaofanya kazi kwenye kaunta ya duka au sakafuni mwa kituo huingia wao wenyewe, kwa simu yao na PIN yao, na kila mmoja anachofanya huhifadhiwa kwa jina lake.",
  "help.people-at-work.step1": "Mmiliki — akiwa ameingia kama duka au kituo — anafungua Watu wa kaunta (programu ya Shop) au Watu wa sakafuni (programu ya Hub) kwenye skrini ya mwanzo, na kuongeza mtu kwa nambari yake ya simu na jina analotumia.",
  "help.people-at-work.step2": "Mtu huyo anakubali akiwa ameingia kwenye SeeBuyGet yeye mwenyewe. Kisha, kwenye simu ya duka au ya kituo: “Ninafanya kazi kwenye kaunta hapa” au “Ninafanya kazi sakafuni hapa”, kwa nambari yake na PIN yake.",
  "help.people-at-work.step3": "Anachofanya huhifadhiwa kwa jina lake, katika “Nani alifanya nini” mahali hapo hapo. Ada, pesa, saa za kufungua na watu hubaki kwa mmiliki: hayo hayaonyeshwi kwake, na akijaribu anakataliwa.",
  "help.people-at-work.step4": "Ukimwondoa mtu, anatolewa mara moja, popote alipoingia.",
  "help.people-at-work.note1": "PIN ya mtu ni yake: usiwahi kuiomba, na usiwahi kuwapa watu wanaokufanyia kazi nenosiri la mmiliki.",
  "help.risk-register.title": "Njia kuu na vituo vilivyokadiriwa hatari kubwa",
  "help.risk-register.summary": "SeeBuyGet hukadiria kila njia kuu na kila kituo kuwa na hatari ndogo, ya wastani au kubwa ya wizi mdogo mdogo, utekaji wa magari, machafuko na unyang’anyi kwenye vizuizi vya barabarani, na hukagua kila ukadiriaji tena kila robo mwaka. Palipokadiriwa hatari kubwa, vifurushi husafiri tu ndani ya mifuko iliyofungwa kwa lakiri yenye nambari, na hakuna kinachosafiri usiku.",
  "help.risk-register.step1": "Hapa chini, kila njia kuu na kila kituo pamoja na viwango vyake vinne. “Kadiria” huviweka, pamoja na sababu; “Bado ni sahihi” wakati kiwango kimefikia ukaguzi wake wa robo mwaka. Kila kimoja huwekwa tarehe kwa jina lako.",
  "help.risk-register.step2": "Njia kuu iliyokadiriwa hatari kubwa: duka halikabidhi kifurushi kilicho huru kwenye njia hiyo — viweke kwenye mfuko, na ufunge mfuko kwa lakiri yenye nambari — na hakuna kinachoingia humo kati ya 19:00 na 06:00, kwa saa ya mahali duka au kituo kilipo.",
  "help.risk-register.step3": "Kituo kilichokadiriwa hatari kubwa: mfuko hutoka humo tu ukiwa na lakiri yenye nambari, na hakuna unaopakiwa humo kati ya 19:00 na 06:00. Kituo huarifiwa kwenye kengele yake kiwango chake kinapobadilika, na vivyo hivyo kampuni ya magari inayoendesha njia kuu hiyo.",
  "help.risk-register.note1": "Programu ya Shop na programu ya Hub: ukataaji unasema ni njia kuu au kituo kipi kimekadiriwa hatari kubwa, kwa hatari gani, na kipi kinaruhusu vifurushi kwenda — mfuko wenye lakiri, au asubuhi.",
  "help.security-declaration.title": "Tia sahihi tamko la usalama",
  "help.security-declaration.summary": "Kila duka, kituo, kampuni ya magari na mwendeshaji asiye katika kampuni ya magari hutia sahihi tamko fupi la usalama: jinsi wanavyotunza kilicho chini ya uangalizi wao. Hutiwa sahihi wanapojiunga na tena kila mwaka. Bila tamko linalotumika, hakuna kipya kinachopokelewa — kilicho mikononi mwao tayari humalizwa kama kawaida.",
  "help.security-declaration.step1": "Programu ya Shop, Hub, Fleet au Driver: kwenye skrini ya mwanzo, tamko — ahadi chache. Zisome kisha ubonyeze “Natamka hivi — tia sahihi”. Linatiwa sahihi kwa jina lako, leo, kwa mwaka mmoja.",
  "help.security-declaration.step2": "Mwezi mmoja kabla mwaka haujaisha, skrini ya mwanzo inasema linaisha, na siku gani. Litie sahihi tena wakati huo; hakuna kinachosimama kwa sasa.",
  "help.security-declaration.step3": "Halijatiwa sahihi, au mwaka umepita, au kuna maneno mapya ambayo SeeBuyGet imeandika: duka halipokei kifurushi, kituo hakifungui mfuko mpya, na madereva wa kampuni ya magari au mwendeshaji asiye katika kampuni ya magari hawachukui mzigo, kifurushi au mfuko mpya. Kila ukataaji unasema mahali pa kutia sahihi.",
  "help.security-declaration.note1": "Madereva wa kampuni ya magari hawatii sahihi chochote chao wenyewe: kampuni hutia sahihi, na huwajibika kwa ajili yao. Dukani, mmiliki ndiye hutia sahihi — si watu wa kaunta.",
  "help.new-partner-limit.title": "Kikomo cha duka au mwendeshaji mpya",
  "help.new-partner-limit.summary": "Pale kampuni ya nchi yako imeweka kikomo, duka jipya hushikilia vifurushi visivyozidi idadi fulani kwa wakati mmoja, na mwendeshaji mpya asiye katika kampuni ya magari hubeba visivyozidi idadi fulani. Kikomo hukua kwa kila kifurushi unachokabidhi, na huondoka ukishakabidhi vya kutosha.",
  "help.new-partner-limit.step1": "Programu ya Shop: skrini ya mwanzo inasema unashikilia vifurushi vingapi, kikomo chako sasa, na jinsi kinavyokua. Ukifika kikomo chako, kifurushi kinakataliwa wakati wa kupokea, na skrini inasema kwa nini.",
  "help.new-partner-limit.step2": "Programu ya Driver: Mizigo yangu inasema unabeba vifurushi vingapi na kikomo chako sasa. Ukifika kikomo chako, duka huhifadhi vifurushi vilivyobaki kwa ajili ya mwendeshaji anayefuata, na huwezi kuchukua mzigo hadi ukabidhi kimoja.",
  "help.new-partner-limit.step3": "Kila kifurushi unachokabidhi — kwa dereva, kwa mtu anayekichukua, au kilichofikishwa — huongeza kikomo chako kwa kimoja. Baada ya idadi iliyowekwa na kampuni yako, hakuna kikomo kabisa.",
  "help.new-partner-limit.step4": "Mwendeshaji wa baiskeli au pikipiki asiye katika kampuni ya magari: hadi SeeBuyGet itakapoona picha ya ID yako, kikomo chako kinabaki pale kilipoanzia. Programu ya Driver, skrini ya mwanzo: “Tuma picha ya ID yako”. Unaarifiwa ikishaonekana — tangu hapo kinakua kama ilivyoelezwa hapo juu — au kwa nini haikukubaliwa, nawe unatuma nyingine.",
  "help.new-partner-limit.note1": "Madereva wa kampuni ya magari hawana kikomo cha aina hiyo: kampuni yao inawajibika kwa ajili yao. Kama kuna kikomo, na idadi zake, ni juu ya kampuni ya nchi yako kuamua.",
  "help.change-password.title": "Badilisha nenosiri lako",
  "help.change-password.summary": "Libadilishe wakati wowote huenda limeonekana — unahitaji lile la sasa ili kufanya hivyo.",
  "help.change-password.step1": "Kwenye programu ya Shop au ya Hub: kitufe cha duara juu, kisha “Mipangilio › Badilisha nenosiri lako”.",
  "help.change-password.step2": "Andika nenosiri lako la sasa, kisha jipya mara mbili. Linahitaji angalau herufi 8, na haliwezi kuwa lile rahisi kukisiwa: neno la kawaida lenye nambari mwishoni, jina lako au anwani yako ya barua pepe, tarakimu pekee, au mfuatano kama 12345678.",
  "help.change-password.note1": "Kila simu au kompyuta nyingine iliyo bado imeingia kwa nenosiri la zamani inatolewa mara moja. Ile uliyotumia inabaki imeingia.",
  "help.change-password.note2": "Nenosiri la sasa lisilo sahihi hapa linahesabiwa kama lisilo sahihi wakati wa kuingia: makosa matano hufunga akaunti kwa muda.",
  "help.change-password.note3": "Kubadilisha nenosiri, au kuweka upya lililosahaulika, huzima kufungua kwa alama ya kidole au uso kwenye kila simu ya duka au ya kituo. Kunaweza kuwashwa tena chini ya Mipangilio.",
  "help.fleet-code.title": "Pata msimbo wa kampuni yako ya magari au toa mpya",
  "help.fleet-code.summary": "Msimbo hutaja kampuni ya magari tu wakati wa kuingia. Kamwe hauongezi mtu yeyote kwenye kampuni yako. Toa mpya ikiwa umeshirikiwa na watu ambao hawapaswi kuwa nao tena.",
  "help.fleet-code.step1": "Programu ya Fleet: “Dashibodi › Msimbo wa kuingia wa kampuni”. Gusa Onyesha ili kuusoma.",
  "help.fleet-code.step2": "Gusa “Toa msimbo mpya” na uthibitishe. Msimbo wa zamani unaacha kufanya kazi mara moja.",
  "help.fleet-code.step3": "Waambie mameneja wengine wa kampuni yako msimbo mpya. Hakuna anayetolewa: simu zao na PIN zao bado zinafanya kazi.",
  "help.fleet-code.note1": "Kadi inasema msimbo ulibadilishwa lini mara ya mwisho, na inapendekeza mpya ukishapita siku 90.",
  "help.fleet-roster.title": "Ongeza au ondoa dereva kwenye kampuni yako ya magari",
  "help.fleet-roster.summary": "Unaongeza dereva mpya wewe mwenyewe. Dereva ambaye tayari yuko kwenye SeeBuyGet hujiunga tu unapompa nafasi naye akakubali.",
  "help.fleet-roster.step1": "Mpya kwenye SeeBuyGet: “Madereva › Sajili dereva”. Andika maelezo yake na nambari ya simu atakayoingia nayo.",
  "help.fleet-roster.step2": "Tayari yuko kwenye SeeBuyGet: “Madereva › Mpe nafasi dereva aliye tayari kwenye SeeBuyGet”. Andika nambari ya simu anayoingia nayo na uguse Toa nafasi.",
  "help.fleet-roster.step3": "Anaona nafasi hiyo kwenye programu yake ya Driver na anakubali au anakataa. Mpaka akubali, unaona tu nambari uliyoandika.",
  "help.fleet-roster.step4": "Ili kuondoa dereva: “Madereva › Ondoa kwenye kampuni” kando ya jina lake. Chagua sababu; ataonyeshwa sababu yako.",
  "help.fleet-roster.note1": "Nafasi uliyotoa hubaki wazi kwa siku 7. Unaweza kuirudisha ikiwa bado iko wazi.",
  "help.fleet-roster.note2": "Dereva anayebeba mmoja wa mizigo yako, au aliyepangwa kwenye mojawapo ya safari zako, hawezi kuondolewa hadi mzigo ufikishwe au urudishwe na mtu mwingine awekwe kwenye safari hiyo.",
  "help.fleet-roster.note3": "Dereva unayemwondoa hubaki na safari zake, hati zake na ukadiriaji wake. Kila safari aliyokufanyia hubaki kwenye kumbukumbu zako.",
  "help.fleet-roster.note4": "Madereva wako pekee ndio wanaoweza kuanza zamu kwenye magari yako.",
  "help.fleet-roster.note5": "Unachagua gari la dereva chini ya Zamu; linakwenda juu ya orodha yake na anaarifiwa. Dereva huanza zamu mwenyewe, kwa PIN yake. Hakuna anayemwanzishia mwingine zamu.",
  "help.fleet-roster.note6": "Dereva anaweza pia kuondoka mwenyewe, kutoka programu yake, zamu yake ikishaisha na hakuna kitu mikononi mwake. Unaarifiwa kwenye kengele, pamoja na safari zako zozote ambazo sasa hazina dereva. Safari ambayo bado haijaondoka haimzuii: weka mtu mwingine juu yake.",
  "help.driver-fleet.title": "Jiunga na kampuni ya magari au uiache",
  "help.driver-fleet.summary": "Kampuni ya magari inakuchukua kwa kukupa nafasi. Unakubali au unakataa kwenye programu. Hakuna msimbo unaoandikwa popote.",
  "help.driver-fleet.step1": "Ipe ofisi ya kampuni ya magari nambari ya simu unayoingia nayo.",
  "help.driver-fleet.step2": "Wanapokupa nafasi, inaonekana kwenye skrini yako ya mwanzo, na chini ya picha yako, kisha Kampuni yako ya magari.",
  "help.driver-fleet.step3": "Gusa “Endesha kwa” na jina la kampuni ili kukubali, au “Hapana, asante”. Ni wewe tu unayeweza kujibu, ukiwa umeingia mwenyewe.",
  "help.driver-fleet.note1": "Huwezi kukubali ukiwa kwenye zamu, ukibeba mzigo, au ukiwa umepangwa kwenye safari ya kampuni yako ya sasa. Programu inasema umalize nini kwanza.",
  "help.driver-fleet.note2": "Leseni yako, safari zako na ukadiriaji wako huja nawe. Kampuni unayoiacha hubaki na safari ulizoifanyia.",
  "help.driver-fleet.note3": "Kampuni ya magari ikikuondoa, programu inasema ni nani na kwa nini. Huwezi kuanza zamu hadi kampuni nyingine ikupe nafasi, au uchague kujiendeshea mwenyewe.",
  "help.driver-fleet.note4": "Unaweza kuiacha kampuni ya magari mwenyewe: jina lako juu, kisha “Kampuni yako ya magari › Ondoka” na jina la kampuni. Hakuna ruhusa ya mtu inayohitajika. Maliza zamu yako kwanza, na ufikishe au urudishe chochote unachobeba; programu inasema kinachozuia bado. Ofisi yao inaarifiwa. Ukiwa kwenye mojawapo ya safari zao ambayo bado haijaondoka, unaondolewa kwayo. Baada ya kuondoka huwezi kuanza zamu hadi kampuni ya magari ikupe nafasi, au uchague kujiendeshea mwenyewe.",
  "help.driver-fleet.note5": "Skrini ya mapato yako inasema nani alilipwa. Ukiwa katika kampuni ya magari, pesa huenda kwa kampuni yako. Usipokuwa katika kampuni, inasema kwamba ulichopata ulipokuwa ukiendesha kwa ajili ya kampuni kililipwa kwa kampuni hiyo, na kwamba hakuna unachodai kwa ajili yake. Pesa zilizokufikia kwa kazi uliyofanya mwenyewe zinaonyeshwa kando ya mojawapo ya hayo.",
  "help.driver-fleet.note6": "Kujiendeshea mwenyewe: ukiwa huna kampuni ya magari na unaendesha baiskeli au pikipiki, Kampuni yako ya magari ina “Endesha kwa ajili yako mwenyewe”. Chagua nchi unayoishi — kisha programu inataja kampuni ambayo ungeendesha kwa ajili yake — sema gari lipi ni lako na uandike nambari yake ya usajili. Inafanyika mara moja: gari liko kwenye skrini yako ya kuanza, na tangu hapo unalipwa moja kwa moja. Leseni yako, safari zako na ukadiriaji wako hubaki kama zilivyo. Kwa gari dogo la mizigo, lori au chochote kizito kuliko pikipiki ni ombi: ongeza picha ya kadi yako ya ID na ya leseni yako ya udereva (na ya bodi ya lori), kisha “Omba kujiendeshea mwenyewe”. Wafanyakazi wa SeeBuyGet wanasoma zote mbili na kukagua rekodi yako; hadi waamue hakuna kinachobadilika, na Kampuni yako ya magari inasema ombi linasubiri. Unaarifiwa kwenye simu yako kwa vyovyote vile — wakikataa, pamoja na sababu yao, na unaweza kuomba tena.",
  "help.close-account.title": "Funga akaunti yako",
  "help.close-account.summary": "Akaunti ya SeeBuyGet iliyokaa miaka minne bila kuingiwa inaweza kufungwa na mwenyewe. Hakuna kinachojifunga chenyewe.",
  "help.close-account.step1": "Akaunti yako ikikaa miaka minne bila kuingiwa, tunakuarifu kwenye programu, na kwa barua pepe ikiwa una barua pepe ya kurejesha akaunti, kwamba inaweza kufungwa.",
  "help.close-account.step2": "Gusa picha yako, kisha “Mipangilio › Funga akaunti yangu”. Kwenye programu ya Send: “Akaunti › Mipangilio › Funga akaunti yangu”.",
  "help.close-account.step3": "Ikiwa kitu bado kiko wazi, inasema ni nini. Kikiwa hakuna, andika PIN yako na uguse “Funga akaunti yangu”.",
  "help.close-account.note1": "Kufunga hakuwezi kutenduliwa. Jina lako, nambari ya ID, nambari ya simu, barua pepe na picha za ID huondolewa, na unatolewa kila mahali.",
  "help.close-account.note2": "Vifurushi, makabidhiano na hati za mizigo hubaki, vikionyesha “akaunti iliyofungwa” mahali ulipokuwa: ni kumbukumbu za watu wengine pia.",
  "help.close-account.note3": "Nambari yako ya simu inaachiliwa. Inaweza kujisajili tena, kama akaunti mpya, na haipati chochote cha ile ya zamani.",
  "help.close-account.note4": "Akaunti inaweza kufungwa tu ikishakaa miaka minne bila kuingiwa. Hadi hapo, unaweza kuipumzisha chini ya “Mipangilio › Nyamazisha akaunti yangu”.",
  "help.mute-account.title": "Nyamazisha akaunti yako",
  "help.mute-account.summary": "Kunyamazisha hupumzisha akaunti yako ya SeeBuyGet: hakuna kipya kinachoifikia hadi uache kuinyamazisha, na hakuna kinachofutwa.",
  "help.mute-account.step1": "Gusa picha yako, kisha “Mipangilio”. Kwenye programu ya Send: “Akaunti › Mipangilio”.",
  "help.mute-account.step2": "Gusa “Nyamazisha akaunti yangu”. Inaeleza kunyamazisha kunafanya nini; gusa “Nyamazisha akaunti yangu” tena ili kufanya hivyo.",
  "help.mute-account.step3": "Ili kuamsha akaunti yako, fungua mstari huo huo — sasa unasema “Acha kunyamazisha akaunti yangu” — na uguse “Acha kunyamazisha akaunti yangu”.",
  "help.mute-account.note1": "Akaunti yako ikiwa imenyamazishwa, duka lako halipendekezwi kwa vifurushi vipya na linaondoka kwenye ramani, hupewi mizigo kama dereva, kampuni yako ya magari haichukui kazi mpya, na duka lako la mtandaoni halipokei oda mpya. Ulicho nacho tayari kinaendelea, na kituo cha kupanga kinaendelea kupanga kile ambacho mtandao unakituma.",
  "help.mute-account.note2": "Misimbo ya kuingia na ujumbe kuhusu usalama wa akaunti yako bado vinakufikia. Arifa nyingine huenda kwenye orodha ndani ya programu bila kulia simu yako, na barua pepe nyingine hazitumwi.",
  "help.mute-account.note3": "Kunyamazisha kunahusu kila jukumu kwenye akaunti yako kwa pamoja: akaunti yako ni nambari yako ya simu, na majukumu yako ni unachofanya nayo.",
  "help.change-pin.title": "Badilisha PIN yako",
  "help.change-pin.summary": "PIN yako ni tarakimu 5. Ibadilishe kwa ile ya sasa — au, ikiwa umeisahau, kwa msimbo unaotumwa kwenye simu yako.",
  "help.change-pin.step1": "Programu ya Driver na ya Fleet: gusa picha yako, kisha “Mipangilio › Badilisha PIN yako”.",
  "help.change-pin.step2": "Programu ya Send: “Akaunti › Mipangilio › Badilisha PIN yako”.",
  "help.change-pin.step3": "Umeisahau? Kwenye skrini ya kuingia gusa kiungo cha kusahau PIN. Tunatuma msimbo kwenye simu yako nawe unachagua PIN mpya.",
  "help.change-pin.note1": "Kubadilisha PIN yako hutoa kila simu nyingine ambayo PIN hiyo ilikuwa imefungua, katika kila programu.",
  "help.change-pin.note2": "PIN iliyo rahisi kukisiwa inakataliwa: tarakimu moja kwa sehemu kubwa, mfuatano kama 12345 au 13579, au mpangilio kama 12312.",
  "help.change-pin.note3": "PIN ni tarakimu tano, si nne, ili isiwe PIN ile ile ya pesa zako za simu au ya kadi yako ya benki. Usitumie hiyo ukiongeza tarakimu moja.",
  "help.change-pin.note4": "PIN iliyobadilishwa kwa msimbo — kwa sababu ilisahaulika, au ilifungwa — inafanya kazi kwenye simu au kivinjari ulichotumia. Kila kingine kinaomba msimbo tena.",
  "help.change-pin.note5": "Kubadilisha PIN iliyosahaulika kwenye simu au kivinjari ambacho hujawahi kuingia nacho kunahitaji misimbo miwili: ule wa nambari yako, na mmoja kwa barua pepe ya kurejesha akaunti iliyo kwenye akaunti yako. Andika anwani hiyo ya barua pepe nasi tunaitumia msimbo. Kwenye simu uliyowahi kuingia nayo, msimbo wa nambari yako unatosha.",
  "help.change-pin.note6": "Tunaandika kwa barua pepe yako ya kurejesha akaunti, na kukuarifu kwenye programu, kila PIN yako inapobadilishwa au inapoanza kufanya kazi kwenye simu au kivinjari kipya. Ikiwa si wewe, badilisha PIN yako mara moja: hilo linafungia nje kila simu na kivinjari kingine.",
  "help.change-pin.note7": "“Mipangilio › Simu na vivinjari” inaonyesha kila simu na kivinjari ambacho PIN yako inafanya kazi, pamoja na lini kila kimoja kilithibitishwa na kilitumika mara ya mwisho. “Sahau vingine vyote” inaomba PIN yako na kukutoa kila mahali; kila kimoja kati ya vingine kisha kinahitaji msimbo kwa nambari yako kabla PIN yako haijafanya kazi huko tena. Kwenye simu au kompyuta isiyo yako, tumia “Toka, na usahau hiki”.",
  "help.change-pin.note8": "Kubadilisha PIN yako, au kuweka upya iliyosahaulika, huzima kufungua kwa alama ya kidole au uso kwenye kila simu. Kuwashe tena chini ya Mipangilio.",
  "help.who-you-contract-with.title": "Unayefanya naye mkataba",
  "help.who-you-contract-with.summary": "Mipangilio inaonyesha kampuni ya SeeBuyGet unayofanya nayo mkataba na leseni na bima ambazo inafanyia biashara, kila moja na nambari yake. Ikiwa moja si sahihi, unaweza kusema hivyo.",
  "help.who-you-contract-with.step1": "Fungua “Mipangilio › Unayefanya naye mkataba”. Programu ya Shop, Hub, Driver, Fleet na Store: gusa picha yako, kisha Mipangilio. Programu ya Business: Mipangilio.",
  "help.who-you-contract-with.step2": "Kila leseni na sera ya bima inaonyesha ni nini, nambari yake, nani aliitoa na ni halali hadi lini. Hakiki nambari kwa aliyeitoa.",
  "help.who-you-contract-with.step3": "Ikiwa moja si sahihi, gusa “Hii si sahihi”. Chagua kilicho kibaya, kieleze kwa maneno yako mwenyewe, na uambatishe kinachokionyesha: picha ya skrini ya rejista ya aliyeitoa, au picha.",
  "help.who-you-contract-with.step4": "Gusa “Tuma ripoti”. Chini ya hati utaona kwamba uliripoti, na baadaye kilichoamuliwa na kwa nini.",
  "help.who-you-contract-with.note1": "Hakuna kinachobadilika kwa kuripoti. Hati inaendelea kuhesabika. Kampuni inaambiwa ulichosema, kamwe si nani alisema, na ina siku saba kujibu. Kisha wafanyakazi wa SeeBuyGet huamua: mmoja wao anaweza kutupilia mbali ripoti, na kufuta hati kunahitaji wawili.",
  "help.who-you-contract-with.note2": "Unaona leseni na bima tu. Akaunti ya benki ya kampuni, watu wanaoweza kutia sahihi kwa niaba yake na hati zenyewe hazionyeshwi.",
  "help.who-you-contract-with.note3": "Mstari huu haupo pale ambapo hakuna kampuni ya SeeBuyGet inayofanya nawe mkataba katika nchi yako.",
  "help.store-secret.title": "Badilisha siri ya kutia sahihi",
  "help.store-secret.summary": "Siri hii hutia sahihi kila taarifa ya hali tunayotuma kwa mfumo wa duka lako la mtandaoni. Haimwingizi mtu yeyote. Ibadilishe wakati wowote huenda imeonekana, au ukiipoteza.",
  "help.store-secret.step1": "“Duka langu la mtandaoni › Siri ya kutia sahihi › Badilisha siri”.",
  "help.store-secret.step2": "Andika nenosiri lako ili kuthibitisha. Duka la mtandaoni ambalo bado halina barua pepe na nenosiri huandika siri ya sasa badala yake.",
  "help.store-secret.step3": "Siri mpya inaonyeshwa mara moja tu. Ihifadhi kabla ya kufunga dirisha.",
  "help.store-secret.step4": "Sasisha mfumo wa duka lako la mtandaoni: taarifa tutakazotuma kuanzia sasa zinatiwa sahihi kwa siri mpya.",
  "help.store-secret.note1": "Kadi inasema siri ilibadilishwa lini mara ya mwisho, na inapendekeza kuibadilisha ikishapita siku 90.",
  "help.store-secret.note2": "Nenosiri lililokosewa hapa halikutoi: programu inasema halikuwa sahihi nawe unajaribu tena.",
  "help.store-secret.note3": "Kubadilisha siri hutoa duka lako la mtandaoni kwenye kila kifaa kingine.",
  "help.api-keys.title": "Tengeneza au badilisha ufunguo wa API wa usafirishaji",
  "help.api-keys.summary": "Ufunguo wa umma unaweza kukaa kwenye ukurasa wako wa wavuti. Ufunguo wa siri ni wa seva yako pekee, na unaonyeshwa mara moja tu.",
  "help.api-keys.step1": "“Duka langu la mtandaoni › Funguo za API za usafirishaji › Ufunguo mpya”.",
  "help.api-keys.step2": "Chagua wa umma au wa siri, na wa majaribio au halisi.",
  "help.api-keys.step3": "Umepoteza ufunguo wa siri, au huna uhakika nani anao? Tengeneza mpya, hamia kwake, kisha batilisha ule wa zamani.",
  "help.api-keys.note1": "Funguo za siri zinaonyesha umri wake, na zinapendekeza kubadilisha ufunguo uliopita siku 90.",
  "help.business-people.title": "Ongeza na uondoe watu kwenye biashara yako",
  "help.business-people.summary": "Mmiliki huongeza watu kwa nambari ya simu wanayoingia nayo. Hakuna kinachofunguka kwao hadi waingie wenyewe na wakubali.",
  "help.business-people.step1": "“Watu › Ongeza mtu”: nambari yake ya simu, jina lake, na anachoruhusiwa kufanya.",
  "help.business-people.step2": "Mmiliki: kila kitu, pamoja na watu. Mratibu: kazi ya kila siku. Fedha: hivyo hivyo, na ndiye mtu ambaye malipo yako yataunganishwa kupitia kwake. Mtazamaji: anaona kila kitu, habadilishi chochote.",
  "help.business-people.step3": "Ili kumtoa mtu, bonyeza Ondoa kwenye mstari wake. Inaanza kufanya kazi kuanzia mbofyo wake unaofuata. Viungo vya hati za mizigo vilivyotumwa kwake kwa barua pepe vinaacha kufanya kazi wakati huo huo.",
  "help.business-people.step4": "Ondoka hukutoa wewe mwenyewe kwenye biashara. Mmiliki aliye peke yake hawezi kuondoka hadi mtu mwingine awe mmiliki.",
  "help.business-bell.title": "Soma arifa chini ya kengele",
  "help.business-bell.summary": "Kile msafirishaji au SeeBuyGet inaiambia biashara yako huhifadhiwa chini ya kengele iliyo juu ya programu ya Business.",
  "help.business-bell.step1": "Gusa kengele. Nambari iliyo juu yake ni idadi ya arifa ambazo hakuna mtu katika biashara aliyezisoma bado. Ya kwanza ni ya kukukaribisha: kile kengele inakuambia, na kuigusa kunafungua “Pata manufaa yote ya programu”.",
  "help.business-bell.step2": "Gusa arifa. Inayohusu kitu chako — mzigo, uhifadhi, usafirishaji nje au uagizaji, mkataba uliopewa — inakifungua mara moja na inawekwa alama ya kusomwa kwa kila mtu katika biashara, ikisema nani aliisoma. Inayoeleza kitu tu inafunguka yote.",
  "help.business-bell.step3": "Mzigo unafunguka kwenye sehemu ambayo arifa inahusu: tatizo njiani chini ya Barabarani, lakiri iliyovunjika chini ya Hati, dai lililoamuliwa chini ya Dai, na kingine chochote kwenye Muhtasari wake, ambapo jibu lako linaombwa. Uhifadhi unafunguka chini ya Safari, usafirishaji nje chini ya Mauzo ya nje, uagizaji chini ya Bidhaa za kuagiza.",
  "help.business-bell.step4": "Chini ya arifa, “Weka kuwa imesomwa” huiweka hiyo moja kuwa imesomwa bila kuifungua, na “Onyesha yote” huonyesha yote ya arifa ndefu. Weka zote kuwa zimesomwa hufuta nambari kwa mara moja.",
  "help.business-bell.note1": "Kisanduku cha arifa ni cha biashara, si chako peke yako: kila mtu katika biashara husoma kile kile.",
  "help.business-bell.note2": "Mtu anayeweza kutazama biashara tu anaweza kusoma kila arifa lakini hawezi kuweka moja kuwa imesomwa. Inabaki haijasomwa hadi mtu anayeweza kuishughulikia aisome.",
  "help.business-bell.note3": "Arifa hazitumwi kwenye simu au kompyuta. Fungua programu ya Business ili kuzisoma. Mtu aliyetolewa kwenye biashara anaacha kuziona mara moja.",
  "help.notices-bell.title": "Soma arifa chini ya kengele",
  "help.notices-bell.summary": "Kile mtandao unakuambia huhifadhiwa chini ya kengele iliyo juu ya programu. Arifa kuhusu kitu hukifungua kwa mguso mmoja.",
  "help.notices-bell.step1": "Gusa kengele. Nambari iliyo juu yake ni idadi ya arifa ambazo bado hujasoma. Ya kwanza ni ya kukukaribisha: kile kengele hii inakuambia, na kuigusa kunafungua “Pata manufaa yote ya programu”.",
  "help.notices-bell.step2": "Gusa arifa inayohusu kitu — mzigo, mazungumzo, kifurushi, ofa, zamu yako, kampuni yako ya magari — nayo inafunguka hapo mara moja, ikiwekwa alama ya kusomwa. Arifa inasema inakupeleka wapi.",
  "help.notices-bell.step3": "Arifa inayoeleza kitu tu inafunguka yote unapoigusa. Chini ya arifa, “Weka kuwa imesomwa” huiweka kuwa imesomwa bila kuifungua, na “Onyesha yote” huonyesha yote ya arifa ndefu.",
  "help.notices-bell.note1": "Ikiwa unaendesha, simama kabla ya kusoma kengele. Kila arifa basi ni mguso mmoja, na kile inachofungua hakikuombi kuandika chochote.",
  "help.notices-bell.note2": "Zikiwashwa kwa kifaa hiki, arifa pia huja kwenye simu hata programu ikiwa imefungwa. Kugusa moja hapo kunafungua mahali pale pale.",
  "help.business-loads.title": "Tangaza mzigo kwa wasafirishaji",
  "help.business-loads.summary": "Tangaza mzigo kwa wasafirishaji kwenye ubao wa wazi, kubalianeni bei, na uufuatilie hadi mlangoni. Unamlipa msafirishaji wewe mwenyewe.",
  "help.business-loads.step1": "“Ndani ya nchi › Mizigo › Tangaza mzigo”. Inauliza sehemu moja baada ya nyingine. Upau ulio juu unasema uko kwenye sehemu gani na nini kinafuata, na kwamba hakuna kinachowekwa hadharani kabla ya hatua ya mwisho; Rudi hukupeleka kwenye sehemu iliyotangulia.",
  "help.business-loads.step2": "Nani anaubeba, pale kuna chaguo: ubao wa wazi, au msafirishaji uliye na mkataba naye. Chini ya mkataba, sema siku unayopaswa kufika, nambari ya oda yako na lini unaweza kufikishwa — msafirishaji anapanga lini atauchukua.",
  "help.business-loads.step3": "Kutoka na kwenda: chagua unapochukuliwa na unakokwenda kutoka kwenye maeneo yako uliyohifadhi — Hifadhi eneo jipya huongeza moja — au uufikishe kwa biashara nyingine kwa msimbo iliyokupa. Sema unakwenda nchi gani; ukivuka mpaka, nani anaupokea na anwani yake.",
  "help.business-loads.step4": "Ni nini: sema ni nini, ni bidhaa za aina gani, uzito wake, jinsi ulivyofungashwa na vipande vingapi. Wasafirishaji wanasoma hasa hiki, na kinaingia kwenye hati ya mzigo. Bidhaa hatari hutajwa kama karatasi yake ya data ya usalama inavyozitaja: nambari ya UN, jina sahihi la usafirishaji, daraja na kundi la ufungashaji.",
  "help.business-loads.step5": "Lini unachukuliwa — tupu ina maana mara tu msafirishaji anapoweza — kisha thamani yake na jinsi bei inavyowekwa: wasafirishaji wanataja bei yao nawe unakubali mmoja, au msafirishaji wa kwanza kwa bei ya ubao anauchukua. Mwisho, kile dereva anaambiwa siku hiyo, na amuulizie nani.",
  "help.business-loads.step6": "“Hakiki na utangaze” inaonyesha kila sehemu, na “Badilisha” inakurudisha kwenye moja. Inasema nani ataona mzigo ukishatoka. “Tangaza mzigo” unautoa — chini ya mkataba kitufe kinatuma oda kwa msafirishaji wako — na kukuonyesha msimbo wake, pamoja na “Fungua mzigo” na “Tangaza mwingine”.",
  "help.business-loads.step7": "Fungua mzigo. Kumbukumbu yake iko katika sehemu — “Muhtasari”, “Barabarani”, “Hati”, “Malipo” na “Dai” — gusa jina, au telezesha pembeni. “Muhtasari” una bei zilizotolewa, nani anaubeba, kiungo cha ufuatiliaji cha kushiriki na hati ya mzigo; “Hati” ina viungo vya hati hiyo.",
  "help.business-loads.note1": "SeeBuyGet haichukui, haishikilii wala haitumi pesa za mizigo yako. Unamlipa msafirishaji moja kwa moja, au kupitia mfumo wako mwenyewe wa malipo.",
  "help.business-loads.note2": "Unaarifiwa chini ya kengele mzigo unapofikishwa, pamoja na nani aliyeupokea.",
  "help.business-exports.title": "Safirisha kontena nje kupitia bandari",
  "help.business-exports.summary": "Rekodi uhifadhi ambao wakala wako wa usafirishaji au kampuni ya meli imethibitisha, na SeeBuyGet inashughulikia barabara hadi terminali kabla geti halijafungwa: kontena tupu likitoka, kontena lililojaa likiingia, uzito wake, lakiri yake, hati zake na siku za bure za kontena, na wakala wako wa forodha kando yako — na faili moja kwa wakala wako wa usafirishaji getini. SeeBuyGet haihifadhi nafasi kwenye meli yoyote.",
  "help.business-exports.step1": "“Mauzo ya nje › Rekodi usafirishaji nje kwa bahari”. Nakili uhifadhi kutoka kwenye uthibitisho wake: nambari ya uhifadhi na ni na nani, meli na safari yake, muda wa mwisho wa kuingia getini, wa uzito jumla uliothibitishwa na wa hati (kwa UTC), nambari ya kuachiliwa kwa kontena tupu. Chagua mahali kontena linapojazwa, terminali, na depo ikiwa unachukua kontena tupu wewe mwenyewe.",
  "help.business-exports.step2": "Chini ya usafirishaji nje, mstari mmoja unasema kontena lililojaa linapaswa kuondoka kufikia lini ili liwe ndani ya geti kabla ya muda wa mwisho — barabara kwa kasi ya lori, pamoja na muda wa kupanga foleni getini. Unaarifiwa chini ya kengele saa sita kabla ya wakati huo, ikiwa geti litafungwa bila kontena, na saa kumi na mbili kabla ya muda wa mwisho wa uzito jumla uliothibitishwa ikiwa bado haujatamkwa.",
  "help.business-exports.step3": "“Tangaza safari ya kontena tupu” ikiwa unachukua kontena tupu, andika nambari ya kontena, na utamke uzito wake jumla uliothibitishwa pamoja na nani anayeutia sahihi. Kisha “Tangaza mzigo kwenda terminali”: dereva anaona muda wa mwisho wa geti na uhifadhi wako. Andika lakiri kwenye mzigo huo chini ya Ndani ya nchi › Mizigo, pamoja na picha zake tatu, kabla dereva hajauchukua.",
  "help.business-exports.step4": "Toa hati chini ya “Hati”: pakia faili kwenye mstari wake, ambatisha mojawapo ya nyaraka zako, au andika rejea yake — tamko la forodha la usafirishaji nje ni nambari ambayo wakala wako wa forodha anakupa. Makundi matatu: zinazohitajika kwa kila usafirishaji nje (ankara ya biashara, orodha ya upakiaji, tamko la forodha la usafirishaji nje, na barua yako ya maelekezo); zinazoombwa kwa bidhaa hizi — weka hati kwenye orodha pale bidhaa, mnunuzi au mpaka unapoihitaji (cheti cha asili, cheti cha afya ya mimea au cheti cha afya, kibali cha kusafirisha nje, cheti cha bima, nyingine yoyote kwa jina lake; bidhaa hatari hubeba tamko lake la bidhaa hatari tangu mwanzo); na zinazohifadhiwa pamoja na usafirishaji zikiwepo (uthibitisho wa uhifadhi, tiketi ya mizani, hati ya shehena). Orodha yako ya upakiaji inatoka kwenye faili lako mwenyewe chini ya “Orodha ya upakiaji”: pakia faili la jedwali au faili ambalo mfumo wako unatoa, au bandika visanduku vyake — kila safu inasomwa kwa kichwa chake, yoyote unayolinganisha kwa mkono inakumbukwa kwa faili lako linalofuata, safu zako mwenyewe zinahifadhiwa, na mstari usioweza kusomwa unaonyeshwa kwa nambari yake; kisha uitie sahihi. Ankara yako ya biashara inatengenezwa kutoka kwenye mistari hiyo hiyo chini ya “Ankara ya biashara” — bei zake na asili zake zinasomwa kutoka kwenye faili hilo hilo (safu ya bei ya kipande au ya thamani, nchi ya asili): jaza nambari yake, sarafu na mnunuzi, ongeza kile ambacho nchi inakokwenda inaomba zaidi (maelezo kwa majina yake yenyewe, matamko kwa maneno yake yenyewe, safu za orodha yako), na uitie sahihi; kile ilichobeba kinakumbukwa kwa ankara yako inayofuata kwenda nchi hiyo. Barua yako ya maelekezo kwa wakala wa usafirishaji ni fomu chini ya “Barua ya maelekezo ya mtumaji wa mzigo”: sehemu kubwa inatoka kwenye usafirishaji huo, na bidhaa zake kutoka kwenye orodha yako ya upakiaji; jaza mpokeaji wa mzigo, anayearifiwa, bandari ya kushushia, masharti ya biashara, kama nauli imelipwa mapema au italipwa na mpokeaji, jinsi hati ya shehena inavyotolewa na mistari ya bidhaa, kisha uitie sahihi. Ikishatiwa sahihi, inahifadhiwa sawasawa kama ilivyotiwa sahihi — mabadiliko ni toleo jipya, na usafirishaji ukibadilika chini yake (uzito, kontena) unaombwa kutia sahihi tena. “Fungua faili la makabidhiano” kwa wakala wako wa usafirishaji: kinachokosekana bado kimewekwa alama ndani yake. Wakala akishatoa hati ya shehena, andika nambari yake kwenye usafirishaji.",
  "help.business-exports.step5": "Chini ya “Saa ya kontena”, andika siku za bure ambazo kampuni ya meli inatoa — nje ya terminali (detention), kuanzia kontena tupu linapotoka depo hadi kontena liwe ndani ya geti, na ndani yake (demurrage), kuanzia getini hadi linapopakiwa melini. Saa inahesabu kuelekea tarehe nawe unaarifiwa chini ya kengele siku tatu kabla yake, na mara moja ikipita. Dereva wetu akichukua kontena tupu ndipo inaanza; ikiwa kampuni ya meli au wakala wako wa usafirishaji alileta kontena tupu, andika lilitoka depo lini. Wakala wako akishasema liko melini, andika lilipakiwa lini: saa inasimama. Ikiwa kontena ni lako mwenyewe (halijakopeshwa na kampuni ya meli), sema hivyo — weka alama unaporekodi usafirishaji nje, au “Kontena ni letu” — na hakuna saa ya kampuni ya meli inayohesabu juu yake.",
  "help.business-exports.step6": "“Wakala wa forodha › Chagua wakala wa forodha” ili kumteua mmoja kutoka orodha ya mawakala. Anaarifiwa, anasoma hati zilizoambatishwa kwenye usafirishaji huu — si hati zako nyingine — anatoa tamko la forodha la usafirishaji nje, na anakubali kila hati au anairudisha pamoja na sababu; hati iliyorudishwa inaonekana kama inayokosekana hadi uitoe tena. “Maliza uteuzi” ukimaliza: anaacha kusoma mara moja, na anaarifiwa. Ada yake inakuja kama nukuu ya bei chini ya “Ada yake”: ikubali hapo ikiwa ni kiasi mlichokubaliana; yeyote kati yenu anasema inapolipwa, pamoja na rejea yake. SeeBuyGet haihamishi pesa yoyote kati yenu.",
  "help.business-exports.note1": "Uzito jumla uliothibitishwa ni tamko lako, unalomkabidhi wakala wako wa usafirishaji: yeye analitamka kwa kampuni ya meli. Kontena halipakiwi melini bila tamko hilo.",
  "help.business-exports.note2": "SeeBuyGet inashughulikia barabara na kuweka hati tayari. Sehemu ya bahari, uhifadhi wake na hati ya shehena ni kazi ya wakala wako wa usafirishaji au ya kampuni ya meli; hakuna kinachohifadhiwa, kuwasilishwa au kutumwa kwa kampuni ya meli kutoka hapa, kwa hiyo wakala yeyote wa usafirishaji anaweza kufanya kazi nayo.",
  "help.business-exports.note3": "Wakala wa forodha anapata usafirishaji nje aliouteuliwa chini ya Mauzo ya nje yake mwenyewe: fungua kila hati, ikubali au uirudishe, na utoe tamko la forodha la usafirishaji nje kwa nambari yake. Weka kwenye orodha kile ambacho mpaka huu unaomba kwa bidhaa hizi: muuzaji nje anaarifiwa. Nukuu ada yako chini ya “Ada yake”: muuzaji nje anaarifiwa na kuikubali, na kiasi kipya kinamwomba akubali tena. Siku za bure ziko katika makubaliano ya muuzaji nje na kampuni ya meli: SeeBuyGet inahesabu siku, na kamwe si gharama ya siku iliyozidi.",
  "help.business-exports.note4": "Pale kontena linakwenda bandarini kwa reli — au lilikuja bara kwa reli katika uagizaji — hifadhi hati ya reli chini ya “Hati ya reli”: nakala yake au nambari yake, na uweke alama kile kilichochapishwa juu yake. Unaulizwa tu kile ambacho sheria za njia yake zinaomba: CIM kati ya nchi wanachama wake, SMGS kati ya Urusi, China na Asia ya Kati, au masharti ya shirika la reli lenyewe, kama ya Kenya Railways. Unaambiwa kinachokosekana, pengo linagharimu nini kitu kikienda kombo, na kama nambari ya kontena na lakiri zake zinalingana na zetu. Shirika la reli hutoa hati hiyo; SeeBuyGet inaihifadhi, na haitoi yoyote.",
  "help.business-parcels.title": "Kutuma vifurushi kutoka kwa biashara yako",
  "help.business-parcels.summary": "Vifurushi hutoka dukani au mahali pako hadi dukani au mahali pako, na hulipwa kutoka kwenye salio lako la vifurushi, kama duka la mtandaoni linavyolipa: bila salio, hakuna lebo. Mtu anayekichukua anaonyesha msimbo unaompa.",
  "help.business-parcels.step1": "Chini ya Vifurushi, fungua akaunti ya vifurushi mara moja. Ni salio kwa kampuni ya SeeBuyGet katika nchi yako.",
  "help.business-parcels.step2": "“Ongeza salio”: weka kiasi na simu inayolipa, na uidhinishe ombi kwenye simu hiyo — au lipa kwa paybill ukitumia rejea iliyoonyeshwa. Salio linaongezeka malipo yakishathibitishwa, kamwe si kabla.",
  "help.business-parcels.step3": "“Tuma kifurushi”: duka kitakapokabidhiwa, duka kitakapochukuliwa, simu ya atakayekichukua, vipimo vyake vinne na picha ya kilicho ndani. Bei inaonyeshwa kabla hujatuma; inalipwa kutoka kwenye salio mara moja, na lebo yake inachapishwa.",
  "help.business-parcels.step4": "Fungua kifurushi ili kuchapisha lebo yake — inafunguka kwenye dirisha linalopanda kwenye ukurasa wake, na Chapisha chini yake — kuona kilipo, na kunakili msimbo ambao duka linaomba. Mpe msimbo yeyote atakayekichukua: SeeBuyGet haimtumii ujumbe wowote.",
  "help.business-parcels.note1": "Kwa nini salio: kifurushi hulipwa kinapotumwa, ili duka lisipokee kifurushi ambacho hakuna aliyekilipia, na hakuna anayesubiri ankara. Kinachoshikiliwa kwa ajili ya njia ndefu zaidi na hakijatumika hurudi kifurushi kikishachukuliwa.",
  "help.business-parcels.note2": "Salio halitoshi: kifurushi kinatengenezwa bila lebo, na “Lipa sasa” kinakilipia baada ya kuongeza salio. Kikighairiwa kabla ya kukabidhiwa, pesa zake zinarudi zote; kikiwa kituoni, kinarudishwa kwenye duka kilipokabidhiwa, kwa bei iliyoonyeshwa.",
  "help.business-parcels.note3": "Mzigo wako mwenyewe, au kitu kikubwa mno kwa duka — paleti, mashine — huenda chini ya Ndani ya nchi, ambapo unakubaliana bei yake na msafirishaji. Vifurushi vya kuvuka mpaka bado havitumwi kutoka hapa.",
  "help.business-parcels.note4": "Mfumo wako mwenyewe unaweza kuvituma pia. Kwa ufunguo wa kampuni, unaotengenezwa na mmiliki chini ya Maelezo ya biashara, unatuma kifurushi kupitia ukaguzi ule ule na kulipa kutoka kwenye salio lile lile; ufunguo wa majaribio unakipa bei na hauhifadhi chochote. Pale anwani ya mfumo wako imetolewa, unaarifiwa kila hatua: kimelipwa, kimekabidhiwa, tayari kuchukuliwa, kimechukuliwa, kimeghairiwa.",
  "help.business-parcels.note5": "Kinachochukuliwa mahali pako badala ya dukani: chini ya “Kinachukuliwa mahali pako”, chagua mojawapo ya maeneo yako ambapo bidhaa hupakiwa. Linachukua eneo la ufikishaji la duka lililo karibu nalo zaidi, na lazima liwe na duka ndani ya km 30. Vifurushi vinavyotumwa kutoka hapo vinakusubiri uviweke kwenye mifuko kulingana na vinakokwenda; funga kila mfuko kwa nambari ya lakiri yake na picha, na madereva walio karibu wanaarifiwa kuwa uko tayari.",
  "help.business-parcels.note6": "Kinachofikishwa mahali pako badala ya kuchukuliwa dukani: chagua mojawapo ya maeneo yako chini ya “Mahali pa kuchukuliwa”, na kiwango cha juu utakachomlipa dereva kwa sehemu ya mwisho ya safari. Kifurushi kinakwenda kwenye duka lililo karibu zaidi na eneo hilo; kikishafika hapo, dereva anaombwa akilete, kwa bei yake mwenyewe na kamwe si zaidi ya kiwango chako cha juu, ikilipwa kutoka kwenye salio lako anapokichukua. Duka linakikabidhi tu kwa dereva huyo, kwa pasi yake, na yeyote anayetia sahihi mahali pako yuko kwenye kumbukumbu yake. Ikiwa salio lako halina kiwango hicho cha juu kufikia wakati huo, hakuna kinachotangazwa na unaarifiwa; na kinaweza kuchukuliwa dukani wakati wowote kwa msimbo wake. Wakati dereva anatafutwa, siku zake za bure rafuni haziishi na mtu anayekipokea haambiwi aje kukichukua; ikiwa hakuna dereva anayekichukua ndani ya siku moja, unaarifiwa, ili uweze kuongeza kiwango cha juu. Ikiwa siku zake za bure ziliisha wakati salio lako lilikuwa pungufu, kile ambacho duka linadai kwa kukihifadhi kinalipwa kutoka kwenye salio lako kinapokabidhiwa.",
  "help.business-fbl.title": "Hati ya shehena ya wakala wa usafirishaji",
  "help.business-fbl.summary": "Hati ya shehena (bill of lading) ambayo wakala wa usafirishaji hutoa kwenye fomu ya FIATA — FBL, au hati yake ya usafirishaji, FWB — inaweza kuhifadhiwa kwenye usafirishaji nje au uagizaji, pamoja na kilichochapishwa juu yake. SeeBuyGet haitoi yoyote wala haithibitishi yoyote: inasema kama hati imekamilika kama ilivyochapishwa, kama inalingana na hati zetu wenyewe, mahali unapoweza kuhakiki kuwa ni halali, na maana yake kitu kikienda kombo.",
  "help.business-fbl.step1": "Chini ya usafirishaji nje au uagizaji, “Hati ya shehena ya wakala wa usafirishaji › Hifadhi hati”. Chagua hati ya shehena au hati ya usafirishaji, na utoe nambari yake, wakala aliyeitoa na siku. Hati ya karatasi huhifadhiwa kama nakala kutoka kwenye nyaraka zako; ya kielektroniki kwa nambari yake. Weka alama kwenye kila kisanduku cha fomu kilichojazwa, na uandike nambari ya kontena, lakiri, vipande, uzito na bandari kama vilivyochapishwa.",
  "help.business-fbl.step2": "Isome tena: kile fomu inachoomba na kinakosekana, na kama kontena, lakiri, vipande, uzito na bandari vinalingana na vyetu. Kulingana hakuthibitishi chochote kuhusu uhalali wake — hati ya kughushi inaweza kunakili kila nambari.",
  "help.business-fbl.step3": "Hati ya kielektroniki: fungua ukurasa wa uhakiki wa FIATA kutoka kwenye hati, ipakie au uandike nambari yake, na uhifadhi kile ukurasa ulichoonyesha kati ya nyaraka zako. Kisha rekodi hilo kwenye hati — imesajiliwa au la, na nambari na mtoaji ambao ukurasa ulionyesha — pamoja na matokeo yakiwa yameambatishwa. Ni kumbukumbu yako ya ulichoona, inayoonyeshwa kwa jina lako: SeeBuyGet haikagui chochote. Hati ya karatasi haina uhakiki wa umma: nambari yake ya mfululizo iko kwa chama ambacho nembo yake inabeba.",
  "help.business-fbl.step4": "Je, wakala wa usafirishaji au wakala wa forodha ni mwanachama wa FIATA? Jitafutie mwenyewe kwenye orodha ya FIATA, chini ya nchi yake — kiungo kiko kando ya hati na mahali unapochagua wakala wa forodha. SeeBuyGet haikagui uanachama wa mtu yeyote.",
  "help.business-fbl.note1": "Kwa nini SeeBuyGet haitoi kamwe hati hii: yeyote anayetoa hati ya shehena ya FIATA huwajibika kama msafirishaji kwa safari nzima, ikiwemo bahari, na lazima awe na bima kwa ajili yake. Sisi tunashughulikia barabara na kuhifadhi hati.",
  "help.business-fbl.note2": "Hati ya shehena ni hati ya umiliki wa bidhaa. Bidhaa hukabidhiwa kwa kubadilishana na nakala halisi moja, inayowasilishwa ikiwa imeidhinishwa ipasavyo; nakala unayohifadhi hapa kamwe si nakala halisi. Nchini Kenya na Uganda sheria ya nyaraka za kielektroniki haifiki hati za umiliki, kwa hiyo hati ya kielektroniki huenda isihesabike kama hati ya umiliki huko.",
  "help.business-fbl.note3": "Vikomo vinatajwa kwa SDR, kama hati inavyovitaja, pamoja na kiasi cha takriban kwa dola kwa kiwango tunachohifadhi pamoja na tarehe yake: kisichozidi SDR 666.67 kwa kipande au SDR 2 kwa kilo pale kuna sehemu ya bahari, SDR 8.33 kwa kilo pale haipo. Ripoti uharibifu ambao hukuweza kuuona ndani ya siku 6 baada ya ufikishaji; peleka dai mahakamani ndani ya miezi 9.",
  "help.air-export.title": "Safirisha bidhaa nje kwa ndege",
  "help.air-export.summary": "Rekodi uhifadhi ambao shirika la ndege au wakala wako wa usafirishaji amethibitisha, na SeeBuyGet inashughulikia barabara hadi terminali ya mizigo ya shirika la ndege kabla ya muda wake wa mwisho wa kupokea — bidhaa za baridi zikihifadhiwa katika kiwango chake chenyewe, mizigo iliyolindwa ikiwa na lakiri. Hati ya mzigo wa ndege (AWB) hukaguliwa, kamwe haitolewi: nambari yake, sheria ya njia yake, na kama inalingana na orodha yako ya upakiaji. SeeBuyGet haihifadhi nafasi kwenye ndege yoyote.",
  "help.air-export.step1": "“Mauzo ya nje › Rekodi usafirishaji nje kwa ndege”. Nakili uhifadhi kutoka kwenye uthibitisho wa shirika la ndege: nambari ya hati ya mzigo wa ndege (tarakimu kumi na moja — tarakimu yake ya mwisho hukaguliwa unapoandika), hati ni ya nani, safari za ndege pamoja na tarehe na viwanja vyake vya ndege, muda wa mwisho wa kupokea (kwa UTC), vipande na uzito kama vilivyohifadhiwa, na nani anaipokea kwenye uwanja wa ndege. Sema kama shirika la ndege limeuthibitisha. Chagua mahali inapopakiwa na terminali ya mizigo kutoka kwenye maeneo yako.",
  "help.air-export.step2": "Bidhaa zinazoharibika hutaja kiwango cha joto zinachohifadhiwa: lori ni la jokofu au lenye bodi ya kuzuia joto, kiwango chake kilichowekwa kiko ndani ya kiwango hicho, na kila kipimo njiani hupimwa dhidi ya kiwango chako, si cha jumla. Ikiwa ukaguzi wa afya ya mimea unafanyika uwanjani wa ndege, weka alama: saa tatu zinaongezwa kabla ya muda wa mwisho wa kupokea.",
  "help.air-export.step3": "Chini ya usafirishaji nje, mstari mmoja unasema mzigo unapaswa kuondoka kufikia lini ili ufike terminali ya mizigo kwa wakati, pamoja na hesabu yake: safari ya barabara, saa moja terminalini kabla ya muda wa mwisho wa kupokea, na saa za ukaguzi pale unafanyika uwanjani wa ndege. “Tangaza mzigo kwenda terminali ya mizigo” mzigo ukishafungashwa: dereva anaona muda wa mwisho wa kupokea na hati ya mzigo wa ndege.",
  "help.air-export.step4": "“Hati ya mzigo wa ndege” inaionyesha ikisomwa dhidi ya sheria ya njia yake siku yake — mkataba wa kimataifa ambao nchi zote mbili zimo, kikomo chake kwa kilo na muda wa kulalamika — kile sheria hiyo inaomba hati ionyeshe na inakosa, na pale vipande au uzito wake havilingani na orodha yako ya upakiaji. Barua yako ya maelekezo kwa ndege inamtaja mpokeaji wa mzigo na uwanja wa ndege unakokwenda. “Fungua faili la makabidhiano” kwa wakala wako wa usafirishaji terminalini.",
  "help.air-export.note1": "Kwa nini muda wa mwisho wa kupokea na si safari ya ndege: shirika la ndege hupokea mizigo kwenye terminali yake hadi muda huo, na mzigo unaofika baada yake husubiri ndege nyingine, saa yoyote ile ndege inaondoka.",
  "help.air-export.note2": "Kwa nini uhifadhi ambao bado haujathibitishwa bado unaendelea: mizigo mara nyingi huhifadhiwa kwa ombi na kuthibitishwa kwa kuchelewa. Lori linaweza kwenda, lakini mzigo huenda usisafiri kwa ndege hiyo — hilo linasemwa kwenye usafirishaji nje, kwenye kazi ya dereva na kwenye faili la makabidhiano, na hatari ya kuachwa nyuma ni yako.",
  "help.air-export.note3": "Mizigo iliyolindwa — iliyolindwa na wakala aliyeidhinishwa au mtumaji anayetambulika kabla haijaondoka — husafiri kwenye gari lililofungwa linalofungika kwa kufuli, kamwe si kwenye baiskeli, pikipiki au tuktuk; ikiwa na lakiri mahali inapopakiwa, lakiri yake ikikaguliwa terminalini, pamoja na dereva ambaye ID yake imeonekana. Hali yake ya usalama ni ya wakala aliyeidhinishwa kuitoa: SeeBuyGet haitoi yoyote, na haitii sahihi tamko lolote kwa ajili yake.",
  "help.air-export.note4": "Dawa na chanjo bado hazibebwi kwenda uwanja wa ndege kwenye SeeBuyGet. Hati ya mzigo wa ndege, safari ya ndege na upokeaji ni mambo ya shirika la ndege na ya wakala wako wa usafirishaji: kufikishwa terminalini si kupokelewa na shirika la ndege.",
  "help.air-export.note5": "Wanyama hai: chagua “Wanyama hai” kama bidhaa na uwatamke — ni wanyama gani, wangapi, kibali cha kuingiza cha mpokeaji wa mzigo na cheti cha afya ya mifugo kwa nambari, CITES pale spishi imeorodheshwa, nani anawatunza njiani, nani alitia sahihi uthibitisho wa mtumaji wa mzigo, na neno lako kwamba hakuna asiyefaa kusafiri. Wanakwenda kwenye bodi ya mifugo, au ndani ya kreti kwenye gari lililofungwa lenye hewa; dereva anawakagua na kuwa na hati halisi kabla ya kuwachukua. Kuna onyo kwa vifaranga wa siku moja ikiwa wangepitisha saa zao 72 — kiasi cha mfugaji — kabla ya ndege.",
  "help.air-export.note6": "Uhifadhi ukibadilika, sema hivyo chini ya “Hati ya mzigo wa ndege”. Umethibitishwa hatimaye: “Shirika la ndege limethibitisha”. Umehamishwa: “Ndege au muda mwingine”, toa ndege uliyohifadhiwa sasa na muda wake wa mwisho wa kupokea kutoka kwenye uthibitisho mpya, kisha “Rekodi uhifadhi mpya”. Uhifadhi kama ulivyokuwa huhifadhiwa kwenye usafirishaji nje. Saa inafuata muda mpya na maonyo yake yanatolewa tena; mzigo unaokwenda terminali ya mizigo unabeba uhifadhi mpya, na dereva aliye tayari njiani anaambiwa kilichobadilika.",
  "help.air-export.note7": "Kwenye terminali ya mizigo dereva anamwomba mhudumu wa mizigo stakabadhi yake na kutoa nambari yake wakati wa kufikisha: ndiyo inayoonyesha kuwa bidhaa ziliingia kabla ya muda wa mwisho wa kupokea. Chochote ambacho mhudumu alikuta si kama kilivyohifadhiwa — vipande pungufu, katoni iliyoharibika — kinasemwa chini ya “Hati ya mzigo wa ndege” mara moja: mwambie wakala wako wa usafirishaji au shirika la ndege, kwa sababu kisichopokelewa huenda kisisafiri.",
  "help.air-export.note8": "Pale ghala linapoyapa malori muda maalum, urekodi pamoja na uhifadhi au baadaye chini ya “Hati ya mzigo wa ndege”. Lori kisha linapangwa kufika kabla ya mwisho wa muda huo badala ya muda wa mwisho wa kupokea, na dereva wake anaambiwa muda huo na rejea yake. Muda maalum unaoisha baada ya muda wa mwisho wa kupokea unakataliwa: mzigo usingeweza kuwahi ndege ndani yake.",
  "help.air-export.note9": "Umepangwa kwenye paleti au makontena ya shirika la ndege kwenye ghala la wakala wako wa usafirishaji? Sema ni mangapi. Lori lenye sakafu ya roli pekee ndilo linapewa mzigo: linayaingiza na kuyatoa yakiwa mazima, ghalani na kwenye gati la terminali. Kampuni za magari husema zina moja chini ya vifaa vya gari lao.",
  "help.air-export.note10": "Unasafiri kwa ndege kutoka uwanja wa ndege wa nchi nyingine — maua ya mkulima wa Rwanda kutoka Nairobi? Nchi inasomwa kutoka kwenye uwanja wa ndege (au uiseme). Sehemu ya barabara kisha inavuka mpaka chini ya dhamana ya forodha: inasafirishwa nje nchini kwako, ikipita kuelekea terminali ya mizigo, na msafirishaji mwenye leseni ya kupitisha mizigo huko — na saa nne za mpaka zinapangwa ndani ya muda wa kuondoka, kwa kiasi chetu.",
  "help.air-export.note11": "Ujazo ulio kwenye uhifadhi unakwenda kwenye sehemu ya barabara: lori ambalo kampuni yake ya magari ilirekodi nafasi ndogo ya mzigo halipewi. Kampuni ya magari hurekodi nafasi ya mzigo ya gari, iliyopimwa ndani ya bodi, chini ya “Nafasi ya mzigo (m³)” kwenye gari.",
  "help.air-import.title": "Chukua bidhaa zilizokuja kwa ndege",
  "help.air-import.summary": "Mizigo ya ndege husubiri kwenye ghala la mhudumu wa mizigo uwanjani wa ndege hadi forodha, kila mamlaka ambayo bidhaa zinahitaji na agizo la kutoa mizigo la mhudumu viiachilie. Rekodi kila hatua inapokuja, na SeeBuyGet haitumi lori ghalani kabla ya hapo — na inahesabu muda wa kuhifadhi bure wa mhudumu, ili mzigo uchukuliwe kabla haujaisha.",
  "help.air-import.step1": "“Bidhaa za kuagiza › Rekodi uagizaji”, na uchague Ndege chini ya “Jinsi unavyokuja”. Kisha, chini ya “Kwa ndege”, nakili hati ya mzigo wa ndege (AWB; tarakimu yake ya mwisho hukaguliwa unapoandika), safari ya ndege, ni ghala la nani inasubiri, vipande na uzito, na — kwa bidhaa zinazohifadhiwa kwa baridi — kiwango chake. Weka alama kwenye mamlaka mbali na forodha zinazopaswa kuachilia bidhaa hizi: orodha ni ya nchi inakokwenda, inapendekezwa kulingana na bidhaa, na kuchaguliwa na wewe au wakala wako wa forodha.",
  "help.air-import.step2": "Toa muda wa kuhifadhi bure wa mhudumu kwa saa, kama ulivyo kwenye taarifa yake au orodha yake ya bei, na mahali kiasi hicho kinapotoka. Taarifa ya kuwasili ya mhudumu ikija, irekodi: saa zinaanza hapo. Unaarifiwa chini ya kengele katika saa zake sita za mwisho, na mara moja ikiisha mzigo ukiwa bado upo.",
  "help.air-import.step3": "Tangaza sehemu ya barabara kutoka ghalani kwa “Tengeneza sehemu ya barabara”, kama kawaida. Haipewi dereva yeyote bado: ubao unawaonyesha inasubiri nini bado. Rekodi kila kibali cha kuachilia kinapokuja — cha forodha pamoja na nambari yake, cha kila mamlaka, agizo la kutoa mizigo la mhudumu au pasi ya geti pamoja na nambari yake. Cha mwisho kinafungua sehemu ya barabara mara moja.",
  "help.air-import.step4": "Ikiwa wakala wako anasema mzigo utatoka ndani ya saa moja, au ghala limethibitisha kwa simu, mwagizaji anaweza kutuma lori hata hivyo: sema kwa nini, na kwamba lori lililotumwa mapema linaweza kusubiri ghalani, kwa gharama yako. Vibali ambavyo bado vinakosekana vinabaki kwenye orodha.",
  "help.air-import.note1": "Kwa nini taarifa ya kuwasili haifungui chochote: inasema mzigo umetua, si kwamba unaweza kuondoka. Lori lililotumwa kwa taarifa hiyo hupanga foleni ghalani hadi forodha na mamlaka nyingine ziachilie bidhaa, na mtu analipia kusubiri huko.",
  "help.air-import.note2": "Kwa nini saa za bure ni wewe unayezitoa: kila mhudumu huweka zake mwenyewe, kuanzia tukio lake mwenyewe, kwa saa au siku — na orodha pekee ya bei iliyochapishwa tuliyoipata katika uwanja wa ndege wa Jomo Kenyatta ni ya mwaka 2013. SeeBuyGet inahesabu saa unazoipa, na kamwe haisemi saa iliyozidi inagharimu kiasi gani: hiyo ni ya mhudumu kuitoza.",
  "help.air-import.note3": "Dawa na chanjo bado hazibebwi kutoka uwanja wa ndege kwenye SeeBuyGet: swali la nani lazima awe na leseni ya kuzibeba liko kwa wakili wetu.",
  "help.air-import.note4": "Kila hatua ni neno lako au la wakala wako, linalohifadhiwa pamoja na rejea yake na nani alilitoa. SeeBuyGet haihukumu yoyote kati yake na haiwezi kusema kibali kitakuja lini: nyakati za mikataba ya huduma ni malengo, si ahadi.",
  "help.air-import.note5": "Wanyama hai: weka alama kwenye “Wanyama hai” chini ya “Kwa ndege” na uwatamke, pamoja na neno lako kwamba hakuna asiyefaa kusafiri. Kibali cha mamlaka ya mifugo huombwa kila mara — wanyama hawatoki uwanja wa ndege bila hicho — na mwagizaji anataja mahali ambapo afisa wa mifugo alipataja. Sehemu ya barabara inakwenda huko na si kwingine, kamwe haipelekwi kwingine, na haibadiliki ikishatangazwa. Bodi ya mifugo pekee ndiyo inabeba mifugo, gari lililofungwa lenye hewa pekee ndilo linabeba kreti, na dereva anawakagua na kuwa na hati halisi kabla ya kuwachukua.",
  "help.air-import.note6": "Kwa nini kutua mwishoni mwa wiki kunaonywa: nchini Kenya uhakiki wa forodha, huduma za mifugo, Pharmacy and Poisons Board na shirika la viwango hufanya kazi Jumatatu hadi Ijumaa uwanjani wa ndege. Mzigo unaotua Jumamosi, Jumapili, Ijumaa alasiri au siku ambayo kalenda ya nchi yako inaiweka kuwa imefungwa unaweza kusubiri siku ya kazi inayofuata — isipokuwa wakala wako aombe maafisa nje ya saa za kazi kwa Form C.1, angalau saa 24 kabla. Unaarifiwa siku tatu kabla, wakati bado kuna muda wa kuomba.",
  "help.air-import.note7": "Ghala haliachilii chochote hadi gharama zake za kuhifadhi na kushughulikia zilipwe: rekodi “Gharama za mhudumu zimelipwa” kama hatua nyingine. Nambari ya agizo la kutoa mizigo na stakabadhi ya mhudumu hupewa dereva, ambaye huombwa navyo kaunta.",
  "help.air-import.note8": "Ghalani dereva anahesabu vipande dhidi ya hati ya mzigo wa ndege kabla ya kuondoka. Hesabu isiyolingana, au uharibifu ambao dereva anaona, unaingia kwenye hati ya mzigo — nawe unaambiwa siku ambayo shirika la ndege lazima liwe limepokea malalamiko yako ya maandishi: siku 14 tangu kupokea kwa uharibifu chini ya Mkataba wa Montreal. Bidhaa zikishatoka ghalani kwa stakabadhi isiyo na dosari, uharibifu unaogunduliwa baadaye unaonekana kuwa wa barabarani.",
  "help.air-import.note9": "Pale ghala linapoyapa malori muda maalum wa kuchukua, urekodi chini ya “Muda wa lori ghalani”: dereva anaambiwa aje ndani ya muda huo. Lori lililo nje ya muda wake husubiri, au hurudishwa.",
  "help.air-import.note10": "Umetua katika nchi nyingine isiyo yako — bidhaa za kuagiza za Uganda zinazotua Nairobi? Nchi inasomwa kutoka kwenye uwanja wa ndege (au uiseme). Forodha ya uwanja wa ndege kisha inauachilia kwa kupita, agizo la kutoa mizigo la mhudumu na gharama kama kawaida, na sehemu ya barabara inaenda chini ya dhamana ya forodha kuvuka mpaka ili kuondolewa forodhani nchini kwako: mamlaka zako mwenyewe huikagua huko, si ghalani.",
  "help.air-import.note11": "Unachukuliwa ukiwa umepangwa kwenye paleti au makontena ya shirika la ndege? Sema ni mangapi chini ya “Kwa ndege”. Lori lenye sakafu ya roli pekee ndilo linapewa sehemu ya barabara — la baridi pale bidhaa zilivyo za baridi — na dereva wake anaambiwa ayaingize na kuyatoa yakiwa mazima.",
  "help.road-meets-rail.title": "Pale barabara inapokutana na reli",
  "help.road-meets-rail.summary": "Pale kontena linaposafiri sehemu ya njia yake kwa treni, lori katika kila upande hupangwa kulingana na treni: kwenda terminali ya reli kabla ya muda wa mwisho wa treni, na kutoka huko tu baada ya shirika la reli kusema kontena limefika. SeeBuyGet haiendeshi treni na haihifadhi nafasi yoyote. Inaweka barabara na reli kwa mpangilio mmoja, ili hakuna lori linalochelewa treni na hakuna linalotumwa kuisubiri.",
  "help.road-meets-rail.step1": "Usafirishaji nje kwa reli: chini ya usafirishaji nje, “Kwa reli hadi bandari › Linakwenda kwa reli”. Chagua terminali ya reli kutoka kwenye maeneo yako, na utoe muda wa mwisho wa treni huko (kwa UTC) na rejea ya treni au ya uhifadhi wa reli. Muda wa mwisho lazima uwe kabla geti la bandari halijafungwa, la sivyo kontena linafika bandarini limechelewa kwa meli — hilo linakataliwa. Fanya hivyo kabla ya kutangaza mzigo kwenda terminali: mzigo kisha unakwenda terminali ya reli, dereva wake anaona muda wa mwisho wa treni, nawe unaarifiwa chini ya kengele saa sita kabla lori halijapaswa kuondoka.",
  "help.road-meets-rail.step2": "Shirika la reli likishaleta kontena ndani ya geti la bandari, andika lini, chini ya kichwa hicho hicho. Tangu hapo saa ya kampuni ya meli inahesabu kontena likiwa ndani ya terminali; hadi hapo inalihesabu likiwa nje, kwa sababu liko nje.",
  "help.road-meets-rail.step3": "Uagizaji kwa reli: chini ya uagizaji, “Kwenda bara kwa reli”. Chagua terminali ya reli ambako treni inaliletea, lini shirika la reli linalitarajia, na siku za bure ambazo terminali inatoa. Sehemu ya barabara kutoka huko inatangazwa kama kawaida na kuchukuliwa kwenye terminali ya reli — na hakuna dereva anayeweza kuichukua hadi shirika la reli liseme kontena liko huko. Treni ikiondoka bandarini na kontena, andika lini chini ya “Treni ilipoondoka bandarini nalo (UTC)” na “Rekodi”: saa ya kampuni ya meli nje ya terminali inahesabu kuanzia hapo, si kuanzia lori letu linapochukua kontena bara.",
  "help.road-meets-rail.step4": "Taarifa ya kuwasili ya shirika la reli ikija, mwagizaji au wakala wake wa forodha anairekodi hapo, pamoja na nambari ya taarifa. Sehemu ya barabara inafunguka mara moja, na siku za bure za terminali zinaanza: unaarifiwa chini ya kengele siku ya mwisho ya bure, na mara moja zikiisha kontena likiwa bado lipo. Zinasimama lori letu linapolitoa kontena.",
  "help.road-meets-rail.step5": "Ikiwa kontena liko huko kabla ya taarifa — terminali ilithibitisha kwa simu, taarifa imechelewa — mwagizaji anaweza kutuma lori hata hivyo, akisema kwa nini. Huo ni uamuzi wa mwagizaji peke yake, kwa sababu ndiye analipia lori linalosubiri. Sababu yake huhifadhiwa na kuonyeshwa kando ya sehemu ya barabara.",
  "help.road-meets-rail.note1": "Kwa nini lori linasubiri taarifa: lori lililotumwa kwa kontena lililo bado kwenye treni hupanga foleni getini, dereva wake hupoteza saa na mzigo unaofuata, na mtu analipia kusubiri huko. Pale treni zinachelewa — kwenye reli nyingi barani Afrika, na hasa Afrika Kusini kwa sasa — neno la shirika la reli lenyewe kwamba kontena liko huko ndilo ukweli pekee wa kutuma lori.",
  "help.road-meets-rail.note2": "Kwa nini muda wa mwisho wa treni unakuja kabla ya ule wa geti: kontena linalokabidhiwa shirika la reli baada ya muda wa mwisho wa treni yake husubiri treni inayofuata, na treni inayofika bandarini baada ya geti kufungwa hukosa meli. Yote mawili yanagunduliwa hapa, kabla lori halijatumwa, badala ya gatini.",
  "help.road-meets-rail.note3": "Dereva anaona kwenye ubao mzigo unaosubiri treni yake, pamoja na sababu, na hawezi kuuchukua bado; unafunguka wenyewe kuwasili kukisharekodiwa. Mzigo uliochukuliwa kabla sehemu ya reli haijarekodiwa kamwe haurudishwi kutoka kwa dereva wake: uagizaji unasema hivyo, ili waweze kuambiwa.",
  "help.road-meets-rail.note4": "Hati ya shirika la reli lenyewe — hati yake ya mzigo au hati ya usafirishaji — huhifadhiwa kando yake, chini ya “Hati ya reli”, na kukaguliwa dhidi ya sheria za njia yake.",
  "help.business-loads.note4": "Kuvuka mpaka, hati ya mzigo inahitaji nani anapokea bidhaa, anwani yake na vipande vingapi, na inaomba maelekezo yako kwa forodha. Inasema usafirishaji uko chini ya sheria gani: CMR pale nchi yoyote kati ya hizo ni mwanachama wake, itifaki ya barabara ya Ushoroba wa Kaskazini kati ya wanachama wake, au vinginevyo mkataba wako.",
  "help.business-loads.note5": "Weka alama kwenye Msafirishaji lazima awe na bima na ni msafirishaji tu ambaye bima yake SeeBuyGet imeikagua kutoka kwenye sera yake, ikiwa bado inatumika, anayeweza kuchukua mzigo — kutoka ubaoni, kwenye ofa na chini ya mkataba vilevile. Wasafirishaji wachache huenda wakajibu. Hati ya mzigo inasema uliomba bima na inataja ya msafirishaji.",
  "help.business-loads.note6": "Unaweza pia kutamka thamani ya bidhaa na maslahi maalum katika ufikishaji, na kukataza kuhamishwa kwenye chombo kingine njiani. Thamani iliyotamkwa huongeza kile msafirishaji anachowajibika nacho bidhaa zikipotea au zikiharibika, kwa hiyo msafirishaji anaweza kutoza kwa ajili yake — kubalianeni nao. Kila kimoja kinaingia kwenye hati ya mzigo; oda chini ya mkataba pia inaonyesha siku ambayo lazima ifike.",
  "help.business-loads.note7": "Ikiwa dereva anaandika kitu kuhusu bidhaa wakati wa kuzichukua — gunia lililochanika, kifuniko kilicholegea — kinaonekana kwenye mzigo, katika “Hati”, chini ya Alichoandika dereva wakati wa kuchukua. Kinakufunga tu ukikubali; kipinge na useme kwa nini, na maneno yako yanaingia kwenye hati ya mzigo kando ya ya dereva. Unajibu mara moja.",
  "help.business-loads.note3": "Mtu aliyetangaza mzigo pia anatumiwa stakabadhi kwa barua pepe unapofikishwa, pamoja na kiungo cha hati ya mzigo.",
  "help.business-loads.note8": "Kuna tatizo na kilichofikishwa: fungua mzigo, kisha “Dai”, na “Ripoti tatizo la bidhaa” ndani ya siku saba baada ya ufikishaji — zimeharibika, pungufu, au hazikupokelewa kabisa — kwa maneno yako mwenyewe, pamoja na picha ikiwa unayo. SeeBuyGet haihukumu dai lolote: isipokuwa kampuni ya SeeBuyGet ilitaja bima kwa mzigo huo, hakuna mtu wa mtandao anayeliamua wala kulipa. Maneno yako yanaingia kwenye hati ya mzigo, na hati hiyo, ikifungiwa pamoja nayo, ndiyo ripoti ya madai ya uharibifu: mpe msafirishaji au kampuni yako ya bima kwa kiungo, chini ya Viungo vya hati hii. Pale masharti ya biashara yaliyokubaliwa yalihamisha hatari kwa mpokeaji mahali pa kuanzia, mpokeaji ndiye anayedai, si wewe.",
  "help.business-loads.note9": "Zimekataliwa mlangoni, zote au sehemu: dereva anabaki na bidhaa zilizokataliwa, nawe unasema zinakwenda wapi ndani ya saa 48 — mzigo unasema kufikia lini. “Rudisha …” zilipochukuliwa, “Kwenda mahali pengine”, au “Ziache”. Zikirudishwa au zikienda kwingine, dereva aliye nazo anazibeba kama mzigo mpya kwa bei ya gari lake, nawe unailipa. Zikiachwa, hakuna kinachosafiri: mpokeaji anaweza kubaki nazo, au msafirishaji anazitupa, na gharama yoyote ya hilo ni yako. Bila jibu kwa wakati zinarudi zilipochukuliwa, kwa gharama yako. Sehemu imekataliwa: zilizobaki zilifikishwa na kutiwa sahihi kama kawaida.",
  "help.business-loads.note10": "Mzigo unaomlipa dereva moja kwa moja: dereva anasema kwenye mzigo umelipa lini — au, ukishafikishwa, kwamba hujalipa, na mzigo unasema “Haujalipwa, asema dereva”. Ikiwa ulilipa, “Tulilipa — toa rejea”: msimbo wa M-Pesa, rejea ya benki, au lini na kwa nani ulikabidhi pesa taslimu. Jibu moja huhifadhiwa; dereva anaarifiwa, na madereva wanaliona kando ya kile dereva alichosema, kama lenye mzozo badala ya kutolipwa. Ukiwa bado haujalipwa wiki moja baada ya dereva kusema hivyo, bila jibu kutoka kwako, madereva wanaonyeshwa hilo kabla ya kuchukua mizigo yako. SeeBuyGet haihukumu upande wowote.",
  "help.business-loads.note11": "Bidhaa zinazojaza lori kabla hazijalielemea — maua, sponji, kreti tupu — zinaweza kutaja nafasi zinazochukua, chini ya “Nafasi inayochukua (m³), ikiwa ni nyepesi kwa ukubwa wake”. Gari ambalo kampuni yake ya magari ilirekodi nafasi ndogo ya mzigo halipewi mzigo huo, na ubao unasema kwa kiasi gani.",
  "help.business-loads.note12": "Unahamisha mizigo ya shirika la ndege kwa barabara chini ya hati yake ya mzigo wa ndege na nambari ya ndege? Weka alama kwenye “Imehamishwa kwa ajili ya shirika la ndege chini ya hati yake ya mzigo wa ndege (ndege kwa lori)”, na utoe hati na ndege. Unabebwa kama mzigo wa kawaida wa barabarani chini ya sheria ya barabara: hati na ndege ni rejea tu, kwenye hati ya mzigo na kuambiwa dereva, na hakuna mtu kwenye SeeBuyGet anayefanya kazi kwa niaba ya shirika la ndege. Kama mkataba wa kimataifa wa usafiri wa anga unatumika badala yake bado haijaamuliwa.",
  "help.business-loads.note13": "Mzigo ulioanza kuujaza huhifadhiwa kwenye simu hii unapoendelea, kwa siku tatu, ili simu inayoingia isiupoteze: Mizigo kisha inatoa “Endelea na mzigo ulioanza” au “Anza upya”. Unaondoka kwenye simu ukishatangazwa, na unapotoka.",
  "help.business-loads.note14": "Chakula kibichi au kilichogandishwa: katika Ni nini, sema joto kinachohifadhiwa — bidhaa za baridi kati ya 2 na 8 °C, zilizogandishwa kwa -18 °C au baridi zaidi, kwa mfano kati ya -25 na -18. Kikiachwa tupu, kinahifadhiwa kati ya 2 na 8 °C. Lori la jokofu au lenye bodi ya kuzuia joto pekee ndilo linapewa mzigo; hati ya mzigo na lebo zake zinachapisha kiwango hicho, dereva anarekodi joto njiani, nawe unaarifiwa chini ya kengele likitoka nje ya kiwango hicho. Muhtasari wa mzigo unasema kiwango unachohifadhiwa. Lori huweka joto moja, kwa hiyo kamwe halibebi mzigo wako kando ya mwingine unaohifadhiwa kwa joto ambalo hayo mawili hayawezi kushiriki.",
  "help.business-coming-in.title": "Pokea bidhaa katika maeneo yako mwenyewe",
  "help.business-coming-in.summary": "Programu ya Business, “Zinazoingia”: kile wasambazaji wako wanachotuma kwenye maeneo yako, kinaposafiri — nambari ya oda yako mwenyewe, kinatoka kwa nani, kiasi gani, kiko wapi sasa na nani anakileta. Kamwe si bei yake: hiyo inabaki kati yako na msambazaji wako.",
  "help.business-coming-in.step1": "“Zinazoingia”, chini ya Maeneo. Chini ya “Unapopokea”, “Pokea bidhaa hapa” kwenye mojawapo ya maeneo yako kunalipa msimbo. Ongeza eneo chini ya Maelezo ya biashara kwanza: yadi, ghala, geti la kiwanda.",
  "help.business-coming-in.step2": "“Tuma msimbo” unampa msambazaji, pamoja na jinsi ya kuutumia. Wanapotangaza mzigo, wanaweka alama kwenye “Fikisha kwa biashara nyingine, kwa msimbo iliyokupa” na kuandika msimbo — pamoja na nambari ya oda yako, ikiwa uliwapa. Mzigo unakuja kwenye eneo hilo na kuonekana hapa. Msimbo unataja eneo hilo na si kitu kingine chako. “Msimbo mpya” hufanya ule wa zamani usitaje chochote; “Acha kupokea hapa” hufunga eneo hilo, na kile kilichokuwa kimetumwa huko bado kinaonekana.",
  "help.business-coming-in.step3": "Chini ya “Unakuja kwako”, kila mzigo: unatoka kwa nani, kiasi gani, uko wapi, unatarajiwa lini na nani anauleta. “Ufuatilie” hufungua ukurasa wake wa ufuatiliaji. Kutoka nje ya nchi, mstari mmoja unasema kama umeshaondolewa forodhani, na ni wajibu wa nani kuuondoa kulingana na masharti ya biashara yaliyokubaliwa: chini ya DAP, kuuondoa forodhani ni wajibu wako.",
  "help.business-coming-in.step4": "Umefikishwa, lakini si wote kama hati inavyosema — vipande pungufu, au baadhi ambavyo si bidhaa hizo — kinachokosekana kinabaki chini ya “Bado zinatarajiwa” hadi ukifunge: “Kimefika” kinapofika hatimaye, au “Hakitakuja” unapoacha kusubiri, pamoja na mstari kwa kumbukumbu zako ukipenda. Msambazaji wako haambiwi: kilichopatikana wakati wa makabidhiano tayari kiko kwenye hati yake.",
  "help.business-coming-in.step5": "Fungua mzigo uliofikishwa kwa ajili ya “Nakala yako ya hati”: hati ya mzigo, iliyohifadhiwa kwa ajili yako kama ilivyotiwa sahihi. Bei ya usafirishaji iko juu yake tu pale masharti ya biashara yaliyokubaliwa yanakufanya wewe ndiye wa kulipia usafirishaji. Ipitishe kwa kiungo, kama ilivyo kwa mizigo yako mwenyewe.",
  "help.business-coming-in.note1": "Tatizo na kilichofikishwa ni lako kudai tu pale masharti ya biashara yaliyokubaliwa yalihamisha hatari kwako mahali pa kuanzia: hapo mzigo uliofunguliwa hapa una “Ripoti tatizo la bidhaa”, ndani ya siku saba baada ya ufikishaji — zimeharibika, pungufu, au hazikupokelewa kabisa, pamoja na picha ikiwa unayo. Vinginevyo msambazaji wako ndiye anayedai, na mzigo unasema hivyo. SeeBuyGet haihukumu dai lolote: isipokuwa kampuni ya SeeBuyGet ilitaja bima kwa mzigo huo, hakuna mtu wa mtandao anayeliamua wala kulipa, na nakala yako ya hati, ikifungiwa pamoja na dai lako juu yake, ndiyo ripoti ya madai ya uharibifu kwa msafirishaji au kampuni yako ya bima.",
  "help.business-coming-in.note2": "Mzigo unaoukataa mlangoni unaonekana kama “Umekataliwa mlangoni kwako”. Bidhaa zinakokwenda baada ya hapo ni msambazaji wako wa kusema, na wa kulipia.",
  "help.business-coming-in.note3": "Kwa nini hakuna bei: kile msambazaji wako anachomlipa msafirishaji wake ni kati yao, isipokuwa masharti yako ya biashara yanakufanya wewe ndiye wa kulipia usafirishaji. Msimbo unamwonyesha msambazaji eneo, na si kitu kingine chako.",
  "help.business-note.title": "Pakua au pitisha hati ya mzigo",
  "help.business-note.summary": "Msafirishaji akishachukua bidhaa, hati huhifadhiwa. Ipakue kama faili moja, au tengeneza kiungo kwa ajili ya mtu asiye na akaunti. Mzigo ukifikishwa, stakabadhi inatumwa kwa barua pepe ikiwa na kiungo kama hicho ndani yake.",
  "help.business-note.step1": "Ndani ya nchi › Mizigo, kisha fungua mzigo. Hati ya mzigo hufungua hati kwenye dirisha linalopanda, ukurasa kwa ukurasa kama itakavyochapishwa, na Chapisha chini yake — “Hifadhi kama PDF” kwenye skrini ya kuchapisha huihifadhi kama faili. Hati ikishahifadhiwa, Shiriki hapo hutuma kiungo chake, kamwe si faili.",
  "help.business-note.step2": "Msafirishaji akishachukua bidhaa, bonyeza Pakua hati hii na picha zake. Unapata faili moja: hati, kila nakala yake kama ilivyotiwa sahihi, na picha zake. Kwenye simu kitufe kinasema Shiriki, na kufungua dirisha la kushiriki la simu yako.",
  "help.business-note.step3": "Ili kumpa hati mtu asiye na akaunti, fungua “Hati” kwenye mzigo, angalia chini ya Viungo vya hati hii na ubonyeze Tengeneza kiungo cha kupitisha. Kisha bonyeza Kitume au Kinakili, na utume kiungo kwenye mazungumzo, ujumbe au barua pepe yako mwenyewe. Kiungo kinaonyeshwa mara moja tu, kwa sababu hatuhifadhi nakala yake.",
  "help.business-note.step4": "Ili kusimamisha kiungo, bonyeza Kighairi kwenye mstari wake, kisha Ndiyo, kighairi. Kiungo kilichoghairiwa hakiwezi kuwashwa tena. Mstari kisha unasema nani alikighairi.",
  "help.business-note.note1": "Mzigo ukifikishwa, mtu aliyeutangaza anatumiwa stakabadhi kwa barua pepe yake mwenyewe ya kurejesha akaunti, pamoja na kitufe: Pata hati ya mzigo. Ikiwa mtu huyo ameondoka kwenye biashara, au hajatoa anwani ya barua pepe, wamiliki ndio wanaotumiwa barua pepe badala yake.",
  "help.business-note.note2": "Kitufe kilicho kwenye barua pepe ni kiungo kama vingine. Kimeorodheshwa chini ya Viungo vya hati hii, pamoja na anwani kilipotumwa, faili limechukuliwa mara ngapi, na kinafanya kazi hadi lini.",
  "help.business-note.note3": "Mtu anapotolewa kwenye biashara, au anapoiacha, viungo vilivyotumwa kwake kwa barua pepe vinasimama mara moja. Vivyo hivyo mtu anapobadilisha barua pepe yake mwenyewe ya kurejesha akaunti: viungo vilivyotumwa kwa anwani ya zamani vinasimama. Viungo vilivyotengenezwa ili biashara ivipitishe vinaendelea kufanya kazi hadi uvighairi.",
  "help.business-note.note4": "Kiungo hufungua hati bila kuingia, kwa yeyote aliye nacho. Kinafanya kazi kwa siku 30 na kinatoa faili mara zisizozidi 25. Hati inaweza kuwa na viungo vitano vinavyofanya kazi kwa wakati mmoja. Ghairi kimoja ili kutengeneza kingine.",
  "help.business-note.note5": "Bei iliyo kwenye stakabadhi ni bei ambayo wewe na msafirishaji mlikubaliana. SeeBuyGet haishikilii pesa za mizigo yako, na stakabadhi si ankara.",
  "help.business-note.note6": "Mtazamaji anaona viungo na anaweza kupakua faili, lakini hawezi kutengeneza wala kughairi kiungo.",
  "help.business-note.note7": "Ikiwa kiungo chako mwenyewe kilisimama kwa sababu ulibadilisha anwani yako ya barua pepe, fungua mzigo na utengeneze kipya. Hati yenyewe bado ipo.",
  "help.business-runs.title": "Hifadhi nafasi kwenye safari ya msafirishaji",
  "help.business-runs.summary": "Malori yanayoondoka hata hivyo, yenye nafasi kwa bidhaa zako. Bei ni ya msafirishaji mwenyewe, nawe unamlipa moja kwa moja.",
  "help.business-runs.step1": "“Ndani ya nchi › Nafasi kwenye safari” inaorodhesha safari zenye nafasi: zinakokwenda, zinapoondoka, kiwango cha bei cha msafirishaji, na jinsi wanavyotaka kulipwa.",
  "help.business-runs.step2": "Fungua moja, sema unachotuma na uzito wake, na uulize kingegharimu kiasi gani. Ihifadhi kwa bei hiyo.",
  "help.business-runs.step3": "Uhifadhi wako umeorodheshwa juu ya safari. Fungua mmoja kwa ajili ya hati yake ya mzigo, kiungo chake cha ufuatiliaji, au kurudisha nafasi.",
  "help.business-runs.step4": "Kiungo cha ufuatiliaji hufungua ukurasa ambao yeyote anaweza kusoma bila akaunti: imehifadhiwa, barabarani tangu msafirishaji anapoweka alama kuwa safari imeondoka, kisha imefikishwa na kwa nani. Mtumie yeyote anayepokea bidhaa. Hauonyeshi bei, wala bidhaa za mtu mwingine yeyote kwenye lori hilo hilo.",
  "help.business-contracts.title": "Agiza kutoka kwa msafirishaji chini ya mkataba",
  "help.business-contracts.summary": "Ikiwa kampuni ya magari inakubebea chini ya mkataba, mizigo yako inaweza kwenda moja kwa moja kwa kampuni hiyo badala ya kwenye ubao wa wazi.",
  "help.business-contracts.step1": "Msafirishaji wako anarekodi mkataba kwenye programu yake ya Fleet na kukutumia msimbo. Mmiliki anafungua Wasafirishaji, chini ya Washirika (kwenye simu, chini ya Zaidi), anaubandika na kugusa Iunganishe. Msimbo unafanya kazi mara moja tu.",
  "help.business-contracts.step2": "Unapotangaza mzigo, chagua msafirishaji huyo chini ya Nani anaubeba, na siku ambayo lazima ufike. Kesho imejazwa kwa ajili yako.",
  "help.business-contracts.step3": "Mzigo unaonekana kama Kwa msafirishaji wako hadi wauweke kwenye lori. Msafirishaji wako akishakubali mpango wake wa siku hiyo, mzigo pia unasema takriban lini umepangwa kufika. Kiungo chake cha ufuatiliaji na hati ya mzigo vinafanya kazi kama vya mzigo mwingine wowote.",
  "help.business-contracts.note1": "Bei na jinsi unavyolipa viko kwenye mkataba wako mwenyewe na msafirishaji. SeeBuyGet inahifadhi oda, hati na ufuatiliaji — kamwe si pesa.",
  "help.business-contracts.note2": "Mmiliki anaweza kumaliza mkataba chini ya Wasafirishaji. Mizigo iliyokwisha agizwa bado inafikishwa.",
  "help.business-contracts.note3": "Oda iliyo kubwa kuliko gari moja linavyobeba inaweza kuletwa kwa mizigo kadhaa na msafirishaji wako. Unaarifiwa chini ya kengele, kila mzigo unasema Mzigo 1 kati ya 2 kwenye orodha yako, na kiungo chochote cha ufuatiliaji kinaonyesha yote.",
  "help.business-contracts.note4": "Ikiwa mpango wa siku wa msafirishaji wako una mzigo unaofika nje ya muda wa ufikishaji ulioomba, unaarifiwa chini ya kengele, na mzigo unasema Nje ya muda wako pamoja na takriban lini umepangwa na kwa kiasi gani. Muda wa mpango ni makadirio na msafirishaji wako bado anaweza kupanga siku upya. Ikiwa haiwezekani, zungumza na msafirishaji wako.",
  "help.business-contracts.note5": "Ikiwa mpango wa siku wa msafirishaji wako unaacha mzigo bila gari, unaarifiwa chini ya kengele, na mzigo unasema Hauko kwenye gari pamoja na sababu: hakuna nafasi siku hiyo, hakuna gari linaloweza kuubeba, ni mzito kuliko gari lao kubwa zaidi, au mahali ambapo hapakupatikana kwenye ramani. Zungumza na msafirishaji wako, kwa sababu siku bado inaweza kupangwa upya. Unaarifiwa tena mzigo ukiwa kwenye gari.",
  "help.business-contracts.note6": "Muda ambao mzigo umepangwa ni makadirio ya msafirishaji wako. Unauona kwenye programu ya Business mara tu msafirishaji wako anapokubali mpango wake. Yeyote aliye na kiungo cha ufuatiliaji anaona siku tangu mwanzo, na takriban saa ngapi tu mzigo ukishakuwa barabarani.",
  "help.business-contracts.note7": "Mzigo ukifikishwa, arifa na mzigo vinasema ulikabidhiwa saa ngapi na kama ilikuwa ndani ya muda ulioomba: ndani yake, muda gani baada yake, au muda gani kabla. Saa ni ya msafirishaji wako mwenyewe.",
  "help.business-contracts.note8": "Ikiwa mzigo haujafika nusu saa baada ya muda ambao msafirishaji wako alipanga, unaarifiwa chini ya kengele kwamba unachelewa, na mzigo unasema Unachelewa. Unaarifiwa mara moja zaidi siku yake nzima ikipita. Muda wa mpango ni makadirio, kwa hiyo hii ni sababu ya kumpigia simu msafirishaji wako, si uthibitisho kwamba kuna tatizo.",
  "help.business-contracts.note9": "Ikiwa mzigo ni wa leo na msafirishaji wako hajauweka kwenye gari lolote kazi ya siku ikishaanza — saa moja asubuhi kwa saa ya msafirishaji wako — unaarifiwa chini ya kengele, na mzigo unasema Hauko kwenye gari. Hiyo ni siku ambayo msafirishaji wako hajaipanga, mzigo ulioagizwa baada ya mpango kutengenezwa, au mzigo uliokosa safari yake. Mzigo ulioagizwa kwa siku hiyo hiyo unapewa saa moja kwanza. Unaarifiwa tena ukiwa kwenye gari, iwe msafirishaji wako alipanga siku upya au aliuweka kwa dereva kwa mkono.",
  "help.business-clients.title": "Tuma kwa niaba ya wateja wako kama wakala wao",
  "help.business-clients.summary": "Wakala wa mtumaji huweka daftari la biashara anazotuma kwa niaba yake. Mzigo au uhifadhi uliofanywa kwa ajili ya mmoja wao unamtaja mteja kama mtumaji, na wewe kama wakala wake.",
  "help.business-clients.step1": "“Wateja › Ongeza mteja”: jina lake lililosajiliwa, nchi, anwani na nani wa kuulizia.",
  "help.business-clients.step2": "Unapotangaza mzigo au kuhifadhi nafasi, chagua mteja chini ya Imetumwa kwa niaba ya. Anakuwa mtumaji kwenye hati ya mzigo; wewe unatajwa kama wakala aliyeuhifadhi.",
  "help.business-clients.step3": "Fungua mteja ili kuona kila kitu kilichotumwa kwa niaba yake — mizigo na nafasi kwenye safari vilevile — pamoja na kiungo cha ufuatiliaji cha kila kimoja cha kumpa. Hakihitaji akaunti.",
  "help.business-clients.step4": "Mteja ambaye hufanyi naye kazi tena anaweza kuwekwa kwenye kumbukumbu za zamani. Kilichotumwa kwa niaba yake kinaendelea kumtaja.",
  "help.business-clients.note1": "Bidhaa za wateja kadhaa kwenye safari moja ni uhifadhi kadhaa kwenye safari hiyo, mmoja kwa kila mteja — kila mmoja na hati yake ya mzigo.",
  "help.quotations.title": "Fuatilia nukuu ya bei na malipo yake",
  "help.quotations.summary": "Popote bei ilipo — ada ya wakala wa forodha, bei ya msafirishaji — SeeBuyGet huhifadhi nukuu ya bei, ankara ya proforma na kama imelipwa, mahali pamoja. Kamwe haishughulikii pesa.",
  "help.quotations.step1": "Wakala wa forodha anatoa nukuu ya ada yake kwenye uagizaji au usafirishaji nje, pamoja na nambari yake mwenyewe ya nukuu. Mwagizaji au muuzaji nje anaikubali.",
  "help.quotations.step2": "Kwa mzigo — chini ya “Malipo” kwenye mzigo — au uhifadhi, bonyeza Fuatilia malipo kwa msafirishaji: bei iliyokubaliwa imejazwa, na unaweza kuibadilisha iwe ile ambayo msafirishaji aliweka kwenye ankara.",
  "help.quotations.step3": "Upande wowote unaweza kuambatisha ankara ya proforma. Inahifadhiwa kama ilivyokabidhiwa.",
  "help.quotations.step4": "Ikishalipwa, bonyeza Thibitisha kuwa imelipwa na uongeze rejea ya malipo ikiwa unayo. Rudisha kuwa wazi hutendua hilo.",
  "help.quotations.note1": "Kila badiliko huhifadhiwa pamoja na jina la aliyelifanya, ili swali la “nani alisema hii imelipwa” liweze kujibiwa kila mara.",
  "help.shop-shelves.title": "Panga rafu zako za uchukuaji",
  "help.shop-shelves.summary": "Kila kifurushi kinachofika ili kuchukuliwa kinapewa nafasi yake yenyewe, inayotajwa kwa rangi na nambari, kama Red-2. Duka linasema lina mistari mingapi na safu ngapi za rangi.",
  "help.shop-shelves.step1": "Programu ya Shop, Duka langu, “Panga rafu”. Mistari ina nambari na kila safu ni rangi. Chagua una mingapi ya kila moja, kisha “Hifadhi rafu”.",
  "help.shop-shelves.step2": "Kifurushi kimoja kutoka basini: unapoweka alama kuwa kimefika, programu inataja nafasi yake. Kiweke hapo.",
  "help.shop-shelves.step3": "Mfuko: baada ya “Pokea na uweke rafuni” programu inaorodhesha kila nafasi na vifurushi vinavyoingia humo, chini ya “Weka kila kifurushi kwenye nafasi yake”. Bonyeza “Vyote viko rafuni” vikishaingia.",
  "help.shop-shelves.step4": "Mteja anapokuja, programu inaonyesha nafasi ile ile. Nafasi inaweza kupatikana tena chini ya Toa, kando ya kila kifurushi kinachosubiri.",
  "help.shop-shelves.step5": "Gusa nafasi tupu ili kuifanya nafasi ya pamoja. Barua na vifurushi vidogo kisha vinaishiriki, hadi kumi na viwili, badala ya kila kimoja kuchukua nafasi nzima.",
  "help.shop-shelves.note1": "Mfuko huwekwa rafuni wote au hauwekwi kabisa. Ikiwa hakuna nafasi kwa kila kifurushi kilicho ndani yake, mfuko unakataliwa na hakuna kinachowekwa rafuni: kabidhi vifurushi vinavyosubiri, au ongeza mstari, kisha uchanganue mfuko tena. Kifurushi kimoja kisichopata nafasi hubaki na dereva vivyo hivyo.",
  "help.shop-shelves.note2": "Nafasi iliyo na kifurushi haiwezi kuondolewa. Kabidhi kifurushi kwanza, au uiache rafu kuwa kubwa ya kutosha kwa nafasi hiyo. Programu inasema ni nafasi ipi na kifurushi kipi.",
  "help.shop-shelves.note3": "Rafu ina angalau nafasi 6 na safu za rangi zisizozidi 10, kwa sababu kila safu ni rangi yake yenyewe.",
  "help.shop-shelves.note4": "Nafasi inakuwa wazi tena mara tu kifurushi chake kinapochukuliwa. Kifurushi chenye tatizo lililoripotiwa kwenye kaunta yako hubaki na nafasi yake, na bado kinaweza kukabidhiwa.",
  "help.shop-shelves.note5": "Kabla hujapokea kifurushi, programu inasema kinalindwa na nini. “Kinabebwa na …, na hakina bima kutoka kwake” ina maana kampuni yenyewe hailipi dai lolote: mwambie mteja, na uweke alama kwenye kisanduku kinachosema ulimwambia. Kitu kikienda kombo anapata ripoti ya madai ya uharibifu ya kupeleka kwa kampuni yake mwenyewe ya bima.",
  "help.shop-shelves.note6": "Kifurushi cha biashara kinachokwenda kwenye mojawapo ya maeneo ya biashara hiyo yenyewe huwekwa rafuni kama kawaida, na kuorodheshwa chini ya Toa, katika “Kwa mlango wa biashara yenyewe”. Kiache rafuni hadi dereva amechukua mzigo wake, kisha ukikabidhi kwa dereva huyo tu: “Changanua pasi yake”, kisha “Kikabidhi”.",
  "help.message-shop.title": "Tuma ujumbe kwa duka au kwa mteja",
  "help.message-shop.summary": "Mtu anayechukua kifurushi na duka linalokishikilia wanaweza kutumiana ujumbe kukihusu, ndani ya SeeBuyGet.",
  "help.message-shop.step1": "Programu ya Send: Vifurushi vyangu, fungua kifurushi, kisha “Tuma ujumbe kwa duka”. Sema utakuja lini, au uliza wanafungua saa ngapi.",
  "help.message-shop.step2": "Programu ya Shop: “Kabidhi kifurushi › Kinasubiri kuchukuliwa › Ujumbe” kando ya kifurushi.",
  "help.message-shop.step3": "Duka linaweza kumfikia tu mteja ambaye ameingia kwenye programu ya Send kwa nambari ya simu aliyolipatia duka la mtandaoni. Ikiwa hakuna wa kufikiwa, programu inasema hivyo.",
  "help.message-shop.note1": "Ni ninyi wawili tu mnaoweza kuusoma, na hakuna chochote ndani yake kinachoweza kuhaririwa au kufutwa. Msimbo wa kuchukua kamwe hautumwi kwenye ujumbe — unabaki kwenye kifurushi katika programu ya Send.",
  "help.message-shop.note2": "Picha kamwe haitumwi ikiwa huru kwenye mazungumzo: inawekwa kwenye faili la kifurushi — kama uharibifu, hati au uthibitisho — na mazungumzo yanaonyesha kadi inayoielekeza. Duka, mtu anayechukua kifurushi na mtumaji wake wanaweza kuifungua.",
  "help.thermal-labels.title": "Chapisha lebo kwenye karatasi au printa ya joto",
  "help.thermal-labels.summary": "Kila lebo huchapishwa kwenye karatasi kutoka kwenye ukurasa inayofungua, au kwenye printa ya lebo ya joto — aina ya 100 × 150 mm ambayo kampuni za usafirishaji wa vifurushi hutumia — kutoka kwenye faili.",
  "help.thermal-labels.step1": "Programu ya Shop: baada ya kupokea kifurushi, “Fungua na uchapishe lebo” huifungua kwenye dirisha linalopanda, kwenye ukurasa wake kama inavyochapishwa, na Chapisha chini yake; “Printa ya joto (ZPL)” huihifadhi kama faili kwa ajili ya printa ya lebo.",
  "help.thermal-labels.step2": "Programu ya Store: vile vile viwili oda ikishalipwa — na tena baadaye, kutoka kwenye oda chini ya Oda: “Chapisha lebo tena”, inayofungua dirisha lile lile linalopanda, au “Printa ya joto (ZPL)”. Programu ya Hub huchapisha lebo mpya ya kifurushi kilichoghairiwa kwa njia hiyo hiyo.",
  "help.thermal-labels.step3": "Programu ya Business: Ndani ya nchi › Mizigo, fungua mzigo, kisha “Hati”, chini ya Hati za bidhaa: “Chapisha lebo” kwa karatasi — inafunguka kwenye dirisha linalopanda, lebo moja kwa ukurasa kama inavyochapishwa, na Chapisha chini yake — na “Printa ya joto (ZPL)” kwa faili lenye lebo moja kwa kila kipande.",
  "help.thermal-labels.step4": "Tuma faili kwa printa kama lilivyo: kwa zana ya mtengenezaji wa printa mwenyewe (kwa Zebra, Zebra Setup Utilities: “Open printer tools › Action › Send file”), au kwa printa ya lebo iliyoshirikiwa kwenye kompyuta yako.",
  "help.thermal-labels.note1": "Faili limeandikwa kwa printa ya 203 dpi iliyowekwa lebo za 100 × 150 mm. Weka ukubwa wa lebo kwenye printa kwanza: printa iliyowekwa ukubwa mwingine huichapisha ikiwa imekatika.",
  "help.thermal-labels.note2": "Lebo kamwe haibebi msimbo unaoachilia kifurushi — ni ufunguo wake wa ufuatiliaji wa umma tu.",
  "help.bag-seals.title": "Funga, chukua na upokee mfuko wenye lakiri",
  "help.bag-seals.summary": "Mfuko huondoka ukiwa umefungwa — kwa lakiri yenye nambari, nambari yake ikiwa imeandikwa na mfuko ukiwa umepigwa picha, au ukipigwa picha ukiwa umefungwa bila lakiri — na dereva anayeuchukua, na yeyote anayeupokea, husoma lakiri na kuipiga picha: dereva kabla haujaondoka, mpokeaji kabla ya kuufungua.",
  "help.bag-seals.step1": "Programu ya Shop, katika Weka vifurushi kwenye mfuko: kabla ya “Funga mfuko”, chagua lakiri yenye nambari (inapendekezwa), ivute ikaze kupitia zipu, andika nambari yake kama ilivyochapishwa na upige picha mfuko lakiri ikionekana — au, bila lakiri, piga picha mfuko ukiwa umefungwa.",
  "help.bag-seals.step2": "Programu ya Hub, katika Pakia mfuko: mfuko ambao bado haujafungwa hufungwa vivyo hivyo kabla beji ya dereva haijachanganuliwa. Programu ya Store, kwenye Sehemu yako ya kupakia: “Funga mfuko” inaomba vivyo hivyo.",
  "help.bag-seals.step3": "Mfuko ambao haujafungwa haupakiwi: programu inasema “Funga mfuko kwanza”.",
  "help.bag-seals.step4": "Programu ya Driver, katika Mizigo yangu: ukichukua mfuko mwenyewe, soma nambari kwenye lakiri yake (kamwe huonyeshwi), piga picha mfuko unapouchukua na useme uko kama ulivyofungwa. Nambari isiyo ile uliyofungwa nayo inasemwa papo hapo, kuwe na mtandao au la.",
  "help.bag-seals.step5": "Mfuko ambao duka au kituo kinakupakia kwa pasi iliyo kwenye simu yako: chini ya Mizigo yangu, “Soma lakiri yake”. Haupokelewi popote hadi umefanya hivyo; bila mtandao, usomaji wako unasubiri kwenye simu yako na kutumwa mtandao ukiwepo.",
  "help.bag-seals.step6": "Kupokea — programu ya Shop, Pokea mfuko; programu ya Hub, Shusha mfuko: uchanganue, soma nambari kwenye lakiri yake (kamwe huonyeshwi), upige picha kama ulivyofika, na useme kama uko kama ulivyofungwa. Hapo tu ndipo unafunguliwa.",
  "help.bag-seals.step7": "Nambari isiyo ile uliyofungwa nayo: isome tena; ikiwa bado si ile ile, “Bado haifanani? Iripoti”. Lakiri iliyovunjika au mfuko uliokatwa: “Umekatwa, umefunguliwa au lakiri imevunjika”, kisha uripoti. Mfuko unazuiliwa na kitengo cha uendeshaji cha SeeBuyGet kinaarifiwa; unapokelewa uendeshaji ukishauachilia.",
  "help.bag-seals.step8": "Mfuko unaouchukua au kuubeba ambao si sawa: “Kuna kitu si sawa na mfuko huu”. Unazuiliwa ulipo na kitengo cha uendeshaji cha SeeBuyGet kinaarifiwa.",
  "help.bag-seals.note1": "Lakiri moja yenye nambari hufunga mfuko mmoja: nambari iliyo tayari kwenye mfuko ambao bado unasafiri inakataliwa. Lakiri na printa za lebo haziuzwi ndani ya SeeBuyGet.",
  "help.held-on-the-road.title": "Ripoti kuzuiliwa na polisi au forodha",
  "help.held-on-the-road.summary": "Sema kutoka kwenye mzigo katika programu ya Driver: kitengo cha uendeshaji cha SeeBuyGet, mtumaji wa mzigo na ofisi ya kampuni yako ya magari wanaarifiwa mara moja, na tena unapoachiliwa.",
  "help.held-on-the-road.step1": "Programu ya Driver, Mizigo yangu: chini ya mzigo ulio barabarani, “Umezuiliwa na polisi au forodha?”. Chagua nani anauzuia — polisi, forodha au mtu mwingine — na, ukiweza, nani na wapi (“Polisi wa trafiki, Athi River”) na walisema nini au wanataka nini. Kisha “Sema — uendeshaji unaarifiwa”.",
  "help.held-on-the-road.step2": "Kadi ya mzigo inasema umezuiliwa, tangu lini, na kwamba uendeshaji, mtumaji wa mzigo na ofisi yako wameshaarifiwa — pamoja na nambari ya dawati la kupigia, kwa nchi ambako mzigo ulichukuliwa na ile unakokwenda. Igusa ili kupiga simu. Bila mtandao inasubiri kwenye simu yako, ikiwa na tarehe ulipolisema, na kutumwa mtandao ukiwepo; nambari za dawati tayari ziko kwenye simu yako.",
  "help.held-on-the-road.step3": "Haufikishwi ukiwa umezuiliwa. Unapoendelea na safari, “Tumeachiliwa — tunaendelea”.",
  "help.held-on-the-road.step4": "Programu ya Business: mzigo unasema “Umezuiliwa na mamlaka”, na nani na tangu lini, hadi uachiliwe; unaarifiwa mara zote mbili kwenye kengele yako, na mfumo wako unapokea load.held na load.let_go.",
  "help.held-on-the-road.note1": "Ukurasa wa ufuatiliaji, ambao yeyote aliye na ufunguo wa lebo anausoma, unasema tu kwamba mzigo umezuiliwa njiani na tangu lini: kamwe si na nani wala wapi, na kamwe si simu yako iko wapi. Gari lililozuiliwa pale dereva wake alisema limezuiliwa si gari lililosimama bila sababu.",
  "help.load-seals.title": "Weka lakiri kwenye mzigo kabla ya kuchukuliwa",
  "help.load-seals.summary": "Pale unapoweka lakiri kwenye mzigo, unaandika kila lakiri kwenye programu ya Business kabla bidhaa hazijachukuliwa. Dereva anasoma kila moja mlangoni wakati wa kuchukua, na kila lakiri inarekodiwa pamoja na kile inachofunga: kontena na misimbo ya vipande vya mzigo.",
  "help.load-seals.step1": "Fungua mzigo kwenye programu ya Business, kisha “Hati”, na uende kwenye Lakiri. Kabla ya kuchukuliwa, bonyeza Andika lakiri: nambari yake kama ilivyochapishwa juu yake, daraja lake kama lilivyowekwa alama (ISO 17712: H, S au I), mtengenezaji ikiwa anaonekana, na nani aliyeifunga — lakiri yako mwenyewe, au ya forodha.",
  "help.load-seals.step2": "Piga picha tatu unapoweka lakiri: mzigo ukiwa wazi, umezuiliwa na kufungwa imara; milango ikiwa imefungwa na nambari ya gari au ya kontena na lakiri vikionekana; lakiri kwa karibu, nambari yake yote ikisomeka. Kisha bonyeza Andika lakiri.",
  "help.load-seals.step3": "Kila lakiri huhifadhiwa pamoja na kile inachofunga: kontena ambalo mzigo unalitaja na misimbo ya vipande vya mzigo (SSCC), kama ilivyo unapoiandika. Mstari wake unasema hivyo — kwenye kontena …, juu ya vipande vilivyowekwa lebo kwa ajili ya mzigo huu — na hati ya mzigo inasema hivyo pia.",
  "help.load-seals.step4": "Wakati wa kuchukua dereva anasoma kila lakiri mlangoni na kuipiga picha. Nambari isiyo ile uliyoandika, na mzigo hauondoki.",
  "help.load-seals.step5": "Baada ya kuchukuliwa lakiri zinabaki kwenye kumbukumbu: ile ambayo forodha ilibadilisha kwenye kituo cha ukaguzi, ile iliyokutwa imevunjika barabarani, na ukaguzi wa mlangoni wakati wa ufikishaji vyote vinasemwa kwenye mstari wa lakiri.",
  "help.load-seals.note1": "Dereva kamwe haonyeshwi nambari ya lakiri kabla ya kuchukua: anaisoma mlangoni, ili nambari iliyotafutwa isiweze kusimama badala ya iliyosomwa.",
  "help.load-seals.note2": "Kama lakiri inahitajika ni kanuni ya kampuni ya nchi ambako bidhaa zako zinachukuliwa: kwa mizigo inayovuka mpaka, kwa sehemu za safari za kontena, au la hasha. Pale inapohitajika, Lakiri inasema hivyo na kutaja kampuni, na bidhaa hazichukuliwi hadi lakiri iandikwe. Pale haihitajiki, lakiri ni chaguo lako; pale unapoweka lakiri kwenye mzigo, andika kila lakiri iliyo juu yake.",
  "help.tampering.title": "Zuia na uripoti bidhaa zinazoonekana kufunguliwa",
  "help.tampering.summary": "Chochote kinachoonekana kufunguliwa huzuiliwa kilipo: kinapigwa picha, kinaripotiwa, na hakikabidhiwi kwa yeyote hadi kitengo cha uendeshaji cha SeeBuyGet kikiangalie na kukiachilia.",
  "help.tampering.step1": "Programu ya Driver, wakati wa kuchukua: lakiri iliyosomwa mlangoni ambayo si nambari iliyoandikwa — isome tena; ikiwa bado si ile ile, gusa “Bado haifanani? Iripoti”, piga picha lakiri ilivyo, na utume.",
  "help.tampering.step2": "Programu ya Driver, barabarani au mlangoni: “Kuna kitu si sawa na mzigo huu” kwa kifuniko kilichokatwa; kwa mpokeaji, sema lakiri si kama hati inavyosema na uziripoti kwanza. Lakiri iliyokutwa imevunjika barabarani inaripotiwa kama awali, na inazuia mzigo pia.",
  "help.tampering.step3": "Programu ya Shop: kazi ya “Kifungashio kimekatwa au kimefunguliwa” — changanua kifurushi, kipige picha kilivyo, kiripoti. Programu ya Hub: kwenye skrini ya kupanga, “Kifungashio kimekatwa au kimefunguliwa? Kiripoti”.",
  "help.tampering.step4": "Kikiwa kimezuiliwa: kiache kimefungwa, kiweke kando, usikifungue zaidi. Hakiingii kwenye mfuko wowote, hakipandi basi lolote wala hakiendi kwa mtu yeyote; programu inakataa kila moja ya haya na kusema kwa nini.",
  "help.tampering.step5": "Dashibodi: kesi ya “Imezuiliwa: dalili za kuchezewa zimepatikana” inaonyesha kilichopatikana, na nani, picha na SSCC. Kiachilie ukishajua kilichotokea, pamoja na kilichopatikana na kilichofanyika: kesi inafungwa kwa maneno hayo.",
  "help.tampering.note1": "Uendeshaji unaarifiwa mara moja, pamoja na mtumaji wa mzigo au duka la mtandaoni ambalo bidhaa ni zake; mpokeaji kamwe hatumiwi ujumbe wa maandishi. Bila mtandao ripoti inasubiri kwenye simu pamoja na picha yake na kutumwa inapowezekana.",
  "help.tampering.note2": "Kuachilia hakuhukumu chochote: kunaruhusu bidhaa kusafiri tena. Kilichopatikana hubaki kwenye kumbukumbu na kwenye hati ya mzigo, kamwe si pamoja na jina la aliyekipata.",
  "help.scan-a-parcel.title": "Changanua kifurushi kwa QR au msimbo pau wa duka la mtandaoni",
  "help.scan-a-parcel.summary": "Kisanduku cha kifurushi kwenye kaunta au kituoni kinapokea QR yetu — au, kwa kifurushi cha duka la mtandaoni, msimbo pau wa GS1-128 ulio chini ya SSCC kwenye lebo yake. Chochote kati ya hivyo kinapata kifurushi kile kile.",
  "help.scan-a-parcel.step1": "Programu ya Shop: katika Pokea, Kabidhi, Mfuko na Toa, changanua QR yetu kwenye lebo kama kawaida — au msimbo pau ulio chini ya SSCC kwenye kifurushi cha duka la mtandaoni. Msimbo wa kifurushi unajaza kisanduku, na skrini inaendelea kama ilivyo kwa QR.",
  "help.scan-a-parcel.step2": "Programu ya Hub: wakati wa kupanga, vivyo hivyo — msimbo wowote kati ya hiyo kwenye lebo unapata kifurushi kilicho kituoni.",
  "help.scan-a-parcel.step3": "Msimbo pau usiotaja kifurushi chochote ambacho duka hili au kituo hiki kinashughulikia husema hivyo: changanua QR yetu kwenye lebo badala yake.",
  "help.scan-a-parcel.step4": "Msimbo pau wa kipande cha mzigo hupata mzigo wake, pale programu hii inapofungua mizigo.",
  "help.scan-a-parcel.note1": "Msimbo pau wa duka la mtandaoni hupata tu vifurushi ambavyo duka hili linapokea au kutoa, au vilivyo kituoni hapa — au ambavyo duka la mtandaoni lilipanga kukabidhi kwenye kituo hiki, kwa wingi: kwa mtu mwingine yeyote hautaji chochote, kwa hiyo kamwe si njia ya kupitia vifurushi vya duka la mtandaoni.",
  "help.hub-bulk.title": "Kabidhi vifurushi kituoni, kwa wingi",
  "help.hub-bulk.summary": "Duka la mtandaoni lenye vifurushi vingi linaweza kuvileta kituoni kwenye paleti au katika katoni, siku ambayo kituo kinapokea. Kituo kinahesabu kilichokuja mlangoni mwake na kuchanganua kila kifurushi kuingia: tangu uchanganuzi huo kifurushi ni cha kituo kukipanga.",
  "help.hub-bulk.step1": "Programu ya Hub, Zinazoingia: mmiliki wa kituo anagusa “Pokea vifurushi kwa wingi” na kusema siku na saa kinazopokea, kwa saa yake yenyewe, na ni mizigo mingapi inayowasili kinachoweza kushusha kwa wakati mmoja — na kinatoza nini kwa kila paleti, katoni, kizimba au gunia; aina iliyoachwa tupu ni bure. “Acha kupokea vifurushi kwa wingi” husimamisha mipango mipya; kile ambacho maduka ya mtandaoni yalishapanga bado kinakuja.",
  "help.hub-bulk.step2": "Programu ya Store, Safirisha: pale kifurushi kinapoanzia, kituo kinachopokea vifurushi kwa wingi kinapendekezwa kando ya maduka, kwa bei kuanzia kituoni — bila duka wala barabara kabla yake.",
  "help.hub-bulk.step3": "Programu ya Store, Sehemu ya kupakia, chini ya “Kwenda kituo, kwa wingi”: “Panga ujio”. Weka alama kwenye vifurushi vyake, sema vinakuja juu ya nini — paleti, katoni, vizimba au magunia — na ngapi, chagua siku ambayo kituo kinapokea, na uongeze rejea yako mwenyewe na nani anavileta. Vipande vinalipwa kutoka kwenye salio lako unapopanga; vyovyote visivyohesabiwa mlangoni vinarudi.",
  "help.hub-bulk.step4": "Programu ya Hub, Zinazoingia: kinachotarajiwa leo kiko chini ya “Mlangoni leo”. Kifungue, hesabu kilichokuja, ongeza chochote ulichoona, na uguse “Vimepokelewa mlangoni”.",
  "help.hub-bulk.step5": "Kisha changanua kila kifurushi kuingia: QR yetu, ufunguo wake wa ufuatiliaji au msimbo pau wa duka la mtandaoni. Msimbo usio kwenye ujio huu unakataliwa — weka kifurushi hicho kando, na uliambie duka la mtandaoni. Kifurushi kilichokatwa au kufunguliwa: kichanganue kuingia, kisha ukiripoti.",
  "help.hub-bulk.step6": "Kifurushi cha mwisho kinamaliza ujio. Baadhi havipo? “Imekamilika: vilivyobaki havikuja”: vinabaki kuwa vya duka la mtandaoni, na duka linaarifiwa. Kilichochanganuliwa kuingia kinasubiri pamoja na vifurushi vingine kupangwa.",
  "help.hub-bulk.step7": "Ujio ambao siku yake imepita bila chochote mlangoni: ufungue na uguse “Havikuja”. Duka la mtandaoni linaarifiwa, na linapanga vifurushi vyake tena.",
  "help.hub-bulk.note1": "Duka la mtandaoni linaona kila ujio kwenye Sehemu yake ya kupakia: vimepokelewa, kisichokuwepo, na kile kituo kilichoandika mlangoni mwake. Mfumo wake wenyewe unaarifiwa jinsi kila ujio ulivyoisha.",
  "help.hub-bulk.note2": "Hadi kifurushi kichanganuliwe kuingia bado ni cha duka la mtandaoni: kituo kinawajibika kwa kile kilichochanganua kuingia, si kwa kile kilichopangwa.",
  "help.gs1-codes.title": "Weka misimbo pau yako mwenyewe ya GS1 kwenye lebo",
  "help.gs1-codes.summary": "Kwa kiambishi cha kampuni ambacho GS1 ilikupa, kila kifurushi au kipande chako kinapata SSCC yake yenyewe, iliyochapishwa kama msimbo pau wa GS1-128 kando ya QR yetu: kile ambacho ghala linalopokea huchanganua kuingiza kwenye mfumo wake.",
  "help.gs1-codes.step1": "Programu ya Store: “Duka langu la mtandaoni › Misimbo pau ya GS1 kwenye vifurushi vyako › Toa kiambishi chako cha GS1”: kiambishi cha kampuni ambacho GS1 ilikupa, na tarakimu ya nyongeza ambayo mifumo yako haitumii.",
  "help.gs1-codes.step2": "Programu ya Business: Maelezo ya biashara, paneli ya GS1 — vivyo hivyo, kwa mizigo unayotangaza. Wakala wa usafirishaji anatoa kiambishi cha mteja mwenyewe kwenye kumbukumbu ya mteja huyo.",
  "help.gs1-codes.step3": "Tangu hapo kila kifurushi cha duka la mtandaoni, kikishalipiwa, na kila kipande cha mzigo kinapata SSCC yake: kwenye lebo iliyochapishwa, kwenye lebo ya joto, kwenye oda, na katika jibu la API ya usafirishaji kama “sscc”.",
  "help.gs1-codes.step4": "Imekataliwa kwa sababu biashara nyingine au duka lingine la mtandaoni linachapisha chini ya kiambishi hicho kwa tarakimu hiyo? Ikiwa kiambishi ni chako, gusa “Kiambishi hiki ni chetu” na utume picha au picha ya skrini ya leseni yako ya GS1. Wanaokitumia wanaarifiwa kwenye kengele yao na wana wiki moja kutuma yao; wafanyakazi wawili wa SeeBuyGet wanaamua ni cha nani, na kila mtu anasoma kwa nini.",
  "help.gs1-codes.note1": "Kamwe hatubuni kiambishi: GS1 pekee ndiyo hutoa. Hakuna msimbo unaotolewa mara mbili, na kifurushi au mzigo hubaki na misimbo uliyopewa ukibadilisha kiambishi au ukiacha.",
  "help.gs1-codes.note2": "Katika maduka na vituo vyetu msimbo pau wa kifurushi cha duka la mtandaoni hupata kifurushi chake, kama QR yetu inavyofanya; pia ndio ambao ghala linalopokea bidhaa huchanganua kuingiza kwenye mfumo wake.",
  "help.no-signal.title": "Fanya kazi bila mtandao",
  "help.no-signal.summary": "Programu inaendelea kufanya kazi kwa kile ilichojua mara ya mwisho, na inarekodi vifurushi unavyohamisha. Baadhi ya mambo yanasubiri muunganisho.",
  "help.no-signal.step1": "Kupokea kifurushi, kukikabidhi kwa basi, kukiweka rafuni, kuhamisha mfuko: vinarekodiwa kwenye simu mara moja, vikiwa na tarehe ulipovifanya, na kutumwa mtandao ukirudi. Mstari ulio juu unahesabu kinachosubiri kutumwa bado.",
  "help.no-signal.step2": "Unachoona ni kile ambacho programu ilipakia mara ya mwisho, na mstari ulio juu unasema hivyo, pamoja na saa.",
  "help.no-signal.step3": "Msimbo wako wa kuchukua unabaki kwenye simu yako kifurushi kikishaonekana katika Vifurushi vyangu — fungua programu mara moja ukiwa na mtandao.",
  "help.no-signal.step4": "Kuingia, kulipa na kukabidhi kifurushi kwenye kaunta kunahitaji muunganisho, vivyo hivyo bei, makubaliano na ujumbe wa sauti kwenye mazungumzo. Programu inasema waziwazi isipoweza kuyafanya.",
  "help.no-signal.step5": "Madereva: kumaliza zamu yako pia kunarekodiwa kwenye simu. Kuanza zamu na kuchukua ofa kunahitaji muunganisho; ofa ambayo hukuweza kuiona inaisha baada ya dakika kumi na haihesabiwi dhidi yako. Programu ya Fleet inaonyesha kila gari lilisikika lini mara ya mwisho.",
  "help.no-signal.step6": "Madereva: hati ya mzigo ya kila mzigo ulio wako huhifadhiwa kwenye simu yako wakati kuna mtandao, ili ifunguke kwenye kituo cha ukaguzi kisicho na mtandao — inasema ni nakala iliyohifadhiwa, na lini. Hati za mizigo ambayo si yako tena, na zote unapotoka, huondolewa. Kuvuka mpaka, ankara ya biashara ya mzigo huhifadhiwa kando ya hati yake, tangu kuchukuliwa, na kuondolewa pamoja nayo.",
  "help.no-signal.note1": "Usifute data ya programu wakati kuna kitu bado kinasubiri kutumwa: kumbukumbu ya ulichohamisha iko kwenye simu hadi itumwe.",
  "help.no-signal.note2": "Kifurushi au mfuko uliohamishwa, mzigo uliochukuliwa au kufikishwa, mpaka uliovukwa, joto lililopimwa, kuharibika kwa gari au hatari barabarani, zamu iliyoisha: vikitumwa baadaye, kila kimoja hubaki na saa ulipokifanya, kwa saa ya simu — kamwe si saa ambayo bado haijafika, kamwe si zaidi ya wiki moja nyuma, na kamwe si kabla ya hatua iliyotangulia. Mwisho wa zamu kamwe hauwekwi tarehe kabla ya simu yako kusikika mara ya mwisho katika zamu hiyo. Pale saa yake imeandikwa, kama kwenye ripoti ya madai ya uharibifu au hati ya mzigo, inasema pia SeeBuyGet ilisikia habari zake lini.",
  "help.no-signal.note3": "Ujumbe wa mazungumzo ulioandikwa bila mtandao unasubiri kwenye simu, na unatumwa wenyewe mtandao ukirudi. Upande mwingine unasoma uliuandika lini na ulifika lini, ili ujumbe unaofika kwa kuchelewa usichukuliwe kuwa mpya. Picha iliyowekwa kwenye faili bila mtandao inasubiri vivyo hivyo.",
  "help.consignment-note.title": "Hati ya mzigo (CMR)",
  "help.consignment-note.summary": "Kila mzigo hubeba hati moja tangu kutangazwa hadi ufikishaji, kwa mpangilio wa CMR: mtumaji, mpokeaji wa mzigo, msafirishaji na gari, bidhaa, makabidhiano na ufikishaji. Kuvuka mpaka inasema usafirishaji uko chini ya sheria gani: CMR pale nchi yoyote kati ya hizo ni mwanachama wake, itifaki ya barabara ya Ushoroba wa Kaskazini kati ya wanachama wake, au vinginevyo mkataba wake.",
  "help.consignment-note.step1": "Programu ya Shop: Mizigo, fungua mzigo, kisha “Hati ya mzigo”. Inafunguka kwenye dirisha linalopanda, ukurasa kwa ukurasa kama itakavyochapishwa. Chapisha hufungua skrini ya kuchapisha ya simu; chagua “Hifadhi kama PDF” hapo ili kuihifadhi kwa vitabu vyako vya hesabu. Kwenye iPhone, “Fungua ili kuchapisha” huifungua kwenye ukurasa wake wenyewe: gusa Shiriki, kisha Chapisha.",
  "help.consignment-note.step2": "Programu ya Driver: “Mizigo › Hati ya mzigo” chini ya mzigo — ionyeshe kwenye mizani, mpakani au getini kwa mpokeaji. “Ukubwa halisi” huonyesha ukurasa ukiwa mkubwa kama unavyochapishwa, ili kuusoma kwenye simu.",
  "help.consignment-note.step3": "Programu ya Driver, kuvuka mpaka: ukishachukua bidhaa, “Ankara ya biashara” iko chini ya mzigo kando ya hati — karatasi ambayo afisa anaiomba. Haionyeshwi kabla ya kuchukua, wala kwenye mzigo wa ndani ya nchi moja, wala kwa ofisi ya kampuni yako ya magari: ni karatasi ya mtumaji wa mzigo.",
  "help.consignment-note.step4": "Programu ya Fleet: “Mapato › Hati ya mzigo” kwenye safari yoyote ya mzigo.",
  "help.consignment-note.note1": "Kila kisanduku kinajazwa kutoka kwenye kitendo kilichorekodiwa — kutangaza, ukaguzi wa usalama wa mzigo wakati wa kuchukua, ripoti ya kushusha wakati wa ufikishaji. Kisanduku kinachosema “hakijarekodiwa” hakijarekodiwa; hakuna kinachoandikwa kwa mkono. Mnunuzi wa oda ya duka la mtandaoni anatajwa kama mnunuzi, kamwe si kwa nambari ya simu.",
  "help.consignment-note.note2": "Mzigo ukifikishwa, duka lililoutangaza linatumiwa stakabadhi kwa barua pepe pamoja na kitufe: Pata hati ya mzigo. Kitufe hufungua hati, kila nakala yake na picha zake kama faili moja, bila kuingia, kwa siku 30. Yeyote ambaye barua pepe hiyo inatumwa kwake anaweza kuifungua pia, kwa hiyo itume tu kwa mtu anayepaswa kuwa na hati.",
  "help.consignment-note.note3": "Duka linaona kiungo hicho kwenye hati yenyewe. Programu ya Shop: “Kumbukumbu › Hati”, kisha fungua hati, na uangalie chini ya Viungo vya hati hii. Inaonyesha anwani ambako barua pepe ilitumwa, faili limechukuliwa mara ngapi, na kiungo kinafanya kazi hadi lini. Gusa Kighairi ili kusimamisha kiungo mara moja. Kiungo kilichoghairiwa hakiwezi kuwashwa tena.",
  "help.consignment-note.note4": "Kiungo kinatoa faili mara zisizozidi 25, na hakifungui chochote hati yenyewe isipohifadhiwa tena. Faili ndiyo nakala ya kuhifadhi: kiungo kinasimama, faili halisimami.",
  "help.consignment-note.note5": "Unaweza pia kutengeneza kiungo wewe mwenyewe, kwa mtu anayepaswa kuwa na hati na hana akaunti: mhasibu, kampuni ya bima, upande mwingine. Fungua hati kwenye kumbukumbu zako na, chini ya Viungo vya hati hii, gusa Tengeneza kiungo cha kupitisha. Kisha gusa Kitume au Kinakili, na utume kiungo kwenye mazungumzo, ujumbe au barua pepe yako mwenyewe. Au fungua mojawapo ya nakala zake — inaonekana kama itakavyochapishwa — na uguse Shiriki kiungo hapo, kinachokabidhi kiungo kwa dirisha la kushiriki la simu yako; katika programu ya Shop, “Hati ya mzigo” kwenye mzigo ina Shiriki ile ile hati ikishahifadhiwa. Kiungo kinaonyeshwa mara moja tu, kwa sababu hatuhifadhi nakala yake. Kikipotea, kighairi na utengeneze kingine.",
  "help.consignment-note.note6": "Hati inaweza kuwa na viungo vitano vinavyofanya kazi kwa wakati mmoja. Ghairi kimoja ili kutengeneza kingine. Viungo visivyofanya kazi tena vimekunjwa — gusa ili kuviona — pamoja na nani alitengeneza kila kimoja, kilifunguliwa mara ngapi, na nani alikighairi.",
  "help.consignment-note.note8": "Ukijiendeshea mwenyewe, wewe ndiye msafirishaji kwenye hati, unayetajwa pamoja na anwani yako: toa anwani ya biashara yako kwenye programu ya Driver, au weka pini kwenye kituo unachofanyia kazi. Dereva wa kampuni ya magari kamwe haulizwi — depo ya kampuni ndiyo anwani.",
  "help.consignment-note.note9": "Unachoandika kuhusu bidhaa unapozichukua kinaingia kwenye hati. Kinamfunga mtumaji tu ikiwa mtumaji anakubali; mtumaji anajibu mara moja, akikubali au akipinga kwa maneno yake mwenyewe, na hati inasema lipi.",
  "help.consignment-note.note7": "Biashara haina hifadhi ya kumbukumbu: inapata faili lile lile na viungo vile vile kwenye mzigo wenyewe, katika programu ya Business chini ya Ndani ya nchi › Mizigo.",
  "help.freight-delivery.title": "Fikisha mzigo na urekodi nani aliupokea",
  "help.freight-delivery.summary": "Mzigo umefikishwa mtu anapoupokea. Dereva anarekodi jina lake na picha ya bidhaa zilivyowekwa chini; vyote viwili vinaingia kwenye hati ya mzigo. Hadi bidhaa ziwe kwenye lori, duka bado linaweza kuondoa mzigo.",
  "help.freight-delivery.step1": "Programu ya Driver, getini: weka alama kwenye orodha ya kushusha, andika jina la mtu aliyepokea bidhaa, piga picha yake mahali ulipoziweka chini, na uandike chochote mpokeaji alichosema. Hicho ni kisanduku 24 cha hati ya mzigo. Hesabu vipande pamoja na mpokeaji dhidi ya hesabu ya hati. Ikiwa chochote si kama inavyosema, weka alama kwenye “Mpokeaji amekuta kitu si kama hati inavyosema” na uandike hicho tu: vipande pungufu, vipande zaidi kuliko hati inavyosema, vipande vilivyoharibika (pamoja na picha), vipande ambavyo si bidhaa zilizo kwenye hati, au vipande ambavyo mpokeaji alikataa. Kinaingia kwenye hati kando ya jina la mpokeaji, ufikishaji bado unasimama, na mtumaji anaarifiwa.",
  "help.freight-delivery.step2": "Programu ya Driver, wakati wa kuchukua: ikiwa kuna kitu tayari si sawa na bidhaa kama zilivyokabidhiwa — gunia lililochanika, hesabu pungufu, paleti iliyolowa — kiandike kwenye kisanduku cha maoni ya tahadhari. Hati kisha inaonyesha bidhaa zilikuwa hivyo kabla hujazichukua.",
  "help.freight-delivery.step3": "Programu ya Shop: mzigo uliofikishwa unaonyesha nani aliupokea na lini. Hadi kuchukuliwa unaweza kuondoa mzigo — ufungue, gusa “Ondoa mzigo huu” na useme kwa nini. Dereva aliyekuwa ameuchukua anaarifiwa, na ada uliyolipa inarudi. Ukishakuwa kwenye lori, zungumza na dereva badala yake.",
  "help.freight-delivery.step4": "Programu ya Driver, bidhaa zisipoweza kukabidhiwa: gusa “Sikuweza kufikisha”, sema kilichotokea mlangoni — hakuna mtu, mpokeaji aliukataa, au hukuweza kufika mahali hapo — na “Rekodi jaribio lililoshindikana”. Bidhaa zinabaki nawe, na mtumaji anaarifiwa, ili ampigie mpokeaji simu au akuambie uzipeleke wapi. Zimekataliwa, zote au sehemu: baki na bidhaa zilizokataliwa hadi mtumaji aseme zinakwenda wapi — kurudishwa, mahali pengine, au kuachwa — ndani ya saa 48; unaarifiwa, nawe unaendelea kuzibeba kama mzigo mpya ambao mtumaji analipia. Bila jibu zinarudi zilipochukuliwa, kwa gharama ya mtumaji. Zimekataliwa zote kisha mpokeaji anazichukua hatimaye: zifikishe kama kawaida.",
  "help.freight-delivery.step5": "Programu ya Shop, kitu kikiwa si sawa na kilichofika: fungua mzigo na uguse “Ripoti tatizo la bidhaa” ndani ya siku saba — zimeharibika, pungufu, au hazikupokelewa — pamoja na picha ikiwa unayo. Mwendeshaji wa mtandao analiamua nawe unaonyeshwa sababu yake. Pesa zinaweza kutolewa tu pale mtandao ulitoza ada ya mzigo huo; vinginevyo uamuzi unasema nani alikuwa sahihi na usafirishaji ni wako na wa msafirishaji kuumaliza.",
  "help.freight-delivery.note1": "Hakuna anayetia sahihi kwenye skrini: dereva anarekodi jina, na picha ndiyo uthibitisho. Mzigo uliofikishwa hauwezi kuondolewa — tatizo la bidhaa ni dai, si kughairi.",
  "help.freight-delivery.note2": "Ni pale tu pesa zinapotolewa — chini ya bima ambayo kampuni iliyotoza ada ya mzigo imeitaja — ndipo msafirishaji anazibeba: hadi kiasi alicholipwa kwa safari hiyo ya mzigo na kamwe si zaidi. Kiasi kinachorudishwa kinaonekana kwenye mzigo huo katika mapato ya dereva na ya kampuni ya magari.",
  "help.freight-delivery.note3": "Dai kuhusu mzigo uliofikishwa — umeharibika, pungufu, haukupokelewa — linaingia kwenye hati ya mzigo, na hati inafungiwa pamoja na dai likiwa juu yake: nakala hiyo ndiyo ripoti ya madai ya uharibifu, chini ya Hati, ya kupitisha kwa kiungo. Hakuna mtu wa mtandao anayeamua dai wala kulipa. Ni pale tu kampuni iliyotoza ada ya mzigo imetaja bima ndipo mfanyakazi anaamua, hadi kiasi cha bima hiyo.",
  "help.freight-delivery.note4": "Programu ya Driver, mzigo ambao mtumaji wa mzigo anakulipa moja kwa moja: akishakulipa bei mliyokubaliana, sema “Nimelipwa” — kwenye mzigo, au chini ya Mapato. Umefikishwa na hujalipwa: “Bado sijalipwa” chini ya Mapato, na mtumaji wa mzigo anaarifiwa na kuliona kwenye mzigo. Mtumaji wa mzigo anaweza kujibu mara moja kwamba alilipa, pamoja na rejea unayoweza kuhakiki — msimbo wa M-Pesa, rejea ya benki — na jibu lake linaonyeshwa kando ya neno lako. Pesa zikishakufikia, sema umelipwa. SeeBuyGet haibebi pesa za mizigo hii na haihukumu upande wowote.",
  "help.sender-instructions.title": "Acha maelekezo kwa dereva",
  "help.sender-instructions.summary": "Kila mzigo una kisanduku cha kile mtumaji anataka dereva ajue mlangoni — hati ya mzigo inakiita kisanduku 13. Maelezo huru, mtu wa kuwasiliana naye ambaye dereva anaweza kumpigia, na muda wa ufikishaji. Inaingia kwenye hati na kwa dereva anayechukua mzigo.",
  "help.sender-instructions.step1": "Programu ya Shop, kwenye kaunta: mzigo unapoandikishwa kama mzigo wa usafirishaji — “Iandikishe kama mzigo”, sehemu moja baada ya nyingine, hakuna kinachotoka kabla ya “Andikisha mzigo” kwenye sehemu yake ya mwisho — andika mtu wa kuwasiliana naye wakati wa ufikishaji na simu yake chini ya “Wa kupigia simu”, na chini ya “Siku hiyo” lini unapaswa kufikishwa (“kabla ya 10:00”, “safari ya pili”) na chochote kingine ambacho dereva anahitaji (“geti la upande wa kaskazini”). Vyote ni hiari.",
  "help.sender-instructions.step2": "Programu ya Shop, Mizigo uliyotangaza: fungua mzigo ili kusoma au kubadilisha maelekezo. Hadi bidhaa zichukuliwe unaweza kuyaandika upya. Mzigo ukishakuwa barabarani unaweza tu kuongeza maelekezo; yanaongezwa pamoja na saa, na kile dereva alichokwisha kuambiwa kinabaki kwenye hati.",
  "help.sender-instructions.step3": "Programu ya Driver, Mizigo yangu: maelekezo yako kwenye kadi ya mzigo na tena getini. Simu ni kitufe — gusa ili kupiga.",
  "help.sender-instructions.step4": "Programu ya Fleet, Utumaji: muda wa ufikishaji unaonekana kwenye mzigo, ili ofisi iweze kuchagua imweke nani. Mtu wa kuwasiliana naye haonekani; ni dereva aliye na mzigo tu anayeona nambari ya simu.",
  "help.sender-instructions.step5": "Programu ya Business: fungua mzigo chini ya “Ndani ya nchi › Mizigo”, kisha “Barabarani”. “Mlangoni” inaorodhesha kila jaribio ambalo dereva hakuweza kuukabidhi — lini, na kwa nini — na chini ya “Kwa dereva”, kile dereva anaambiwa. “Badilisha maelekezo” huyaandika upya hadi bidhaa zichukuliwe; baada ya hapo, “Ongeza maelezo kwa dereva”: dereva aliye nao anaarifiwa mara moja, na ulichosema awali kinabaki.",
  "help.sender-instructions.note1": "Maelekezo ni ya mlangoni, si ya pesa — bei inakubaliwa kwenye mzigo wenyewe. Kiungo cha ufuatiliaji kamwe hakiyaonyeshi, na kamwe si simu ya mtu wa kuwasiliana naye.",
  "help.freight-tracking.title": "Fuatilia mzigo na umkadirie dereva",
  "help.freight-tracking.summary": "Kila mzigo una kiungo cha ufuatiliaji — msimbo ule ule ambao hati ya mzigo inabeba kama QR. Yeyote aliye nacho anaona mzigo uko wapi, nani anaubeba, siku unayotarajiwa pale ulipoagizwa kwa siku fulani, na nani aliutia sahihi — na si kingine. Baada ya ufikishaji duka lililotangaza mzigo linamkadiria dereva.",
  "help.freight-tracking.step1": "Programu ya Shop, Mizigo uliyotangaza: fungua mzigo na uguse “Kiungo cha ufuatiliaji”. Kishiriki, au kinakili kwenye ujumbe kwa yeyote anayesubiri bidhaa. Hawahitaji akaunti.",
  "help.freight-tracking.step2": "Programu ya Send, Fuatilia: andika msimbo, au fungua kiungo. Mzigo unapanda ngazi yake yenyewe — unasubiri msafirishaji, umehifadhiwa, barabarani, umefikishwa — pamoja na msafirishaji kama atakavyokuwa mlangoni, mlango wowote ambao hakuna aliyeufungua, na nani aliutia sahihi.",
  "help.freight-tracking.step3": "Programu ya Shop, ukishafikishwa: gusa “Mkadirie dereva”. Nyota kati ya tano, na alama za kilichokwenda vibaya ikiwa kipo. Unahesabiwa katika ukadiriaji wa dereva kama ukadiriaji wa duka kwenye kaunta, uamuzi mmoja kwa kila mzigo, na unaweza kuubadilisha ndani ya siku 30.",
  "help.freight-tracking.note1": "Kiungo hakionyeshi nambari ya simu, bei wala sababu — mzigo ulioondolewa unasema lini, kamwe si kwa nini. Kilicho kati ya mtumaji na msafirishaji kinabaki hapo.",
  "help.freight-tracking.note2": "Yeyote aliyetuma mzigo anaarifiwa unapofikishwa, pamoja na nani aliyeupokea: angalia chini ya kengele.",
  "help.freight-tracking.note3": "Mzigo ulioagizwa kutoka kwa msafirishaji kwa siku fulani unaonyesha siku hiyo tangu mwanzo. Ukishakuwa barabarani unaonyesha pia takriban saa ngapi msafirishaji alipanga kuwa mlangoni. Saa hiyo ni makadirio ya msafirishaji; haionyeshwi kabla mzigo haujawa barabarani, kwa sababu hadi hapo msafirishaji bado anaweza kupanga siku upya. Saa hiyo ikipita mzigo ukiwa barabarani, au siku yake nzima ikipita, ukurasa unasema unachelewa badala ya kuendelea kusema unatarajiwa.",
  "help.manager-dispatch.title": "Mpe dereva mzigo kutoka ofisini",
  "help.manager-dispatch.summary": "Hapo awali mzigo ulimfikia dereva wa kampuni ya magari kwa njia mbili tu: dereva aliukubali, au SeeBuyGet ilimpa. Sasa ofisi ya kampuni ya magari inaweza kumpa mzigo dereva aliye kwenye zamu. Ofisi inaliona soko jinsi dereva huyo angeliona — bei kulingana na gari lake, likipimwa kutoka mahali alipo, kila sababu ya mzigo kutochukuliwa ikiwa imeonyeshwa — kwa hiyo haiwezi kamwe kumpa kitu ambacho dereva hangeweza kukubali.",
  "help.manager-dispatch.step1": "Programu ya Fleet, “Fleet › Ugawaji wa mizigo”, au “Tafuta mzigo” kando ya dereva kwenye kichupo cha Zamu: chagua dereva, chagua umbali wa kuangalia kutoka alipo, na usome soko kwa niaba yake. Atakachopata ni kiwango cha gari lake mwenyewe.",
  "help.manager-dispatch.step2": "Gusa “Mpe <name>”. Bei inathibitishwa wakati huo, mzigo unaingia kwenye orodha ya dereva, anaambiwa, na jina la ofisi linarekodiwa kwenye mzigo. Mzigo uliowekwa kwa ajili ya majadiliano ya bei hauwezi kugawiwa — dereva anaweza kumtumia mtumaji wa mzigo bei kutoka kwenye Soko lake mwenyewe.",
  "help.manager-dispatch.step3": "Programu ya Driver, Mizigo yangu: mzigo uliopewa na ofisi unasema hivyo, na nani alikupa. Unachukuliwa, kubebwa na kufikishwa sawasawa na ule uliokubali, nawe unalipwa vivyo hivyo.",
  "help.manager-dispatch.note1": "Dereva lazima awe kwenye zamu ili apewe mzigo, kwa sababu mzigo unapakiwa kwenye gari na bei ni ya gari hilo. Kile ambacho dereva hangeweza kuchukua — kizito mno, bodi isiyofaa, barabara isiyoweza kuubeba — ofisi haiwezi kulazimisha pia.",
  "help.fleet-orders.title": "Pokea oda kutoka kwa watumaji wa mizigo walio na mkataba nawe",
  "help.fleet-orders.summary": "Mtumaji wa mzigo uliye na mkataba naye anakutumia oda zake moja kwa moja. Haziko kwenye ubao wowote na hakuna msafirishaji mwingine anayeziona; ofisi yako inaweka kila moja kwenye lori.",
  "help.fleet-orders.step1": "“Oda › Rekodi mkataba”: unambebea nani, na nambari ya mkataba. Hakuna bei — unachowatoza kinabaki kwenye mkataba wako mwenyewe.",
  "help.fleet-orders.step2": "Ikiwa mtumaji wa mzigo ana biashara kwenye SeeBuyGet, gusa Watumie msimbo wa kuunganisha na uwapatie msimbo huo. Mmiliki wa biashara yao anauweka mara moja, na kuanzia hapo wanaagiza kwako moja kwa moja. Ikiwa hawako, pakia oda zao wewe mwenyewe kama laha.",
  "help.fleet-orders.step3": "Oda inafunguka kwenye kesho: oda ngapi, uzito kiasi gani, na ngapi bado hazina lori. Chagua siku nyingine juu. Chochote cha siku iliyopita ambacho hakijafikishwa kinabaki kuonekana chini ya Zimechelewa.",
  "help.fleet-orders.step4": "Fungua oda ili uone inachukuliwa wapi, inaenda wapi na siku inayopaswa kufika. Dereva akiwa kwenye zamu unaweza kuiweka kwenye lori lake papo hapo.",
  "help.fleet-orders.note1": "Oda Imechelewa siku iliyopaswa kufika ikishapita bila kufikishwa. Hilo linasomwa kutoka kwenye oda yenyewe, halikadiriwi kamwe.",
  "help.fleet-orders.note2": "Upande wowote unaweza kumaliza mkataba. Hilo linasimamisha oda mpya; zile zilizokwisha wekwa bado ni zako kuzifikisha.",
  "help.fleet-order-sheet.title": "Pakia laha ya oda",
  "help.fleet-order-sheet.summary": "Mtumaji wa mzigo akikutumia oda zake kama lahajedwali, pakia laha hiyo chini ya mkataba wake. Inakaguliwa mstari kwa mstari kabla chochote hakijaongezwa.",
  "help.fleet-order-sheet.step1": "“Oda › Pakia oda” kando ya mkataba. Sema bidhaa zinachukuliwa wapi: andika mahali na upatafute kwenye ramani. Panakumbukwa kwa wakati ujao.",
  "help.fleet-order-sheet.step2": "Chagua laha — kitabu cha Excel chenyewe (.xlsx) au faili la CSV — au nakili visanduku kwenye lahajedwali na uvibandike. Mstari wa kwanza unataja safu: nambari ya oda, bidhaa, uzito, mahali pa kufikisha na tarehe. Pakua kiolezo cha kuwatumia kinaonyesha muundo kamili.",
  "help.fleet-order-sheet.step3": "Gusa Kagua laha. Unaona oda ngapi ziko tayari, ngapi tayari ziko hapa, na kila mstari wenye tatizo, kwa nambari ya mstari wake na kwa maneno.",
  "help.fleet-order-sheet.step4": "Gusa Ongeza oda. Mistari iliyo sahihi inakuwa oda; mingine inaachwa nje. Irekebishe na upakie laha ileile tena — nambari ya oda ambayo tayari iko hapa haiongezwi mara mbili kamwe.",
  "help.fleet-order-sheet.step5": "Anwani ambayo ramani haiijui inaongezwa bila alama na kuwekewa ishara kwenye foleni. Ifungue na uiweke kwenye ramani, la sivyo haiwezi kupangwa.",
  "help.fleet-order-sheet.note1": "Tarehe zinasomwa kama 2026-10-06 au siku kwanza, 06/10/2026. Uzito unaweza kuwa 4000, 4,000 kg au 1.5 t. Tarehe iliyoandikwa kama tarehe kwenye Excel inasomwa kwa muundo wowote ambao kisanduku kinaionyesha.",
  "help.fleet-order-sheet.note2": "Ofisi yako inaweza kuondoa oda iliyoipakia, ikitoa sababu. Oda ambayo mtumaji wa mzigo aliiweka mwenyewe ni yake kuiondoa.",
  "help.fleet-order-sheet.note4": "Kwa ajili ya hati ya mzigo, laha inaweza pia kuwa na safu ya Consignee (anayepokea kila oda kwenye anwani yake), nambari ya UN ya bidhaa hatari, daraja, jina rasmi la usafirishaji na kundi la ufungashaji, na maagizo ya forodha (Customs instructions). Kila kimoja kinasomwa pale tu laha ina safu hiyo; mstari ambao bidhaa zake hatari zimetajwa kwa sehemu tu unasema kinachokosekana na hauingizwi.",
  "help.fleet-order-sheet.note3": "Kwenye kitabu cha Excel, laha ya kwanza ndiyo inasomwa, na unaambiwa jina lake na laha zipi hazikusomwa. Matatizo yanaripotiwa kwa nambari za mistari zinazoonyeshwa na Excel. Faili la zamani la .xls na kitabu chenye nenosiri havisomwi: kihifadhi kama .xlsx au kama CSV. Kitabu kinachozidi 1 MB kinakataliwa kabla hakijatumwa, pamoja na ukubwa wake: baki na laha yenye oda tu, au nakili visanduku na uvibandike.",
  "help.fleet-plan.title": "Panga lori lipi linachukua oda zipi",
  "help.fleet-plan.summary": "Programu inaandaa mpango wa oda za siku kwenye malori yako mwenyewe, na inakuambia unapungukiwa na malori mangapi. Husomeka vizuri zaidi kwenye kompyuta ndogo.",
  "help.fleet-plan.step1": "Oda, chagua siku, kisha Panga siku hii. Mstari wa kwanza ndio jibu: oda ngapi za siku ziko kwenye lori, na malori mangapi zaidi ungehitaji kwa zilizobaki.",
  "help.fleet-plan.step2": "Chini yake, kisichotosha, kikiwa kimepangwa kwa sababu: anwani isiyo kwenye ramani (iwekee pini na upange tena), hakuna nafasi iliyobaki kwenye siku, lori lililo wazi bila dereva, bidhaa ambazo hakuna lori lako linaloweza kuzishughulikia, au oda nzito kuliko lori lako kubwa zaidi (igawe kuwa mizigo).",
  "help.fleet-plan.step3": "Oda nzito kuliko lori lako kubwa zaidi ina Igawe kuwa mizigo. Mpango unasema inaunda mizigo mingapi ya gari lako kubwa zaidi; unaweza kuchagua zaidi. Kisha kila mzigo unakuwa oda yake yenyewe — inapangwa, inawekwa kwenye lori, inatiwa sahihi na kufuatiliwa kando — na mtumaji wa mzigo anaambiwa oda yake inakuja kwa sehemu. Fungua mzigo wowote na uguse Unganisha oda tena ili kutendua, wakati hakuna mzigo ulio kwenye lori au uliokabidhiwa.",
  "help.fleet-plan.step4": "Kisha siku ya kila lori, safari baada ya safari kwa mpangilio inavyoendeshwa. Lori lililoshusha mzigo linaenda kwenye uchukuaji wake unaofuata kutoka lilipo, si kutoka bohari.",
  "help.fleet-plan.step5": "Pale mtumaji wa mzigo alipoomba muda maalum wa ufikishaji, mpango unaulenga: gari linalowahi linasubiri muda huo ufunguke, na mlango unaofungwa mapema zaidi unatembelewa kwanza. Oda isiyoweza kufikia muda wake inapangwa hata hivyo na kuwekewa alama ya itakavyochelewa — au itakavyowahi, siku isipokuwa na nafasi ya kusubiri. Mistari ya kwanza ya mpango inasema ni ngapi.",
  "help.fleet-plan.step6": "Badilisha siku inafungua mipangilio yako: malori yanaondoka lini, siku ndefu zaidi, kasi barabarani, dakika za kupakia na za kukabidhi, na magari yapi yanatoka. Badilisha mojawapo na mpango unaandaliwa upya.",
  "help.fleet-plan.step7": "Kubali mpango huu ukiwa sahihi. Kisha kila oda inaonyesha lori lake, safari yake na takriban wakati itakapofika. Ukifungua mpango baadaye unaonyeshwa kuwa umekubaliwa; Panga siku tena inaandaa mpya, ambao unachukua nafasi yake tu utakapoukubali.",
  "help.fleet-plan.step8": "Siku yenyewe mpango unatumwa wenyewe, safari moja baada ya nyingine: lori linapata safari yake ya kwanza dereva wake anapoanza zamu ndani yake, na inayofuata oda ya mwisho ya safari hiyo ikifikishwa. Tuma safari zinazofuata sasa inafanya vivyo hivyo kwa mkono, na inasema kila lori linafanya nini.",
  "help.fleet-plan.note1": "Kila muda kwenye mpango ni makadirio: umbali kwa kasi moja, pamoja na dakika zisizobadilika kila mahali pa kusimama — vivyo hivyo “kuchelewa” na “kuwahi”. Umbali ni wa barabarani pale huduma ina seva ya kupanga njia, na ni makadirio — mistari iliyonyooka pamoja na nyongeza kwa ajili ya barabara — pale isipokuwa nayo, au isipoweza kufikiwa. Mpango unasema ni upi, chini ya mistari yake ya kwanza.",
  "help.fleet-plan.note2": "Lori hupewa safari moja tu kwa wakati mmoja — kile linachoweza kubeba kwa mara moja. Kila oda inapakiwa kwa ukaguzi uleule kama mzigo wowote (nafasi, vifaa, saa za dereva). Inayokataliwa inabaki kwenye foleni ikiwa na sababu yake.",
  "help.fleet-plan.note3": "Mpango kamwe haupakii lori zaidi ya linavyobeba, kamwe haufanyi siku kuwa ndefu kuliko ulivyoweka (si zaidi ya saa 13), na hautumi magari mengi kuliko madereva ulio nao.",
  "help.fleet-plan.note4": "Mpango utaiacha oda moja nje ikiwa hilo linauwezesha kufikisha nyingine zaidi: mzigo mzito wa mbali unaweza kushikilia lori ambalo oda tatu za karibu zingelijaza. Kamwe hauachi oda moja kwa ajili ya moja. Kilichoachwa nje kinaorodheshwa pamoja na sababu yake na kuhesabiwa kwenye malori unayopungukiwa.",
  "help.fleet-plan.note5": "Muda maalum unasomwa ukiandikwa kama saa: 8-12, 08:00-12:00, before 14:00, after 9, 2pm-5pm. Maneno kama asubuhi, au saa zinazoweza kuwa nusu yoyote ya siku (1-5), hayasomwi: oda inapangwa kwa siku yake tu na inasema hivyo. Hakuna kinachoachwa nje kamwe kwa sababu ya muda maalum.",
  "help.fleet-plan.note6": "Kukubali mpango kunawaambia watumaji wa mizigo mambo mawili, na mpango unasema hivyo juu ya kitufe cha Kubali pale lolote kati ya hayo linapohusika. Mtumaji wa mzigo wa oda ambayo mpango umeiacha nje anaambiwa haiko kwenye gari lolote na kwa nini: hakuna nafasi siku hiyo, hakuna gari linaloweza kuibeba, ni nzito kuliko gari lako kubwa zaidi, au haina alama kwenye ramani. Hawaambiwi kamwe chochote kuhusu madereva wako. Mtumaji wa mzigo wa oda iliyopangwa nje ya muda wake maalum anaambiwa takriban lini, na kwa kiasi gani.",
  "help.fleet-plan.note7": "Kukubali siku ileile tena hakurudii chochote. Mtumaji wa mzigo anaarifiwa tena tu kitu kikibadilika: sababu nyingine ya kuachwa nje, muda uliosogea kwa nusu saa au zaidi, au oda ambayo hatimaye iko kwenye gari. Mtumaji wa mzigo pia anaona, kwenye programu yake, takriban lini kila oda yake iliyopangwa itafika. Yeyote mwenye kiungo cha ufuatiliaji cha oda anaona siku yake, na takriban lini mzigo ukishakuwa barabarani. Oda ambayo ofisi yako yenyewe iliiandika au kuipakia haina mtu wa kuambiwa.",
  "help.fleet-plan.note8": "Kila muda kwenye mpango ni kwa saa ya ofisi yako, na mpango unasema ni ipi chini ya mistari yake ya kwanza. Huiweki wewe: kampuni ya magari inafuata saa za eneo la nchi yake. Pale tu nchi ina zaidi ya moja ndipo ubao unakuomba uchague, mara moja. “Leo” ni leo kwa saa hiyo, kwa hiyo zamu inayoanza muda mfupi baada ya saa sita usiku inapata safari za siku hiyo.",
  "help.fleet-plan.note9": "Kwa saa hiyo, watumaji wa mizigo wanaweza kuambiwa mambo mawili zaidi, na wanaambiwa. Mzigo ukikabidhiwa, mtumaji wake anaambiwa muda na kama ulikuwa ndani ya muda maalum alioomba. Mzigo usipofika nusu saa baada ya muda uliotolewa na mpango wako, mtumaji wake anaambiwa unachelewa, na anaambiwa tena siku nzima ikipita.",
  "help.fleet-plan.note10": "Mtumaji wa mzigo pia anaambiwa oda ya leo isipokuwa kwenye gari lolote saa moja asubuhi kwa saa yako, au saa nzima baada ya kuagizwa ikiwa hiyo ni baadaye. Hiyo ni siku isiyo na mpango uliokubaliwa, oda iliyowekwa baada ya mpango, au oda iliyokosa safari yake. Hakuna anayeambiwa wakati wa usiku. Wanaambiwa tena ikiwa kwenye gari: unapokubali mpango unaoijumuisha, au ukimpa dereva kwa mkono.",
  "help.fleet-plan-adviser.title": "Uliza kuhusu mpango na useme cha kubadilisha",
  "help.fleet-plan-adviser.summary": "Kwenye mpango ambao bado hujaukubali unaweza kumuuliza mshauri wa AI kwa nini mpango uko jinsi ulivyo, au kumwambia kwa maneno yako mwenyewe kinachopaswa kuwa tofauti. Anaeleza, na anamwomba mpangaji tena. Mpangaji bado ndiye anayepanga.",
  "help.fleet-plan-adviser.step1": "Oda, chagua siku, kisha Panga siku hii. Chini ya jibu kuna Uliza kuhusu mpango huu. Andika swali — kwa nini oda hii imeachwa nje, kwa nini lori lile halitoki — na uguse Uliza.",
  "help.fleet-plan-adviser.step2": "Au sema cha kubadilisha: FRT-142 isiwe kwenye KLM 808T, anza saa kumi na mbili asubuhi, lori dogo liko gereji, ruhusu saa 11 za kazi. Mshauri anabadilisha kile mpangaji anachoombwa, mpango unaandaliwa upya, na ubao unaonyesha mpya.",
  "help.fleet-plan-adviser.step3": "Chini ya kila jibu programu inasema kilichobadilishwa, au kwamba hakuna kilichobadilishwa. Mstari huo unatoka kwa mpangaji, si kwa mshauri: vikitofautiana wakati wowote, amini mstari huo na mpango ulio kwenye ubao.",
  "help.fleet-plan-adviser.step4": "Kanuni uliyoiomba inabaki kwenye ubao chini ya Kanuni kwenye mpango huu: oda iliyozuiwa isiwe kwenye gari fulani, au oda iliyowekwa kwenye gari moja tu na si jingine. Inadumu kila mara siku inapopangwa tena. Gusa Ondoa ili kuiondoa.",
  "help.fleet-plan-adviser.step5": "Bila mshauri: fungua Badilisha siku. Chini ya kila mahali pa kusimama, Isiwe kwenye gari hili inazuia oda hiyo isiwe kwenye gari hilo na Hamishia inaiweka kwenye jingine. Oda ambayo mpango uliiacha nje ina Weka kwenye.",
  "help.fleet-plan-adviser.step6": "Hakuna kinachokubaliwa kwa kuuliza. Mpango ukiwa sahihi, bado ni wewe wa kugusa Kubali mpango huu. Kanuni ambazo mpango ulikubaliwa chini yake zinahifadhiwa pamoja nao.",
  "help.fleet-plan-adviser.note1": "Mshauri anaweza kubadilisha magari yanaondoka lini, siku ndefu zaidi, kasi barabarani, dakika za kupakia na za kukabidhi, magari yapi yanatoka, na kanuni kuhusu oda moja na gari moja. Hawezi kubadilisha muda maalum wa ufikishaji au mpangilio wa mahali pa kusimama, wala kugawa oda; anasema hivyo akiulizwa. Anaweza kukuambia oda zipi zimepangwa kuchelewa kwa muda wake maalum na kwa nini.",
  "help.fleet-plan-adviser.note2": "Hawezi kuvunja mipaka ya mpango wenyewe: hakuna gari linalopakiwa zaidi ya linavyobeba, hakuna siku inayozidi saa 13, hakuna magari mengi yanayotoka kuliko madereva ulio nao. Oda iliyowekwa kwenye gari dogo mno kwa ajili yake inaachwa nje, na ubao unasema kanuni ndiyo sababu.",
  "help.fleet-plan-adviser.note3": "Kinachopelekwa kwa huduma ya AI ili kukujibu: maneno yako, na mpango — misimbo ya oda, majina ya watumaji wa mizigo, anwani za ufikishaji, uzito na nambari za usajili. Hakuna nambari za simu wala majina ya watu wa mawasiliano.",
  "help.fleet-plan-adviser.note4": "Mshauri asipowashwa, akiwa na shughuli nyingi au asipoweza kufikiwa, mpango hauathiriki. Badilisha siku bado inafanya mipangilio na magari kwa mkono.",
  "help.fleet-plan-adviser.note5": "Ni AI na anaweza kuelewa swali vibaya. Kamwe haandiki mpango wenyewe, kwa hiyo jibu lisilo sahihi haliwezi kuweka oda kwenye lori.",
  "help.fleet-partners.title": "Toa oda kwa washirika au kwenye ubao wa wazi",
  "help.fleet-partners.summary": "Oda ambazo malori yako hayawezi kuchukua zinaenda kwanza kwa kampuni za magari unazofanya nazo kazi. Ambazo hakuna mshirika anayezichukua zinaweza kwenda kwenye ubao wa wazi.",
  "help.fleet-partners.step1": "“Oda › Washirika”. Taja kampuni ya magari unayoipa kazi na utaonyeshwa msimbo mara moja. Utume kwa ofisi yao; wanauweka chini ya Washirika wao. Kuanzia hapo unaweza kuwapa oda. Yeyote kati yenu anaweza kuumaliza ushirika huo.",
  "help.fleet-partners.step2": "Kutoa oda moja, ifungue na uguse Itoe kwa washirika wako. Kutoa zote ambazo mpango uliziacha nje, gusa Zitoe kwa washirika wako kwenye mpango. Washirika wako wote wanaulizwa kwa pamoja; wa kwanza kuchukua oda ndiye anayeibeba.",
  "help.fleet-partners.step3": "Mshirika anaona anachohitaji ili kuamua: nini, kutoka wapi hadi wapi, uzito kiasi gani, kwa siku gani. Haoni ni mteja wa nani hadi atakapochukua oda.",
  "help.fleet-partners.step4": "Oda iliyotolewa haiko kwenye mpango wako na haiwezi kuwekwa kwenye malori yako. Ondoa ofa ili uibebe wewe mwenyewe.",
  "help.fleet-partners.step5": "Ambayo hakuna mshirika anayeichukua: fungua oda na uguse Iweke kwenye ubao wa wazi. Msafirishaji yeyote aliyekaguliwa anaweza kuichukua kwa bei ya ubao, na unamlipa wewe mwenyewe. Iondoe kwenye ubao wakati hakuna aliyeichukua.",
  "help.fleet-partners.step6": "Oda ambazo mshirika anakupa WEWE ziko juu ya Oda. Chukua moja na ni yako kuipanga na kuibeba; iache na inaenda kwa washirika wao wengine. Ukichukua moja na hatimaye huwezi kuibeba, irudishe ukitoa sababu — kabla haijawekwa kwenye mojawapo ya malori yako.",
  "help.fleet-partners.step7": "Kupitisha. Chini ya Washirika, weka alama kwenye Wanaweza kupitisha oda zangu kwa mshirika wao kando ya mshirika unayemwamini kufanya hivyo. Mshirika huyo kisha anaweza kutoa oda aliyochukua kutoka kwako kwa washirika wake; wa kwanza kuichukua ndiye anayeibeba, na oda inakuonyesha ni nani. Ondoa alama na ofa zao zilizo wazi zinarudishwa. Oda ambayo mtu tayari anaibeba inabaki kwake.",
  "help.fleet-partners.step8": "Ikiwa kampuni ya magari imekuwekea alama hiyo, oda uliyochukua kutoka kwake ina Ipitishe kwa washirika wako. Inaweza kupitishwa mara moja: kampuni inayoichukua inaibeba au inakurudishia, na bado unaweza kuirudisha kwa kampuni ilikotoka.",
  "help.fleet-partners.note1": "Unabaki kuwa msafirishaji ambaye mtumaji wako wa mzigo aliagiza kwake. Hati ya mzigo inamtaja yule aliyebeba bidhaa hasa.",
  "help.fleet-partners.note2": "Unaambiwa mshirika anapochukua oda, hakuna mshirika anapoichukua, na mmoja anapoirudisha na kwa nini. Mshirika anaambiwa unapotoa ofa na unapoiondoa.",
  "help.fleet-partners.note3": "Bei kati yako na mshirika, au msafirishaji kutoka kwenye ubao, ni yako kukubaliana na kulipa. SeeBuyGet haishughulikii.",
  "help.fleet-partners.note4": "Kampuni ya magari inayopewa oda iliyopitishwa inaona ni kampuni ipi inayoitoa — si kampuni ambayo iliagizwa kwake mara ya kwanza, wala ni mteja wa nani, hadi itakapoichukua. Hati ya mzigo inamtaja aliyebeba.",
  "help.papers-that-expire.title": "Huisha bima, ukaguzi au leseni",
  "help.papers-that-expire.summary": "Bima ya gari na cheti chake cha ukaguzi, pamoja na leseni ya dereva, kila kimoja kina tarehe ya mwisho wa matumizi. Siku moja baada ya tarehe hiyo kupita, gari au dereva anasimamishwa hadi uhuishaji urekodiwe — na ofisi ya kampuni ya magari, au kwa mjumbe asiye na kampuni ya magari, na wafanyakazi wa SeeBuyGet. Dereva anatuma picha ya kadi iliyohuishwa kutoka programu ya Driver kwa yule kati ya hao wawili anayerekodi leseni yake. Hati isiyo na tarehe iliyorekodiwa haizimi chochote — na hakuna kinachoifuatilia kwa niaba yako pia.",
  "help.papers-that-expire.step1": "Programu ya Fleet, Magari: rekodi nambari ya bima na tarehe ya mwisho wa matumizi unaposajili gari, au baadaye kwa “Hati” chini ya gari. Ukurasa huohuo ndipo unaporekodi uhuishaji — tarehe mpya ndiyo yote.",
  "help.papers-that-expire.step2": "Programu ya Fleet, Madereva: dereva ambaye leseni yake inakaribia kuisha anatuma picha ya kadi mpya kutoka kwenye programu yake, nayo inafika hapa. Kichupo cha Madereva kinaonyesha ngapi zinasubiri, na madereva hao wanakuja kwanza wakiwa na “Soma kadi”. Ifungue na picha inaonyeshwa kwa ukubwa unaosomeka, pamoja na tarehe waliyosoma kando ya kisanduku: andika tarehe unayoisoma wewe mwenyewe — inayotofautiana na yao inaonyeshwa kabla haijahifadhiwa — au chagua “Haikukubaliwa” na useme kwa nini, kwa sentensi ambayo dereva anaonyeshwa. Bila kadi kutumwa, “Leseni” chini ya dereva inarekodi tarehe kutoka kwenye kadi kama ulivyoiona, kama awali. Ofisi ya kampuni ya magari pekee ndiyo inayoweza kuirekodi; tarehe ipo ili kuchukua nafasi ya neno la dereva mwenyewe kuhusu leseni yake.",
  "help.papers-that-expire.step3": "Programu ya Fleet, Fleet: kadi ya Hati inaorodhesha kilichokwisha muda na kinachoisha ndani ya siku 30, kinachoisha mapema zaidi kwanza, na inasema hati ngapi bado ziko ndani ya muda na ngapi hazina tarehe kabisa.",
  "help.papers-that-expire.step4": "Kila baada ya saa sita SeeBuyGet inakagua kila kampuni ya magari. Gari au dereva aliye tayari kwenye zamu hati inapokwisha muda, zamu inamalizwa na dereva anaambiwa kwa nini, na anwani ya mawasiliano ya kampuni ya magari inatumiwa barua pepe ya kilichosimamishwa na kinachokaribia kuisha — mara moja kwa kila hati, kwa hiyo hati iliyohuishwa inaanza hesabu mpya na barua pepe iliyopuuzwa hairudiwi kamwe.",
  "help.papers-that-expire.step5": "Programu ya Driver: leseni inayokaribia kuisha inatajwa kwenye skrini ya mwanzo kabla ya siku itakayokusimamisha, pamoja na kitufe cha kutuma picha ya kadi iliyohuishwa na tarehe uliyosoma juu yake. Ukiwa katika kampuni ya magari, inaenda kwa ofisi ya kampuni yako, na bado unaweza kuwaonyesha kadi badala yake. Kuituma hakubadilishi chochote bado — ofisi yako inasoma picha hiyohiyo na kurekodi tarehe, au inakuambia kwa nini haikuweza, nawe unaambiwa kwa vyovyote vile. Gari lililosimamishwa linaorodheshwa, linawekewa alama, na linakataliwa wakati wa kuchanganua huku hati husika ikitajwa, ili ujue cha kuiomba ofisi.",
  "help.papers-that-expire.step6": "Programu ya Driver, ukiendesha bila kampuni ya magari: kitufe hichohicho kinatuma kadi kwa wafanyakazi wa SeeBuyGet, wanaosoma picha hiyohiyo na kurekodi tarehe, au wanakuambia kwa nini hawakuweza. Unaambiwa kwa vyovyote vile.",
  "help.papers-that-expire.note1": "Hakuna kinachoandikwa kwenye rekodi kama “limesimamishwa”: tarehe ndiyo swichi kwa pande zote mbili, kwa hiyo uhuishaji unaanza kutumika mara tu unaporekodiwa na hakuna cha kutengua.",
  "help.papers-that-expire.note2": "Kadi aliyotuma dereva inafunguliwa na ofisi ya kampuni ya magari anayoiendeshea na wafanyakazi wa SeeBuyGet — si na kampuni nyingine, wala si na mwenzake. Kadi isiyokubaliwa inafutwa mara moja; iliyorekodiwa inahifadhiwa kama nakala ya leseni yenyewe, na inachukua nafasi ya iliyotangulia.",
  "help.papers-that-expire.note4": "Mtumaji anaweza kuomba msafirishaji mwenye bima. Bima yako ya msafirishaji inahesabika SeeBuyGet ikishaisoma kwenye hati ya bima uliyotuma, pamoja na inachogharamia na hadi kiasi gani kwa kila mzigo: kuanzia hapo hadi itakapokwisha muda, mizigo inayohitaji bima iko wazi kwa madereva wako, na hati zao za mizigo zinataja bima hiyo. Bila hiyo, mizigo hiyo inasema kwa nini imefungwa.",
  "help.papers-that-expire.note5": "Ukiendesha kwa ajili yako mwenyewe, unaweza kuonyesha bima yako mwenyewe: tuma hati yako ya bima kutoka programu ya Driver, chini ya Bima yako. SeeBuyGet ikishaisoma, mizigo ambayo mtumaji wake anahitaji bima iko wazi kwako hadi itakapoisha, na hati zako za mizigo zinaitaja. Dereva wa kampuni ya magari analindwa na bima ya kampuni hiyo.",
  "help.papers-that-expire.note3": "Dereva asiye katika kampuni yoyote ya magari — aliyeondolewa, au aliyeondoka — hana mtu wa kumtumia kadi, na hawezi kuanza zamu hadi kampuni ya magari impe nafasi.",
  "help.hand-back.title": "Rudisha mzigo kabla ya uchukuaji",
  "help.hand-back.summary": "Ofisi inaweza kumpa dereva mzigo, kwa hiyo dereva lazima aweze kukataa — na dereva aliyekubali mzigo anaweza kubadili nia. Hadi bidhaa zipakiwe kwenye gari, mzigo unaweza kurudishwa: unarudi sokoni kana kwamba haukuguswa, malipo ya mtumaji yanarudi, na sababu inabaki kwenye rekodi.",
  "help.hand-back.step1": "Programu ya Driver, Mizigo yangu: fungua mzigo kana kwamba unaenda kuuchukua na uguse “Siwezi kubeba mzigo huu”. Sema sababu — gari kuharibika, barabara, mabadiliko ya mpango — na uurudishe. Unaondoka kwenye orodha yako.",
  "help.hand-back.step2": "Programu ya Shop, Mizigo uliyoweka: mzigo unaonyesha nani aliurudisha, lini na kwa nini, na uko sokoni tena. Malipo yoyote yaliyotozwa kwa ajili yake yamerudi. Hakuna kilichohama.",
  "help.hand-back.step3": "Programu ya Fleet: ofisi iliyompa dereva mzigo inaambiwa pia, pamoja na sababu, na inaweza kumpa mtu mwingine kutoka Ugawaji wa mizigo.",
  "help.hand-back.step4": "Bidhaa zikishapakiwa kwenye gari, hii si njia ya kutokea tena: mzigo uliopokelewa unafikishwa, au mtumaji anaombwa kuuondoa.",
  "help.hand-back.note1": "Kila urudishaji unabaki kwenye rekodi ya mzigo pamoja na sababu ya dereva — si ukadiriaji, wala haufichwi.",
  "help.hours-of-service.title": "Kikomo cha zamu na mapumziko kati ya zamu",
  "help.hours-of-service.summary": "Zamu ina kikomo — saa 13 — baada ya hapo hakuna mzigo mpya unaotolewa, kuonyeshwa kuwa unaweza kuchukuliwa au kupewa dereva, ingawa kilichopakiwa tayari kinafikishwa. Baada ya siku halisi ya kazi ya saa nne au zaidi, zamu inayofuata inasubiri saa 9 za mapumziko.",
  "help.hours-of-service.step1": "Programu ya Driver, skrini ya mwanzo: saa ya zamu inaonyesha saa za kazini ukilinganisha na kikomo. Ukishakivuka, soko linawekea alama kila mzigo, hakuna ofa inayokuja, na skrini ya mwanzo inasema hivyo waziwazi.",
  "help.hours-of-service.step2": "Dereva anaambiwa bila kuuliza: arifa chini ya saa moja kabla ya kikomo, na nyingine kwenye kikomo, ikisema kile ambacho bado ni chake kufanya (kufikisha kilichopakiwa), kisicho chake (chochote kipya), na kwamba zamu inayofuata inaweza kuanza saa 9 baada ya hii kuisha. Saa ya zamu inasema “imebaki chini ya saa moja” katika saa hiyo ya mwisho.",
  "help.hours-of-service.step3": "Programu ya Driver, ukianza zamu mapema mno baada ya siku ya kazi: kuanza kunakataliwa, na ukataaji unasema saa ngapi zimepita tangu zamu ya mwisho iishe na ngapi zinahitajika. Kuunganishwa kwa dakika chache — kuchanganua vibaya, kusogeza gari kidogo — hakuhitaji mapumziko.",
  "help.hours-of-service.step4": "Programu ya Driver, skrini ya mwanzo, baada ya siku ya kazi: skrini ya mwanzo inasema kuanzia lini zamu inayofuata inaweza kuanza, kabla chochote hakijajaribiwa. Bonyeza “Niambie ninapoweza kuanza” ili upate arifa wakati huo. Anayejaribu kuanza mapema mno anaambiwa wakati huo pia. Hakuna mwingine anayeambiwa: kwa siku nyingi za kazi wakati huo huangukia usiku.",
  "help.hours-of-service.step5": "Programu ya Fleet, Dashibodi na Zamu: dereva aliyevuka kikomo anawekewa alama. Ugawaji wa mizigo hautampa mzigo; maliza zamu na umwache apumzike.",
  "help.hours-of-service.step6": "Programu ya Fleet, kengele: ofisi inaambiwa mmoja wa madereva wake anapovuka kikomo, pamoja na gari, ili asipangiwe mzigo mpya.",
  "help.hours-of-service.note1": "Vikomo hivi ni vya SeeBuyGet, kati ya kikomo cha kila siku cha kuendesha cha EU na mapumziko yake ya kila siku yaliyopunguzwa, na si dai kuhusu sheria ya nchi yoyote. Pale mamlaka inapoweka vyake, hivyo ndivyo vinakuwa kikomo.",
  "help.goods-coming-back.title": "Bidhaa zako ziletwe mlangoni kwako",
  "help.goods-coming-back.summary": "Kifurushi chako kilichoondolewa kwenye kituo kinarudi kwenye duka ulipokikabidhi, na duka linaomba malipo ya safari ya kurudi linapokukabidhi. Kikiwa bado kituoni, dereva anaweza kukileta mlangoni kwako badala yake, kikilipiwa kwanza kwa M-Pesa.",
  "help.goods-coming-back.step1": "Programu ya Send, Vifurushi vyangu: kifurushi kinachorudisha bidhaa zako kinasema “Bidhaa zako, zinarudi”. Kikiwa bado kituoni, gusa “Kiletwe mlangoni kwangu badala yake”.",
  "help.goods-coming-back.step2": "Sema mlango wako uko wapi — mtaa, lango, alama inayojulikana — na “Itafute”, au weka pini kwenye ramani mwenyewe. Kisha kiasi cha juu unachomruhusu dereva: kiasi kinapendekezwa, na dereva anaweza kuomba kidogo zaidi, kamwe si zaidi. Na nambari yako ya M-Pesa: dereva anaipigia akifika mlangoni kwako.",
  "help.goods-coming-back.step3": "“Omba … kupitia M-Pesa” na uidhinishe kwenye simu yako. Ikishalipwa, mzigo wa kuja mlangoni kwako unasubiri dereva. Isipolipwa kwa wakati, au “Acha: kinakuja dukani”, nacho kinakuja dukani kama awali; kikiwa bado kituoni, unaweza kuomba tena.",
  "help.goods-coming-back.step4": "Wakati hakuna dereva aliyeuchukua: “Ongeza kiwango cha juu” — kinachoidhinishwa kwenye simu yako vivyo hivyo — au “Kitume kwa … badala yake — pesa zote zinarudi”, nawe unalipia kwa pesa taslimu dukani unapokichukua. Kikishafikishwa, kiasi ambacho dereva alitoza chini ya ulicholipa kinarudi kwenye nambari yako pamoja na malipo yako yajayo.",
  "help.goods-coming-back.note1": "Pale ambapo hakiwezi kuja mlangoni kwako, programu inasema hivyo, na kwa nini, kabla hujalipa chochote. Kisha kinakuja dukani kama awali.",
  "help.call-off-order.title": "Sitisha oda",
  "help.call-off-order.summary": "Duka la mtandaoni linaweza kusitisha oda kutoka kwenye programu yake wakati kifurushi chake hakiko barabarani: bado hakijakabidhiwa, kiko kwenye duka kilipokabidhiwa, au kiko kituoni. Kinachorudi, na gharama yake, vinasemwa kabla chochote hakijafanywa.",
  "help.call-off-order.step1": "Programu ya Store, Oda: fungua oda na uguse “Sitisha oda hii”. Inasema kusitisha kungefanya nini sasa na kunagharimu kiasi gani; hakuna kinachofanywa bado. “Iendelee” inaiacha kama ilivyokuwa.",
  "help.call-off-order.step2": "Bado hakijakabidhiwa, au bado kiko kwenye duka kilipokabidhiwa: “Isitishe”. Inaondolewa, na ulicholipa kwa ajili yake kinarudi kwenye salio lako.",
  "help.call-off-order.step3": "Kiko kituoni: kinarudi kwenye duka kilipokabidhiwa, kama kifurushi kipya kwa bei inayoonyeshwa — “Irudishe kwa …”. Gharama ya kukifikisha kituoni hairudishwi. Kichukue kwenye duka hilo kwa msimbo ulio kwenye oda mpya.",
  "help.call-off-order.step4": "Kiko kituoni, na hakikuwahi kukabidhiwa dukani — kilichukuliwa mlangoni kwako, au kililetwa kituoni kwa wingi: sema kinarudi wapi. Duka, linalotafutwa kwa jina lake au eneo, lililo karibu zaidi kwanza; au “Mlangoni kwako”, kama mzigo: weka kiasi cha juu unachomlipa dereva, na dereva wa kwanza ambaye gari lake linatosha anauchukua kwa bei yake, kamwe si zaidi. Mzigo uko chini ya Zilizotumwa kama mizigo.",
  "help.call-off-order.note1": "Ikiwa barabarani, ikisubiri mnunuzi dukani, au ikiwa imechukuliwa, oda haiwezi kusitishwa: programu inasema kwa nini. Kifurushi kinachokurudishia bidhaa zako hakiwezi kusitishwa pia — kichukue kwenye duka kinakopelekwa.",
  "help.hub-hours.title": "Sema kituo chako kiko wazi lini na jinsi ya kukifikia",
  "help.hub-hours.summary": "Madereva wanaoleta au kuchukua mifuko, na maduka ya mtandaoni yanayoleta vifurushi, wanaona kwenye programu zao kituo chako kiko wazi lini, wamuulizie nani, waingilie wapi, na kitufe cha kukupigia simu.",
  "help.hub-hours.step1": "Programu ya Hub, skrini ya mwanzo: “Saa za kufungua na jinsi ya kukufikia”. Mmiliki wa kituo anagusa “Weka saa zako na mawasiliano” — baadaye, “Badilisha saa au mawasiliano”.",
  "help.hub-hours.step2": "Weka alama kwenye “Wazi siku na saa zilizopangwa” na uweke saa za kila siku. Weka nambari ya kupigiwa — ya dawati lako au ya lango lako, si nambari unayoingia nayo — na, ukipenda, nambari ya pili, wamuulizie nani na waingilie wapi. Kisha “Hifadhi”.",
  "help.hub-hours.step3": "Ukurasa wako wa umma unaonyesha saa zako kwa vyovyote vile. Nambari yako na mahali pa kuingilia viko juu yake tu ukiweka alama kwenye “Onyesha nambari yangu na mahali pa kuingilia kwenye ukurasa wangu wa umma, kwa yeyote”; madereva na maduka ya mtandaoni yanayofanya kazi na kituo chako wanaviona kwenye programu yao kwa vyovyote vile.",
  "help.hub-hours.note1": "Nambari yako haiandikwi kamwe: inaonyeshwa kama kitufe cha kukupigia. Bila saa, hakuna anayeambiwa uko wazi lini; bila nambari, hakuna anayeweza kukupigia kutoka kwenye programu.",
  "help.logistics-directory.title": "Onekana kwenye saraka ya usafirishaji",
  "help.logistics-directory.summary": "Saraka ya umma ya SeeBuyGet inaorodhesha mawakala wa usafirishaji, mawakala wa forodha, bohari za makontena na wasafirishaji wa barabarani ambao hati zao zilikaguliwa na wafanyakazi wetu, kwa kila nchi. Sema kama unaonyeshwa, andika mstari wako mwenyewe, na uchague jinsi watu wanavyokufikia.",
  "help.logistics-directory.step1": "Programu ya Business: “Maelezo ya biashara” › “Kwenye saraka ya usafirishaji”. Programu ya Fleet: skrini ya “Fleet”, kadi ya “Kwenye saraka ya usafirishaji”. Inasema kama unaonyeshwa, na kama sivyo, kwa nini.",
  "help.logistics-directory.step2": "Gusa “Badilisha” na uandike mstari wako: unachofanya na wapi, kwa maneno yako mwenyewe, hadi herufi 240. “Hifadhi”. Unaonyeshwa kama maneno yako mwenyewe, kando ya tulichoona cha kazi yako kwenye SeeBuyGet.",
  "help.logistics-directory.step3": "Jinsi watu wanavyokufikia: biashara inaonyesha taarifa zake za mawasiliano, kwenye skrini hiyohiyo; kampuni ya magari inajaza simu, barua pepe na tovuti inayotaka zionyeshwe chini ya “Badilisha” — acha kisanduku wazi ili kisionyeshe chochote hapo. Simu inaonyeshwa kama kitufe cha Piga simu.",
  "help.logistics-directory.step4": "“Tuondoe kwenye saraka” inakuondoa mara moja; “Tuonyeshe kwenye saraka” inakurudisha, mstari wako ukiwa umehifadhiwa. “Tazama saraka” inafungua ukurasa wa nchi yako.",
  "help.logistics-directory.note1": "Orodha imepangwa kwa alfabeti na hakuna anayelipa ili awemo au awe juu zaidi. Tulichoona kinahesabu kazi iliyofanywa kupitia SeeBuyGet tu, na ukurasa unasema kwamba rekodi fupi si rekodi mbaya.",
  "help.logistics-directory.note2": "Biashara inaonyeshwa wafanyakazi wetu wawili wakishakagua hati zake, na tu ikiwa ni wakala wa usafirishaji, inatoa bidhaa forodhani au inaendesha bohari ya makontena. Kubadilisha jina lake au nambari ya usajili kunaiondoa hadi ikaguliwe tena. Kampuni ya magari inaonyeshwa ikishakuwa hai. Katika biashara, mmiliki pekee ndiye anayebadilisha hili.",
  "help.logistics-directory.note3": "Nchi yako iko kwenye ramani ya saraka pale yalipo maeneo ya kampuni zake. Kwenye programu ya Business, ongeza moja chini ya “Maelezo ya biashara” › “Maeneo yako” › “Eneo jipya”: pini kwenye ramani, au anwani tunayoweza kuipata.",
  "help.logistics-directory.note4": "Unapochagua wakala wa forodha kwa uagizaji au usafirishaji nje, orodha ni ile ya saraka: kila wakala wa forodha aliyekaguliwa na wafanyakazi wetu, maneno yake mwenyewe kando ya tulichoona, hati zilizokaguliwa — kamwe si yule aliyejiondoa kwenye saraka.",
  "help.logistics-directory.note5": "Unatafuta msafirishaji: programu ya Business, “Wasafirishaji wako” › “Tafuta msafirishaji wa barabarani”. Mpigie simu au mwandikie mmoja, au gusa “Omba mkataba”: msafirishaji anaambiwa kwenye programu yake ya Fleet, si zaidi ya mara moja kwa wiki. Akikubali, anagusa “Rekodi mkataba na …” kwenye arifa hiyo, na mkataba unakuja kwako chini ya “Uliyopewa”: mmiliki anagusa “Kubali”, bila msimbo, au “Kataa”. Hakuna kinachokubaliwa kwa kuomba, na msafirishaji anaambiwa jibu lako.",
  "help.logistics-directory.note6": "Yeyote anaweza kutafuta kwenye saraka katika kila nchi, bila akaunti: kwenye ukurasa wa saraka, chini ya “Tafuta kampuni, katika nchi yoyote” — maneno machache, ambayo kila moja lazima lipatikane kwenye kampuni, na inachofanya. Anwani ya ukurasa inahifadhi utafutaji, ili uweze kushirikiwa.",
  "help.hub-carriers.title": "Tuma paleti, vizimba na kreti kwenda vituo vingine",
  "help.hub-carriers.summary": "Sema kituo chako kinahamishia mifuko kwenye nini kwenda vituo vingine, na uvitume pamoja na dereva — ukisema vinarudi vipi: pamoja na dereva, vinaachwa huko, au kwa kazi ya kurudisha unayoiweka.",
  "help.hub-carriers.step1": "Programu ya Hub, skrini ya mwanzo: “Paleti, vizimba na kreti”. Mmiliki wa kituo anagusa “Ongeza aina”: ni nini, jina lake kama watu wako wanavyokiita, urefu wake, upana wake na kimo chake kikiwa kimejazwa kwa sentimita, na kinachoweza kubeba kwa kilo. Idadi ya vifurushi kinachoshika inakokotolewa kutokana na hivyo.",
  "help.hub-carriers.step2": "Chini ya “Vibebeo kati ya vituo”, “Tuma vibebeo pamoja na dereva”: vipi, vingapi, kwenda kituo kipi, na vinarudi vipi — pamoja na dereva katika ziara hiyohiyo, vinaachwa huko ili kituo kingine kivihifadhi au kivitumie, au vinawekwa huko kwa ajili ya kazi ya kurudisha unayoiweka na kuilipia. Changanua pasi ya dereva anayevichukua, kisha “Vitume”. Kituo kingine kinaambiwa cha kufanya navyo.",
  "help.hub-carriers.step3": "Vibebeo ambavyo kituo kingine kilikutumia viko chini ya “Vimekuja kwako”. Fanya kilichoomba: “Vimehesabiwa na kurudishwa kwa dereva”, pamoja na vingapi vilirudi — kamwe si zaidi ya vilivyokuja; “Vimepokelewa: vinabaki hapa”; au “Vimewekwa kando kwa kazi yao ya kurudisha”.",
  "help.hub-carriers.step4": "Vyako vilivyowekwa kwenye kituo kingine viko chini ya “Vyako, viko mbali”. Mmiliki anagusa “Weka kazi ya kurudisha”, pamoja na uzito wake kwa jumla: mzigo kutoka kituo hicho kurudi kwako, kwenye soko kwa ajili ya dereva yeyote na wenye bei kama mzigo wowote. Unamlipa msafirishaji, kati yenu wawili.",
  "help.hub-carriers.note1": "Mmiliki wa kituo pekee ndiye anayesema kituo kinahamishia mifuko kwenye nini na kuweka kazi ya kurudisha. Watu wa sakafuni hutuma vibebeo pamoja na dereva na kuvihesabu vinaporudishwa.",
  "help.hub-space.title": "Sema kituo chako kinaweza kupokea kiasi gani, na kinachotokea kikijaa",
  "help.hub-space.summary": "Nambari mbili zinaiambia SeeBuyGet kituo chako kinaweza kupokea kiasi gani: mifuko mingapi inaweza kukaa sakafuni kwako kwa wakati mmoja, na vifurushi vingapi unavipanga kwa siku. Sakafu yako ikijaa, mifuko mipya inaenda kwenye kituo kingine kinachohudumia maeneo yako, au inasubiri ilipo na kuja yenyewe ukiwa na nafasi.",
  "help.hub-space.step1": "Programu ya Hub, skrini ya mwanzo: kadi ya “Sakafu yako” inasema nafasi ngapi za mifuko ziko wazi kati ya ngapi, vifurushi vingapi unapanga kwa siku, na vingapi umepanga leo. Mmiliki wa kituo anagusa “Weka nafasi yako” — baadaye, “Badilisha”.",
  "help.hub-space.step2": "“Nafasi za mifuko”: hesabu kila mfuko unaoweza kukaa sakafuni kwako kwa wakati mmoja — mifuko iliyoingia na inasubiri kupangwa, na mifuko unayoijaza au inayosubiri dereva. Mfuko mtupu uliokunjwa hauchukui nafasi.",
  "help.hub-space.step3": "“Vifurushi vinavyopangwa kwa siku”: kile watu wako wanachopanga siku ya kawaida. Kisha “Hifadhi”. Kituo kinachojisajili kinasema vyote viwili katika hatua zake za kwanza, na kuvibadilisha hapa siku yoyote.",
  "help.hub-space.step4": "Sakafu ikijaa kadi inasema “Imejaa”. Mifuko mipya ya maeneo yako inaenda kwenye kituo kingine kilichoidhinishwa kinachoyahudumia; pasipo na kituo kama hicho, inasubiri kwenye duka au kituo kinachoishikilia, na kuja kwako yenyewe, ya zamani zaidi kwanza, unapopanga na kutuma mifuko mbele.",
  "help.hub-space.note1": "Dereva anayeleta mifuko harudishwi kamwe: kila mfuko unapokelewa. Ukizidi nafasi zako kadi inasema “Imezidi kujaa” kwa rangi nyekundu — panga, na utume mifuko mbele, ili upate nafasi.",
  "help.hub-space.note2": "Upangaji wa leo ukijaa, kadi inasema “Siku imejaa” nawe unaarifiwa kwenye kengele yako. Mifuko mipya inaenda kwenye kituo kingine chenye nafasi leo pale kilipo; mingine bado inakuja kwako, na kisichopangwa leo kinapangwa kesho.",
  "help.hub-space.note3": "Kwa nini mifuko iliyo njiani inahesabiwa pia: mfuko uliotolewa kwa dereva, au ulio barabarani kuja kwako, unachukua nafasi mara tu unapofika. Kuhesabu tu kilicho sakafuni kungetuma kila mfuko unaosubiri mara tu nafasi moja ikiwa wazi.",
  "help.hub-space.note4": "Mmiliki pekee, akiwa ameingia kama kituo, ndiye anayeweka nambari hizo mbili. Watu wanaofanya kazi sakafuni wanaziona; wafanyakazi wa SeeBuyGet wanaziona na hawabadilishi chochote. Hadi mmiliki azitaje, hakuna kinachozuiliwa kwa ajili ya kituo.",
  "help.bag-waits.title": "Mfuko unaosubiri nafasi kwenye kituo chake",
  "help.bag-waits.summary": "Mfuko uliofungwa unatolewa kwa madereva tu pale kituo unakoenda kina nafasi sakafuni. Kituo hicho, na kila kituo kingine cha eneo hilohilo, vikijaa, mfuko unasubiri ulipo na kuendelea wenyewe nafasi ikipatikana.",
  "help.bag-waits.step1": "Unafunga mfuko kama kawaida. Pale kituo chake kisipokuwa na nafasi, skrini ya mfuko inasema unasubiri hapa nafasi kwenye kituo hicho, na kengele yako inasema hivyo pia — mara moja.",
  "help.bag-waits.step2": "Baki na mfuko sakafuni kwako. Hautolewi kwa dereva yeyote, na hakuna dereva anayeweza kuuchukua kaunta, wakati unasubiri.",
  "help.bag-waits.step3": "Kituo kikiwa na nafasi — kinapanga na kutuma mifuko mbele, au mmiliki wake akiongeza nafasi — mfuko unatolewa kwa madereva tena wenyewe, mfuko uliosubiri muda mrefu zaidi kwanza, na kengele yako inakuambia unaweza kuendelea.",
  "help.bag-waits.note1": "Pale kituo kingine kilichoidhinishwa kinahudumia eneo hilohilo na kina nafasi, mfuko wako unaenda huko badala yake, na hausubiri kabisa. Ofa ya dereva inataja kituo unakoenda.",
  "help.bag-waits.note2": "Kwa nini unasubiri kwako badala ya kwenda hata hivyo: dereva angefika kwenye kituo kisicho na nafasi sakafuni. Mfuko ulio tayari njiani bado unapokelewa kituoni.",
  "help.install-app.title": "Sakinisha programu na upate arifa zake",
  "help.install-app.summary": "Ikishasakinishwa, programu ya SeeBuyGet inafunguka kutoka skrini yako ya mwanzo kama programu nyingine yoyote, skrini nzima, na inaweza kukuambia mara tu kitu kinapokuhitaji. Hadi isakinishwe, upau uliobandikwa juu ya programu unasema “Sakinisha programu ya …”: uguse ili upate hatua, kila moja ikiwa na mchoro.",
  "help.install-app.step1": "Gusa upau wa “Sakinisha programu ya …”, au “Jinsi gani” juu yake. Ukurasa unafunguka wenye hatua zilizopewa nambari kwa ajili ya simu uliyoshika. Simu isiyo sahihi? Chagua Android au iPhone chini ya “Simu yako”.",
  "help.install-app.step2": "Iweke kwenye skrini yako ya mwanzo. Android: gusa “Sakinisha sasa”, kisha Install — au, pale hilo lisipotolewa, menyu ⋮ ya Chrome juu kulia, kisha Install app au Add to Home screen. iPhone, kwenye Safari: Share chini ya skrini, kisha Add to Home Screen, kisha Add.",
  "help.install-app.step3": "Fungua programu kutoka kwenye aikoni yake mpya kwenye skrini yako ya mwanzo — kwenye iPhone, kamwe si kutoka Safari. Gusa “Washa arifa”, kwenye skrini ya mwanzo ya programu au chini ya kengele iliyo juu, na simu ikiuliza, gusa Allow.",
  "help.install-app.step4": "Ulikataa, au hakuna kinachofika? Android: shikilia aikoni ya programu kwa sekunde mbili, gusa ⓘ kwa App info, kisha Notifications, na uziwashe zote. iPhone: fungua Settings, kisha Notifications, kisha programu, na uwashe Allow Notifications.",
  "help.install-app.step5": "Arifa zinachelewa? Simu nyingi za Android huzizuia programu ili kuokoa betri. Kwenye App info ya programu, gusa Battery, kisha Unrestricted — simu nyingine zinasema No restrictions, au Allow background activity.",
  "help.install-app.step6": "Kwenye Android upau unaondoka wenyewe programu ikishasakinishwa. Kwenye iPhone, Safari haiwezi kujua: programu ikishakuwa kwenye skrini yako ya mwanzo, gusa “Iko kwenye skrini yangu ya mwanzo” kwenye ukurasa huo.",
  "help.install-app.note1": "Arifa zilizimwa baadaye, au zinazuiwa na betri? Mwongozo huohuo unabaki ndani ya programu: kwenye programu ya Shop, Hub, Driver, Fleet na Store, gusa picha yako, kisha “Nufaika kikamilifu na programu”; kwenye programu ya Send, “Akaunti”, kisha “Nufaika kikamilifu na programu”; kwenye programu ya Business — ambayo upau wake uko kwenye Muhtasari wake, na unaonekana kwenye kompyuta pia pale Chrome au Edge inaweza kuisakinisha — gusa herufi za mwanzo za jina lako juu kulia, kisha “Nufaika kikamilifu na programu”.",
  "help.install-app.note2": "iPhone inaonyesha arifa za programu tu ikiwa programu ilifunguliwa kutoka kwenye aikoni yake kwenye skrini ya mwanzo, na tu kwenye iOS 16.4 au toleo jipya zaidi.",
  "help.install-app.note3": "Kwenye simu ya Android, shikilia aikoni ya programu iliyosakinishwa ili upate njia zake za mkato, kila moja moja kwa moja hadi skrini moja. Programu ya Shop: pokea kifurushi, kabidhi kifurushi, kabidhi kwa basi, pokea mfuko. Programu ya Hub: vinavyoingia, shusha mfuko, panga vifurushi, pakia mfuko kwenda mbele. Programu ya Driver: tafuta kazi, mizigo yangu, soko la mizigo, mapato. Programu ya Fleet: gawa mzigo, zamu, safari, oda. Programu ya Store: safirisha oda, oda, upakiaji, uwekaji hesabu. Programu ya Send: tuma kifurushi, fuatilia kifurushi, vifurushi vyangu. Programu ya Business: mizigo, mauzo ya nje, bidhaa za kuagiza, vifurushi — sehemu ambayo biashara yako haifanyi inafungua Muhtasari wake.",
  "help.install-app.note4": "Pale simu inapoionyesha, nambari kwenye aikoni ya programu inahesabu arifa ambazo bado hazijasomwa.",
  "help.install-app.note5": "Kwa nini usakinishe: kwenye skrini ya mwanzo programu inafunguka kwa mguso mmoja, skrini nzima, na arifa zake zinakufikia hata ikiwa imefungwa, kwa hiyo huhitaji kuiacha wazi ili uambiwe.",
  "help.install-app.note6": "Kila moja ya programu hizi huhifadhi arifa zake chini ya kengele iliyo juu, zimesomwa au la. Kuruhusu arifa kunaifanya tu simu ikuambie kila moja inapokuja.",
  "help.get-around.title": "Kuzunguka ndani ya programu: kurudi nyuma, kurasa zinazoteleza na kuonyesha upya",
  "help.get-around.summary": "Programu hizi zinafanya kazi kama programu za simu yako zenyewe. Kurudi nyuma kunafunga kilichofunguliwa, kisha kunarudi skrini moja; ukurasa unaoteleza unafungwa kwa kutelezesha kidole chini; na kuvuta chini juu ya skrini kunaileta upya.",
  "help.get-around.step1": "Kurudi nyuma — kitufe cha kurudi nyuma cha simu ya Android au ishara yake — kunafunga kwanza ukurasa unaoteleza au menyu iliyofunguliwa, kisha kunarudi skrini moja nyuma. Kwenye skrini ya kwanza ya programu, bila kitu kilichofunguliwa, kurudi nyuma kunatoka kwenye programu.",
  "help.get-around.step2": "Ukurasa unaoteleza kutoka chini unafungwa kwa kutelezesha kidole chini, au kwa kurudi nyuma.",
  "help.get-around.step3": "Kila skrini inakumbuka ulipofika: rudi kwenye orodha, nawe uko pale ulipoiacha.",
  "help.get-around.step4": "Programu ya Shop, Hub, Driver, Fleet, Store na Send: vuta chini kabisa juu ya skrini kisha uachilie, nayo inaletwa upya.",
  "help.get-around.step5": "Programu ya Business: rekodi ya mzigo iko katika sehemu — “Muhtasari”, “Barabarani”, “Hati”, “Malipo” na “Dai”. Majina yanabaki yamebandikwa juu unaposogeza; gusa moja, au telezesha rekodi kushoto au kulia.",
  "help.get-around.note1": "Katika rekodi ya mzigo, kitone kando ya jina la sehemu kinaonyesha kuna kitu hapo kinachokusubiri. Chochote kinachosubiri jibu lako kiko katika “Muhtasari”.",
  "help.get-around.note2": "Skrini inabaki imewaka unapochanganua, msimbo unapoonyeshwa ili uchanganuliwe, na safari ya dereva ikiwa barabarani.",
  "help.get-around.note3": "Kutelezesha kunakoanzia ukingoni kabisa mwa skrini ni ishara ya simu yenyewe ya kurudi nyuma, si kutelezesha kati ya sehemu.",
  "help.get-around.note4": "Programu ya Shop, Hub, Driver, Fleet, Store na Send: kabla hujaingia, upau ulio chini ya skrini una Rudi, Msaada, Soma kwa sauti na Programu zote. Ukishaingia, vichupo vya programu yenyewe vinachukua nafasi yake.",
  "help.share-seebuyget.title": "Shiriki SeeBuyGet na watu unaofanya nao kazi",
  "help.share-seebuyget.summary": "Kila programu ina kiungo cha SeeBuyGet ambacho ni chako mwenyewe, cha kumtumia yeyote unayependa. Kinafunguka kama kadi yenye picha na mstari kuhusu SeeBuyGet, na yeyote anayejisajili kupitia kiungo hicho anahesabiwa kwako.",
  "help.share-seebuyget.step1": "Programu ya Shop, Hub, Driver, Fleet na Store: gusa picha yako, kisha “Shiriki SeeBuyGet”. Programu ya Business: menyu iliyo chini ya jina lako, kisha “Shiriki SeeBuyGet”.",
  "help.share-seebuyget.step2": "Gusa “Shiriki”: orodha ya kushiriki ya simu yako inafunguka, pamoja na watu unaowasiliana nao na programu zilizo kwenye simu. Chagua utakayemtumia.",
  "help.share-seebuyget.step3": "Au gusa programu chini ya “Au kitume kwa” — WhatsApp, Telegram, ujumbe mfupi, barua pepe — zilizoorodheshwa kwa mpangilio ambao watu hushiriki unakoishi. “Nakili kiungo” kinakinakili, ili ukibandike kwenye gumzo lolote.",
  "help.share-seebuyget.step4": "Pale simu inaporuhusu programu kusoma orodha yako ya mawasiliano, “Chagua kutoka kwa orodha yako ya mawasiliano” inaongeza watu, kila mmoja akiwa na kitufe cha kumtumia ujumbe moja kwa moja.",
  "help.share-seebuyget.note1": "Kiungo chako kinatengenezwa mara moja na kinabaki kilekile, hata ukikituma mara ngapi. Ukurasa unasema watu wangapi walijiunga kupitia kiungo hicho.",
  "help.share-seebuyget.note2": "Mtu anayefungua kiungo chako na kujisajili kwenye simu hiyo ndani ya siku thelathini — kwenye ukurasa wa mwanzo, kwenye programu ya Send au kwenye programu ya Business — anahesabiwa kwako.",
  "help.share-seebuyget.note3": "Programu ya Send: “Akaunti”, kisha “Alika rafiki”. Chagua marafiki kutoka kwa orodha yako ya mawasiliano au ongeza mmoja kwa jina, chagua jinsi ya kutuma, kisha gusa “Tuma” kando ya kila jina.",
  "help.share-seebuyget.note4": "Mawasiliano unayochagua hayatoki kamwe kwenye simu yako: programu inafungua tu programu yako ya ujumbe ikiwa na kiungo ndani yake.",
  "help.fingerprint-unlock.title": "Fungua programu kwa alama ya kidole au uso wako",
  "help.fingerprint-unlock.summary": "Kwenye simu yako mwenyewe, programu inaweza kufunguka kwa alama ya kidole au uso wako, jinsi unavyofungua simu — badala ya PIN yako, au, kwenye programu ya Shop, Hub na Store, nenosiri la akaunti. Inawashwa na kuzimwa chini ya Mipangilio, na PIN au nenosiri hufanya kazi pia kila wakati.",
  "help.fingerprint-unlock.step1": "Fungua Mipangilio — kwenye programu ya Shop, Hub, Driver, Fleet na Store, gusa picha yako, kisha “Mipangilio”; kwenye programu ya Send, “Akaunti › Mipangilio”; kwenye programu ya Business, menyu iliyo chini ya jina lako, kisha “Mipangilio” — na uguse “Fungua kwa alama ya kidole au uso”.",
  "help.fingerprint-unlock.step2": "Andika PIN yako — kwenye programu ya Shop, Hub na Store, nenosiri la akaunti — na uguse “Endelea”. Kisha gusa “Iwashe”, na uipe simu alama ya kidole au uso wako inapoomba.",
  "help.fingerprint-unlock.step3": "Wakati ujao, skrini ya kuingia inatoa “Fungua kwa alama ya kidole au uso” kwanza. Ili kuandika PIN au nenosiri badala yake, gusa “Tumia PIN yangu badala yake” au “Tumia nenosiri langu badala yake”.",
  "help.fingerprint-unlock.step4": "Ili kuizima, fungua mstari uleule kwenye Mipangilio na uguse “Izime, tumia PIN yangu”, au “Izime, tumia nenosiri”. Hakuna kingine kinachoulizwa, nawe unaingia kwa PIN au nenosiri kama awali.",
  "help.fingerprint-unlock.note1": "Inafanya kazi kwenye simu hiyo tu. Kila simu na kivinjari kingine bado kinaomba PIN au nenosiri.",
  "help.fingerprint-unlock.note2": "Alama ya kidole au uso wako haitoki kamwe kwenye simu. SeeBuyGet huhifadhi tu ufunguo unaothibitisha kwamba ni simu hiyo.",
  "help.fingerprint-unlock.note3": "Inazimwa kwenye kila simu PIN au nenosiri likibadilishwa au kuwekwa jingine, na kwenye simu moja simu hiyo ikisahaulishwa chini ya “Mipangilio › Simu na vivinjari”. Kisha skrini ya kuingia inasema “Alama ya kidole au uso imezimwa kwenye simu hii”: andika PIN au nenosiri, na uiwashe tena kwenye Mipangilio ukipenda.",
  "help.fingerprint-unlock.note4": "Programu ya Shop, Hub na Store: yeyote anayeweza kufungua simu — kwa alama ya kidole, uso, au PIN au mchoro wa simu yenyewe — anaweza kisha kuingia kama duka, kituo au duka la mtandaoni bila nenosiri. Iwashe tu kwenye simu ambayo ni yako peke yako.",
  "help.fingerprint-unlock.note5": "Si kwenye simu ya kaunta: kwenye simu ya duka au ya kituo ambapo watu wa kaunta au wa sakafuni huingia, haiwezi kuwashwa, na kama ilikuwa imewashwa, inazimwa mara ya kwanza mmoja wao anapoingia hapo. Mipangilio inasema kwa nini. Kila mmoja wao huingia kama yeye mwenyewe, kwa nambari yake na PIN yake.",
  "help.fingerprint-unlock.note6": "Hakuna mstari kama huo kwenye Mipangilio? Simu haiwezi kukagua alama ya kidole au uso yenyewe, au PIN yako au nenosiri lako bado halifanyi kazi kwenye simu hii. Ingia kama awali.",
  "help.share-into-chat.title": "Tuma kitu kutoka programu nyingine kwenye gumzo",
  "help.share-into-chat.summary": "Maneno au kiungo kutoka programu nyingine — ujumbe wa WhatsApp wenye anwani, kiungo cha ramani, kiungo cha ufuatiliaji — vinaweza kwenda moja kwa moja kwenye mojawapo ya gumzo zako za SeeBuyGet. Kwenye simu ya Android, programu iliyosakinishwa iko kwenye orodha ya kushiriki ya simu.",
  "help.share-into-chat.step1": "Kwenye programu nyingine, gusa kitufe chake cha kushiriki, na uchague programu ya SeeBuyGet kutoka kwenye orodha: Shop, Driver, Fleet, Store au Send.",
  "help.share-into-chat.step2": "Programu inafunguka kwenye “Imeshirikiwa na SeeBuyGet”: ulichoshiriki, na gumzo zako, za karibuni zaidi kwanza. Ili kukibadilisha kabla hakijaenda, gusa “Badilisha maneno”.",
  "help.share-into-chat.step3": "Gusa gumzo chini ya “Itume kwenye gumzo”. Kinaenda huko kama ujumbe kutoka kwako, na kama kila ujumbe hakiwezi kurudishwa.",
  "help.share-into-chat.step4": "Si kwa ajili ya gumzo? Gusa “Nakili”, na ukibandike popote unapokihitaji.",
  "help.share-into-chat.step5": "Picha haitumwi kamwe ikiwa huru. Sema ni nini chini ya “Hii ni nini?”, kisha chagua gumzo kuhusu mzigo wake au kifurushi chake chini ya “Ihifadhi kwenye”: inahifadhiwa kwenye mzigo au kifurushi hicho, ikiwa na alama kwamba imetoka kwenye matunzio.",
  "help.share-into-chat.note1": "Umetoka? Ulichoshiriki kinasubiri kwenye simu kwa saa moja. Ingia, na uchague gumzo.",
  "help.share-into-chat.note2": "Bila mtandao, kinaenda chenyewe mtandao ukirudi, na programu inasema kinasubiri.",
  "help.share-into-chat.note3": "Programu ya Fleet: gumzo ni za madereva wako wenyewe, kwa hiyo nakili kilichoshirikiwa na ukipitishe kwa njia unayotumia kwa kawaida.",
  "help.share-into-chat.note4": "Programu ya Hub haina gumzo, kwa hiyo haimo kwenye orodha ya kushiriki.",
  "help.share-into-chat.note5": "Programu inasema ulichoshiriki hakikuifikia? Funga programu, kisha ukishiriki mara moja zaidi.",
  "help.chat-photos.title": "Tuma picha kwenye gumzo kuhusu mzigo au kifurushi",
  "help.chat-photos.summary": "Picha kwenye gumzo inahifadhiwa kwenye rekodi kwanza, kisha inaonyeshwa. Inahifadhiwa pamoja na mzigo au kifurushi ambacho gumzo linahusu — kama uharibifu, hati au ushahidi — pamoja na alama yake ya utambulisho, na gumzo linaonyesha kadi inayoielekeza. Kisha dai kuhusu mzigo au kifurushi hicho linakuwa nayo.",
  "help.chat-photos.step1": "Kwenye gumzo, gusa “Piga picha” ili kutumia kamera ya programu yenyewe, au “Chagua kutoka kwenye matunzio” kwa picha iliyo tayari kwenye simu yako.",
  "help.chat-photos.step2": "Ukitumia kamera, shika simu bila kutikisika na uguse “Piga picha”. Kamera imezuiwa? Iruhusu programu kutumia kamera, au chagua picha kutoka kwenye matunzio badala yake.",
  "help.chat-photos.step3": "Sema ni nini chini ya “Hii ni nini?”: “Uharibifu”, “Hati” au “Ushahidi”. Ushahidi unauliza wa nini: “Upakiaji”, “Makabidhiano” au “Ufikishaji” — kifurushi kinakabidhiwa na kufikishwa, kamwe hakipakiwi.",
  "help.chat-photos.step4": "Gusa “Ihifadhi kwenye rekodi”. Picha inahifadhiwa kwenye mzigo au kifurushi pamoja na alama yake ya utambulisho, na gumzo linaonyesha kadi inayosema ni wapi. Ikishahifadhiwa, haiwezi kurudishwa.",
  "help.chat-photos.step5": "Gusa kadi ili uone picha, nani aliihifadhi na lini, na alama zake za utambulisho. “Fungua kwenye rekodi ya mzigo”, au ya kifurushi, inaorodhesha kila picha iliyohifadhiwa humo unayoweza kuiona.",
  "help.chat-photos.note1": "Kila picha inasema ilikotoka: “imepigwa ndani ya programu, wakati huo huo” kwa kamera ya programu yenyewe; “kutoka kwenye matunzio, ilipigwa … (tarehe ya simu)” kwa picha iliyo tayari kwenye simu, pamoja na tarehe ambayo simu iliiandika ndani yake; au “kutoka kwenye matunzio, haina tarehe”. Picha kutoka kwenye matunzio inakubaliwa, na inawekewa lebo tu.",
  "help.chat-photos.note2": "Nani anaweza kuifungua: kwa mzigo, aliyeuweka na dereva anayeubeba; kwa kifurushi, duka, mtu anayekichukua na mtumaji wake. Wafanyakazi wa SeeBuyGet wanaona picha za mzigo dai linapowasilishwa, au mtu anaposhiriki ripoti ya gumzo.",
  "help.chat-photos.note3": "Dai linazikusanya. Ripoti ya madai ya uharibifu ya kifurushi inabeba picha zilizohifadhiwa kwenye kifurushi, na zile zilizohifadhiwa baada ya ripoti kuandaliwa zinakabidhiwa kando yake. Dai kuhusu mzigo linaorodhesha picha zilizohifadhiwa kwenye mzigo kwa ajili ya wafanyakazi wanaolisoma.",
  "help.chat-photos.note4": "Bila mtandao, picha inasubiri kwenye simu pamoja na ulichosema ni nini, na inahifadhiwa yenyewe mtandao ukirudi. Kisha kadi yake inasema ilihifadhiwa kwenye simu bila mtandao.",
  "help.chat-photos.note5": "Kwa nini inahifadhiwa kwenye rekodi, si kutumwa tu: picha inayozungushwa kwenye gumzo inaweza kuwa ya kitu chochote. Ikihifadhiwa kwenye mzigo au kifurushi chake — pamoja na nani aliihifadhi, lini, na alama ya utambulisho — inaweza kutegemewa katika dai.",
  "help.chat-photos.note6": "Vitufe vya picha vipo tu kwa mtu anayehusika na mzigo au kifurushi hicho.",
  "help.upload-refused.title": "Picha au faili isipopakiwa",
  "help.upload-refused.summary": "Hakuna picha wala faili linalokataliwa bila maelezo. Picha inapunguzwa ukubwa kwenye simu yako kabla haijatumwa, na PDF au lahajedwali inaonyesha kikomo chake kando ya kitufe cha kuichagua. Moja isipoweza kwenda, programu inasema kwa nini pale ulipoichagua: ukubwa wake, kiwango cha juu, na la kufanya.",
  "help.upload-refused.step1": "Picha, hata ikiwa kubwa kiasi gani: ichague kama ilivyo. Simu inaipunguza ukubwa kabla haijatumwa.",
  "help.upload-refused.step2": "Picha ambayo simu haiwezi kuifungua — baadhi ya kubwa sana, na baadhi ya aina: programu inasema hivyo. Piga picha kwa kamera badala yake, au chagua ndogo zaidi.",
  "help.upload-refused.step3": "PDF kubwa mno: chagua ndogo zaidi, au piga picha ya hati badala yake. Picha inapunguzwa ukubwa; PDF haiwezi.",
  "help.upload-refused.step4": "Lahajedwali kubwa mno: tuma tu laha yenye mistari, au nakili mistari na uibandike badala yake.",
  "help.upload-refused.step5": "Ujumbe wa sauti mkubwa mno: rekodi mfupi zaidi, au andika ujumbe.",
  "help.upload-refused.step6": "“Picha haikutumwa — gusa kujaribu tena”, au “Haikutumwa. Jaribu tena.”: faili lilikuwa sawa, lakini halikutufikia, kwa kawaida kwa kukosa mtandao. Jaribu tena mtandao ukipatikana.",
  "help.upload-refused.note1": "Picha ya wasifu inafanya kazi vivyo hivyo: picha yoyote, inayopunguzwa ukubwa kwenye simu. Isipoweza kutumika, ukurasa unasema kwa nini, chini ya kitufe kilichoichagua.",
  "help.upload-refused.note2": "Faili la aina isiyo sahihi linakataliwa kwa maelezo pia: picha inaombwa pale picha inapohitajika, PDF au picha kwa hati, na lahajedwali kwa laha ya oda au orodha ya ufungashaji.",
  "help.upload-refused.note3": "Kwa nini picha inapunguzwa ukubwa: picha ya kamera ya simu ni megabaiti kadhaa, na ndogo zaidi inaenda haraka zaidi na inatumia data kidogo.",
  "help.car-messages.title": "Sikiliza jumbe zako ukiwa garini",
  "help.car-messages.summary": "Ukiwa na programu ya SeeBuyGet Driver kutoka Google Play na simu yako imeunganishwa na Android Auto, gari linasoma kwa sauti jumbe kutoka kwa watu walio kwenye gumzo zako kuhusu mizigo, nawe unajibu kwa sauti — simu inabaki kwenye kishikio chake.",
  "help.car-messages.step1": "Sakinisha programu ya SeeBuyGet Driver kutoka Google Play, ifungue, na uingie kwa PIN yako kama kawaida.",
  "help.car-messages.step2": "Gusa picha yako, kisha “Mipangilio”, na uguse “Ujumbe ukiwa garini”. Andika PIN yako na uguse “Iwashe”.",
  "help.car-messages.step3": "Simu inafungua skrini ya programu ya Driver yenyewe kwa muda mfupi, kisha inarudi. Mipangilio inasema “Inasubiri simu” hadi simu ijibu, kisha “Imewashwa kwa simu hii”.",
  "help.car-messages.step4": "Ukiwa garini, simu ikiwa imeunganishwa na Android Auto, ujumbe mpya unatangazwa. Liombe gari liusome, kisha ujibu kwa sauti: gari linakusomea jibu lako kabla halijatumwa.",
  "help.car-messages.step5": "Ili kuisimamisha, fungua mstari uleule kwenye Mipangilio na uguse “Izime”. Hakuna kingine kinachoulizwa.",
  "help.car-messages.note1": "Mazungumzo pekee ndiyo yanayosomwa kwa sauti. Ofa za kazi, bei na malipo yanabaki kwenye simu: fungua programu ukishasimama.",
  "help.car-messages.note2": "Ujumbe wa sauti au picha haichezwi garini: gari linasema kimefika, na ufungue programu utakaposimama.",
  "help.car-messages.note3": "Jibu lako linafika kama ujumbe wa maandishi wenye alama “Umetumwa kutoka garini”, na linakataliwa kwa sababu zilezile kama la kuandikwa — mazungumzo yaliyofungwa, au jumbe nyingi mno ndani ya saa moja. Kisha gari linasema halikutumwa.",
  "help.car-messages.note4": "Hakuna mstari wa “Ujumbe ukiwa garini” kwenye Mipangilio? Upo tu kwenye programu ya SeeBuyGet Driver kutoka Google Play, si kwenye kivinjari, na tu kwenye simu ambayo PIN yako inafanya kazi. Kwenye simu yenye Android 8 au ya zamani zaidi inasema “Inahitaji Android 9 au mpya zaidi.”: sehemu ya gari haifanyi kazi hapo.",
  "help.car-messages.note5": "Inajizima yenyewe PIN yako ikibadilishwa au kuwekwa nyingine, simu hii ikisahaulishwa chini ya “Mipangilio › Simu na vivinjari”, au nambari yako ikihamishwa. Iwashe tena kwenye Mipangilio.",
  "help.car-messages.note6": "Kwa nini ni salama kuiacha imewashwa: Firebase ya Google huiamsha simu tu kusema kwamba gumzo lina habari mpya — kamwe si maneno, na kamwe si nani aliyeyaandika. Kisha simu inaleta ujumbe kutoka SeeBuyGet.",
  "help.car-messages.note7": "Ikiwa imewashwa, ujumbe wa gumzo unakuja kwenye simu mara moja — kama arifa ya gari lenyewe, yenye Jibu na Weka kuwa imesomwa — na si pia kama arifa kutoka kwenye programu. Bado uko kwenye kengele.",
};
